    BaniLine(id = "sidha-gosht-8", gurmukhi = "ਸਾਚ ਸਬਦ ਬਿਨੁ; ਮੁਕਤਿ. ਨ ਕੋਇ ॥੧॥ ਰਹਾਉ ॥", transliteration = "saach sabad bin; mukat. na koi ||1|| rhaau ||", translation = "Without the True Word of the Shabad, no one finds liberation. ||1||Pause||", hindi = "साच सबद बिनु; मुकति. न कोइ ॥१॥ रहाउ ॥", punjabi = "(ਸਤਿਗੁਰੂ ਦੇ) ਸੱਚੇ ਸ਼ਬਦ ਤੋਂ ਬਿਨਾ (\"ਦੁਨੀਆ ਸਾਗਰ ਦੁਤਰ ਤੋਂ\") ਖ਼ਲਾਸੀ ਨਹੀਂ ਹੁੰਦੀ ॥੧॥ ਰਹਾਉ ॥", wordMeaning = "ਰਹਾਉ = ਠਹਰ ਜਾਓ, (ਭਾਵ), ਇਸ ਸਾਰੀ ਲੰਮੀ ਬਾਣੀ ਦਾ 'ਮੁੱਖ ਭਾਵ' ਇਹਨਾਂ ਦੋ ਤੁਕਾਂ ਵਿਚ ਹੈ ॥੧॥ ਰਹਾਉ ॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-9", gurmukhi = "ਕਵਨ ਤੁਮੇ. ਕਿਆ ਨਾਉ ਤੁਮਾਰਾ; ਕਉਨੁ ਮਾਰਗੁ. ਕਉਨੁ ਸੁਆਓ ॥", transliteration = "kavan tume. kiaa naau tumaaraa; kaun maarag. kaun suaao ||", translation = "Who are you? What is your name? What is your way? What is your goal?", hindi = "कवन तुमे. किआ नाउ तुमारा; कउनु मारगु. कउनु सुआओ ॥", punjabi = "(ਚਰਪਟ ਜੋਗੀ ਨੇ ਪੁੱਛਿਆ-) ਤੁਸੀ ਕੌਣ ਹੋ? ਤੁਹਾਡਾ ਕੀਹ ਨਾਮ ਹੈ? ਤੁਹਾਡਾ ਕੀਹ ਮਤ ਹੈ? (ਉਸ ਮਤ ਦਾ) ਕੀਹ ਮਨੋਰਥ ਹੈ?", wordMeaning = "ਤੁਮ੍ਹੇ = ਅੱਖਰ 'ਮ' ਦੇ ਨਾਲ ਅੱਧਾ 'ਹ' ਹੈ। ਮਾਰਗੁ = ਰਸਤਾ, ਪੰਥ, ਮਤ। ਸੁਆਓ = ਮਨੋਰਥ, ਪ੍ਰਯੋਜਨ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-10", gurmukhi = "ਸਾਚੁ ਕਹਉ ਅਰਦਾਸਿ ਹਮਾਰੀ; ਹਉ. ਸੰਤ ਜਨਾ ਬਲਿ ਜਾਓ ॥", transliteration = "saach kahau ardaas hmaaree; hau. sant jnaa bal jaao ||", translation = "We pray that you will answer us truthfully; we are a sacrifice to the humble Saints.", hindi = "साचु कहउ अरदासि हमारी; हउ. संत जना बलि जाओ ॥", punjabi = "(ਗੁਰੂ ਨਾਨਕ ਦੇਵ ਜੀ ਦਾ ਉੱਤਰ-) ਮੈਂ ਸਦਾ ਕਾਇਮ ਰਹਿਣ ਵਾਲੇ ਪ੍ਰਭੂ ਨੂੰ ਜਪਦਾ ਹਾਂ, ਸਾਡੀ (ਪ੍ਰਭੂ ਅਗੇ ਹੀ ਸਦਾ) ਅਰਦਾਸਿ ਹੈ ਤੇ ਮੈਂ ਸੰਤ ਜਨਾਂ ਤੋਂ ਸਦਕੇ ਜਾਂਦਾ ਹਾਂ (ਬੱਸ! ਇਹ ਮੇਰਾ ਮਤ ਹੈ)।", wordMeaning = "ਕਹਉ = ਮੈਂ ਕਹਿੰਦਾ ਹਾਂ, ਮੈਂ ਜਪਦਾ ਹਾਂ। ਹਉ = ਮੈਂ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-11", gurmukhi = "ਕਹ ਬੈਸਹੁ. ਕਹ ਰਹੀਐ ਬਾਲੇ; ਕਹ ਆਵਹੁ. ਕਹ ਜਾਹੋ ॥", transliteration = "kah baisah. kah rheeai baale; kah aavah. kah jaaho ||", translation = "Where is your seat? Where do you live, boy? Where did you come from, and where are you going?", hindi = "कह बैसहु. कह रहीऐ बाले; कह आवहु. कह जाहो ॥", punjabi = "(ਚਰਪਟ ਦਾ ਪ੍ਰਸ਼ਨ) ਹੇ ਬਾਲਕ! ਤੁਸੀ ਕਿਸ ਦੇ ਆਸਰੇ ਸ਼ਾਂਤ-ਚਿੱਤ ਹੋ? ਤੁਹਾਡੀ ਸੁਰਤ ਕਿਸ ਵਿਚ ਜੁੜਦੀ ਹੈ? ਕਿੱਥੋਂ ਆਉਂਦੇ ਹੋ? ਕਿੱਥੇ ਜਾਂਦੇ ਹੋ?", wordMeaning = "ਕਹ = ਕਿਥੇ? ਕਿਸ ਦੇ ਆਸਰੇ? ਬੈਸਹੁ = (ਤੁਸੀ) ਬੈਠਦੇ ਹੋ, ਸ਼ਾਂਤ-ਚਿੱਤ ਹੁੰਦੇ ਹੋ। ਬਾਲੇ = ਹੇ ਬਾਲਕ! ਕਹ = ਕਿਥੇ?", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-12", gurmukhi = "ਨਾਨਕੁ ਬੋਲੈ. ਸੁਣਿ ਬੈਰਾਗੀ; ਕਿਆ ਤੁਮਾਰਾ ਰਾਹੋ ॥੨॥", transliteration = "naanak bolai. sun bairaagee; kiaa tumaaraa raaho ||2||", translation = "Tell us, Nanak - the detached Siddhas wait to hear your reply. What is your path?\" ||2||", hindi = "नानकु बोलै. सुणि बैरागी; किआ तुमारा राहो ॥२॥", punjabi = "ਨਾਨਕ ਆਖਦਾ ਹੈ ਕਿ ਚਰਪਟ ਨੇ ਪੁੱਛਿਆ- ਹੇ ਸੰਤ! ਸੁਣ, ਤੇਰਾ ਕੀਹ ਮਤ ਹੈ? ॥੨॥", wordMeaning = "ਨਾਨਕੁ ਬੋਲੈ = ਨਾਨਕ ਆਖਦਾ ਹੈ (ਕਿ ਜੋਗੀ ਨੇ ਪੁਛਿਆ)। ਬੈਰਾਗੀ = ਹੇ ਬੈਰਾਗੀ! ਹੇ ਵੈਰਾਗਵਾਨ! ਹੇ ਸੰਤ ਜੀ! ਸਾਚੁ = ਸਦਾ ਕਾਇਮ ਰਹਿਣ ਵਾਲਾ ਪ੍ਰਭੂ। ਰਾਹੋ = ਰਾਹੁ, ਮਤ, ਮਾਰਗ ॥੨॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-13", gurmukhi = "ਘਟਿ ਘਟਿ ਬੈਸਿ. ਨਿਰੰਤਰਿ ਰਹੀਐ; ਚਾਲਹਿ ਸਤਿਗੁਰ ਭਾਏ ॥", transliteration = "ghat ghat bais. nirantar rheeai; chaalah stigur bhaae ||", translation = "He dwells deep within the nucleus of each and every heart. This is my seat and my home. I walk in harmony with the Will of the True Guru.", hindi = "घटि घटि बैसि. निरंतरि रहीऐ; चालहि सतिगुर भाए ॥", punjabi = "(ਸਤਿਗੁਰੂ ਜੀ ਦਾ ਉੱਤਰ-) (ਹੇ ਚਰਪਟ!) ਸਰਬ-ਵਿਆਪਕ ਪ੍ਰਭੂ (ਦੀ ਯਾਦ) ਵਿਚ ਜੁੜ ਕੇ ਸਦਾ ਸ਼ਾਂਤ-ਚਿੱਤ ਰਹੀਦਾ ਹੈ। ਅਸੀਂ ਸਤਿਗੁਰੂ ਦੀ ਮਰਜ਼ੀ ਵਿਚ ਚੱਲਦੇ ਹਾਂ।", wordMeaning = "ਘਟਿ = ਘਟ ਵਿਚ, ਸਰੀਰ ਵਿਚ। ਘਟਿ ਘਟਿ = ਹਰੇਕ ਘਟ ਵਿਚ, ਹਰੇਕ ਸਰੀਰ ਵਿਚ (ਭਾਵ, ਹਰੇਕ ਘਟ ਵਿਚ ਵਿਆਪਕ ਪ੍ਰਭੂ ਦੀ ਯਾਦ ਅੰਦਰ)। ਬੈਸਿ = ਬੈਠ ਕੇ, ਟਿਕ ਕੇ। ਨਿਰੰਤਰਿ = ਨਿਰ-ਅੰਤਰਿ, ਇਕ-ਰਸ, ਸਦਾ। ਅੰਤਰ = ਵਿੱਥ, ਵਕਫ਼ਾ। ਰਹੀਐ = ਰਹੀਦਾ ਹੈ, ਸੁਰਤ ਜੁੜਦੀ ਹੈ। ਭਾਏ = ਭਾਉ ਵਿਚ, ਮਰਜ਼ੀ ਵਿਚ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-14", gurmukhi = "ਸਹਜੇ ਆਏ. ਹੁਕਮਿ ਸਿਧਾਏ; ਨਾਨਕ. ਸਦਾ ਰਜਾਏ ॥", transliteration = "sahje aae. hukam sidhaae; naanak. sdaa rjaae ||", translation = "I came from the Celestial Lord God; I go wherever He orders me to go. I am Nanak, forever under the Command of His Will.", hindi = "सहजे आए. हुकमि सिधाए; नानक. सदा रजाए ॥", punjabi = "ਹੇ ਨਾਨਕ! ਪ੍ਰਭੂ ਦੇ ਹੁਕਮ ਵਿਚ ਸੁਤੇ ਹੀ (ਜਗਤ ਵਿਚ) ਆਏ, ਹੁਕਮ ਵਿਚ ਵਿਚਰ ਰਹੇ ਹਾਂ, ਸਦਾ ਉਸ ਦੀ ਰਜ਼ਾ ਵਿਚ ਹੀ ਰਹਿੰਦੇ ਹਾਂ।", wordMeaning = "ਸਹਜੇ = ਸੁਤੇ ਹੀ। ਹੁਕਮਿ = ਹੁਕਮ ਵਿਚ। ਸਿਧਾਏ = ਫਿਰਦੇ ਹਾਂ। ਰਜਾਏ = ਰਜ਼ਾ ਵਿਚ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-15", gurmukhi = "ਆਸਣਿ ਬੈਸਣਿ ਥਿਰੁ ਨਾਰਾਇਣੁ; ਐਸੀ ਗੁਰਮਤਿ ਪਾਏ ॥", transliteration = "aasan baisan thir naaraain; aisee guramat paae ||", translation = "I sit in the posture of the eternal, imperishable Lord. These are the Teachings I have received from the Guru.", hindi = "आसणि बैसणि थिरु नाराइणु; ऐसी गुरमति पाए ॥", punjabi = "(ਪੱਕੇ) ਆਸਣ ਵਾਲਾ, (ਸਦਾ) ਟਿਕੇ ਰਹਿਣ ਵਾਲਾ ਤੇ ਕਾਇਮ ਰਹਿਣ ਵਾਲਾ ਪ੍ਰਭੂ ਆਪ ਹੀ ਹੈ, ਅਸਾਂ ਇਹੀ ਗੁਰ-ਸਿੱਖਿਆ ਲਈ ਹੈ।", wordMeaning = "ਆਸਣਿ = ਆਸਣ ਵਾਲਾ। ਬੈਸਣਿ = ਬੈਠਣ ਵਾਲਾ। ਥਿਰੁ = ਕਾਇਮ ਰਹਿਣ ਵਾਲਾ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-16", gurmukhi = "ਗੁਰਮੁਖਿ ਬੂਝੈ. ਆਪੁ ਪਛਾਣੈ; ਸਚੇ ਸਚਿ ਸਮਾਏ ॥੩॥", transliteration = "gurmukh boojhai. aap pchhaanai; sche sach smaae ||3||", translation = "As Gurmukh, I have come to understand and realize myself; I merge in the Truest of the True. ||3||", hindi = "गुरमुखि बूझै. आपु पछाणै; सचे सचि समाए ॥३॥", punjabi = "ਗੁਰੂ ਦੇ ਦੱਸੇ ਰਾਹ ਤੇ ਤੁਰਨ ਵਾਲਾ ਮਨੁੱਖ ਗਿਆਨਵਾਨ ਹੋ ਜਾਂਦਾ ਹੈ, ਆਪਣੇ ਆਪ ਨੂੰ ਪਛਾਣਦਾ ਹੈ, ਤੇ, ਸਦਾ ਸੱਚੇ ਪ੍ਰਭੂ ਵਿਚ ਜੁੜਿਆ ਰਹਿੰਦਾ ਹੈ ॥੩॥", wordMeaning = "ਬੂਝੈ = ਸਮਝ ਵਾਲਾ ਬਣਦਾ ਹੈ, ਗਿਆਨਵਾਨ ਹੁੰਦਾ ਹੈ। ਆਪੁ = ਆਪਣੇ ਆਪ ਨੂੰ ॥੩॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-17", gurmukhi = "ਦੁਨੀਆ ਸਾਗਰੁ. ਦੁਤਰੁ ਕਹੀਐ; ਕਿਉ ਕਰਿ ਪਾਈਐ ਪਾਰੋ ॥", transliteration = "duneeaa saagar. dutar kheeai; kiu kar paaeeai paaro ||", translation = "\"The world-ocean is treacherous and impassable; how can one cross over?\"", hindi = "दुनीआ सागरु. दुतरु कहीऐ; किउ करि पाईऐ पारो ॥", punjabi = "(ਚਰਪਟ ਦਾ ਪ੍ਰਸ਼ਨ) ਜਗਤ (ਇਕ ਐਸਾ) ਸਮੁੰਦਰ ਕਿਹਾ ਜਾਂਦਾ ਹੈ ਜਿਸ ਨੂੰ ਤਰਨਾ ਔਖਾ ਹੈ, (ਇਸ ਸਮੁੰਦਰ ਦਾ) ਪਾਰਲਾ ਕੰਢਾ ਕਿਵੇਂ ਲੱਭੇ?", wordMeaning = "ਦੁਤਰੁ = ਦੁੱਤਰੁ, ਦੁਸ-ਤੁਰ, ਜਿਸ ਨੂੰ ਤਰਨਾ ਔਖਾ ਹੈ। ਕਿਉਕਰਿ = ਕਿਵੇਂ? ਕਿਸ ਤਰ੍ਹਾਂ? ਪਾਰੋ = ਪਾਰਲਾ ਕੰਢਾ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-18", gurmukhi = "ਚਰਪਟੁ ਬੋਲੈ, ਅਉਧੂ ਨਾਨਕ; ਦੇਹੁ ਸਚਾ ਬੀਚਾਰੋ ॥", transliteration = "charapat bolai, audhoo naanak; deh schaa beechaaro ||", translation = "Charpat the Yogi says, \"O Nanak, think it over, and give us your true reply.\"", hindi = "चरपटु बोलै, अउधू नानक; देहु सचा बीचारो ॥", punjabi = "ਚਰਪਟ ਆਖਦਾ ਹੈ (ਭਾਵ, ਚਰਪਟ ਨੇ ਆਖਿਆ) ਹੇ ਵਿਰਕਤ ਨਾਨਕ! ਠੀਕ ਵਿਚਾਰ ਦੱਸ।", wordMeaning = "ਨਾਨਕ = ਹੇ ਨਾਨਕ! ਅਉਧੂ = ਵਿਰਕਤ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-19", gurmukhi = "ਆਪੇ ਆਖੈ ਆਪੇ ਸਮਝੈ; ਤਿਸੁ ਕਿਆ ਉਤਰੁ ਦੀਜੈ ॥", transliteration = "aape aakhai aape samjhai; tis kiaa utar deejai ||", translation = "What answer can I give to someone, who claims to understand himself?", hindi = "आपे आखै आपे समझै; तिसु किआ उतरु दीजै ॥", punjabi = "ਉੱਤਰ: (ਜੋ ਮਨੁੱਖ ਜੋ ਕੁਝ) ਆਪ ਆਖਦਾ ਹੈ ਤੇ ਆਪ ਹੀ (ਉਸ ਨੂੰ) ਸਮਝਦਾ (ਭੀ) ਹੈ ਉਸ ਨੂੰ (ਉਸ ਦੇ ਪ੍ਰਸ਼ਨ ਦਾ) ਉੱਤਰ ਦੇਣ ਦੀ ਲੋੜ ਨਹੀਂ ਹੁੰਦੀ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-20", gurmukhi = "ਸਾਚੁ ਕਹਹੁ. ਤੁਮ ਪਾਰਗਰਾਮੀ; ਤੁਝੁ. ਕਿਆ ਬੈਸਣੁ ਦੀਜੈ ॥੪॥", transliteration = "saach kahah. tum paaragraamee; tujh. kiaa baisan deejai ||4||", translation = "I speak the Truth; if you have already crossed over, how can I argue with you? ||4||", hindi = "साचु कहहु. तुम पारगरामी; तुझु. किआ बैसणु दीजै ॥४॥", punjabi = "(ਇਸ ਵਾਸਤੇ, ਹੇ ਚਰਪਟ!) ਤੇਰੇ (ਪ੍ਰਸ਼ਨ) ਵਿਚ ਕੋਈ ਉਕਾਈ ਲੱਭਣ ਦੀ ਲੋੜ ਨਹੀਂ, (ਉਂਝ ਉੱਤਰ ਇਹ ਹੈ ਕਿ) ਸਦਾ ਕਾਇਮ ਰਹਿਣ ਵਾਲੇ ਪ੍ਰਭੂ ਨੂੰ ਜਪੋ ਤਾਂ ਤੁਸੀਂ (ਇਸ 'ਦੁਤਰੁ ਸਾਗਰੁ' ਤੋਂ) ਪਾਰ ਲੰਘ ਜਾਉਗੇ ॥੪॥", wordMeaning = "ਸਾਚੁ ਕਹਹੁ = ਸਦਾ ਕਾਇਮ ਰਹਿਣ ਵਾਲੇ ਪ੍ਰਭੂ ਨੂੰ ਜਪੋ। ਪਾਰਗਰਾਮੀ = (ਸੰਸਾਰ-ਸਮੁੰਦਰ ਤੋਂ) ਪਾਰ ਲੰਘਣ ਵਾਲਾ। ਬੈਸਣੁ = (ਸੰ: ਵ੍ਯਸਨ) ਉਕਾਈ, ਨੁਕਸ। {ਵ੍ਯਸਨ = ਪ੍ਰਹਾਰੀ (ਸੰ: ਵ੍ਯਸਨ ਪ੍ਰਹਾਰਿਨ), ਉਹ ਜੋ ਚਰਚਾ ਵਿਚ ਆਪਣੇ ਵਿਰੋਧੀ ਦੀ ਕਿਸੇ ਉਕਾਈ ਤੇ ਚੋਟ ਮਾਰਦਾ ਹੈ} ॥੪॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-21", gurmukhi = "ਜੈਸੇ ਜਲ ਮਹਿ. ਕਮਲੁ ਨਿਰਾਲਮੁ; ਮੁਰਗਾਈ ਨੈ ਸਾਣੇ ॥", transliteration = "jaise jal mah. kamal niraalam; murgaaee nai saane ||", translation = "The lotus flower floats untouched upon the surface of the water, and the duck swims through the stream;", hindi = "जैसे जल महि. कमलु निरालमु; मुरगाई नै साणे ॥", punjabi = "ਜਿਵੇਂ ਪਾਣੀ ਵਿਚ (ਉੱਗਿਆ ਹੋਇਆ) ਕੌਲ ਫੁੱਲ (ਪਾਣੀ ਨਾਲੋਂ) ਨਿਰਾਲਾ ਰਹਿੰਦਾ ਹੈ, ਜਿਵੇਂ ਨਦੀ ਵਿਚ (ਤਰਦੀ) ਮੁਰਗਾਈ (ਭਾਵ, ਉਸ ਦੇ ਖੰਭ ਪਾਣੀ ਨਾਲ ਨਹੀਂ ਭਿੱਜਦੇ, ਇਸੇ ਤਰ੍ਹਾਂ)", wordMeaning = "ਨਿਰਾਲਮੁ = ਨਿਰਾਲੰਭ, (ਨਿਰ-ਆਲੰਭ) ਨਿਰ-ਆਸਰਾ, ਨਿਰਾਲਾ, (ਨਿਰ-ਆਲਯ) ਵੱਖਰਾ। ਨੈ = ਨਈ, ਨਦੀ ਵਿਚ। ਸਾਣੇ = ਜਿਵੇਂ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-22", gurmukhi = "ਸੁਰਤਿ ਸਬਦਿ. ਭਵ ਸਾਗਰੁ ਤਰੀਐ; ਨਾਨਕ. ਨਾਮੁ ਵਖਾਣੇ ॥", transliteration = "surat sabad. bhav saagar treeai; naanak. naam vkhaane ||", translation = "with one's consciousness focused on the Word of the Shabad, one crosses over the terrifying world-ocean. O Nanak, chant the Naam, the Name of the Lord.", hindi = "सुरति सबदि. भव सागरु तरीऐ; नानक. नामु वखाणे ॥", punjabi = "ਹੇ ਨਾਨਕ! ਗੁਰੂ ਦੇ ਸ਼ਬਦ ਵਿਚ ਸੁਰਤ (ਜੋੜ ਕੇ) ਨਾਮ ਜਪਿਆਂ ਸੰਸਾਰ-ਸਮੁੰਦਰ ਤਰ ਸਕੀਦਾ ਹੈ।", wordMeaning = "ਸਬਦਿ = ਸ਼ਬਦ ਵਿਚ। ਵਖਾਣੇ = ਵਖਾਣਿ, ਵਖਾਣ ਕੇ, ਜਪ ਕੇ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-23", gurmukhi = "ਰਹਹਿ ਇਕਾਂਤਿ. ਏਕੋ ਮਨਿ ਵਸਿਆ; ਆਸਾ ਮਾਹਿ ਨਿਰਾਸੋ ॥", transliteration = "rahah ikaant. eko man vsiaa; aasaa maah niraaso ||", translation = "One who lives alone, as a hermit, enshrining the One Lord in his mind, remaining unaffected by hope in the midst of hope,", hindi = "रहहि इकांति. एको मनि वसिआ; आसा माहि निरासो ॥", punjabi = "(ਜੋ ਮਨੁੱਖ ਸੰਸਾਰ ਦੀਆਂ) ਆਸਾਂ ਵਲੋਂ ਨਿਰਾਸ ਰਹਿੰਦੇ ਹਨ, ਜਿਨ੍ਹਾਂ ਦੇ ਮਨ ਵਿਚ ਇਕ ਪ੍ਰਭੂ ਹੀ ਵੱਸਦਾ ਹੈ (ਉਹ ਸੰਸਾਰ ਵਿਚ ਰਹਿੰਦੇ ਹੋਏ ਭੀ ਸੰਸਾਰ ਤੋਂ ਲਾਂਭੇ) ਇਕਾਂਤ ਵਿਚ ਵੱਸਦੇ ਹਨ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-24", gurmukhi = "ਅਗਮੁ ਅਗੋਚਰੁ ਦੇਖਿ ਦਿਖਾਏ; ਨਾਨਕੁ. ਤਾ ਕਾ ਦਾਸੋ ॥੫॥", transliteration = "agam agochar dekh dikhaae; naanak. taa kaa daaso ||5||", translation = "sees and inspires others to see the inaccessible, unfathomable Lord. Nanak is his slave. ||5||", hindi = "अगमु अगोचरु देखि दिखाए; नानकु. ता का दासो ॥५॥", punjabi = "(ਅਜੇਹੇ ਜੀਵਨ ਵਾਲਾ ਜੋ ਮਨੁੱਖ) ਅਗੰਮ ਤੇ ਅਗੋਚਰ ਪ੍ਰਭੂ ਦਾ ਦਰਸ਼ਨ ਕਰ ਕੇ ਹੋਰਨਾਂ ਨੂੰ ਦਰਸ਼ਨ ਕਰਾਂਦਾ ਹੈ, ਨਾਨਕ ਉਸ ਦਾ ਦਾਸ ਹੈ ॥੫॥", wordMeaning = "ਅਗਮੁ = ਅ-ਗਮ, ਜਿਸ ਤਕ ਜਾਇਆ ਨ ਜਾ ਸਕੇ {ਗਮ = ਜਾਣਾ}। ਅਗੋਚਰ = ਅ-ਗੋ-ਚਰ {ਅ = ਨਹੀਂ। ਗੋ = ਗਿਆਨ ਇੰਦ੍ਰੇ। ਚਰ = ਅੱਪੜਨਾ}, ਜਿਸ ਤਕ ਗਿਆਨ-ਇੰਦ੍ਰਿਆਂ ਦੀ ਪਹੁੰਚ ਨਾਹ ਹੋ ਸਕੇ। (ਨੋਟ: ਦੂਜੀ ਅਤੇ ਚੌਥੀ ਤੁਕ ਦੇ ਲਫ਼ਜ਼ \"ਨਾਨਕ\" ਅਤੇ \"ਨਾਨਕੁ\" ਵਿਚ ਫ਼ਰਕ ਪਾਠਕ-ਜਨ ਚੇਤੇ ਰੱਖਣ) ॥੫॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-25", gurmukhi = "ਸੁਣਿ ਸੁਆਮੀ ਅਰਦਾਸਿ ਹਮਾਰੀ; ਪੂਛਉ ਸਾਚੁ ਬੀਚਾਰੋ ॥", transliteration = "sun suaamee ardaas hmaaree; poochhau saach beechaaro ||", translation = "\"Listen, Lord, to our prayer. We seek your true opinion.", hindi = "सुणि सुआमी अरदासि हमारी; पूछउ साचु बीचारो ॥", punjabi = "(ਚਰਪਟ ਦਾ ਪ੍ਰਸ਼ਨ:) ਹੇ ਸੁਆਮੀ! ਮੇਰੀ ਬੇਨਤੀ ਸੁਣ, ਮੈਂ ਸਹੀ ਵਿਚਾਰ ਪੁੱਛਦਾ ਹਾਂ;", wordMeaning = "ਸਾਚੁ = ਸਹੀ, ਠੀਕ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-26", gurmukhi = "ਰੋਸੁ. ਨ ਕੀਜੈ, ਉਤਰੁ ਦੀਜੈ; ਕਿਉ ਪਾਈਐ ਗੁਰ ਦੁਆਰੋ ॥", transliteration = "ros. na keejai, utar deejai; kiu paaeeai gur duaaro ||", translation = "Don't be angry with us - please tell us: How can we find the Guru's Door?\"", hindi = "रोसु. न कीजै, उतरु दीजै; किउ पाईऐ गुर दुआरो ॥", punjabi = "ਗੁੱਸਾ ਨਾਹ ਕਰਨਾ, ਉੱਤਰ ਦੇਣਾ ਕਿ ਗੁਰੂ ਦਾ ਦਰ ਕਿਵੇਂ ਪ੍ਰਾਪਤ ਹੁੰਦਾ ਹੈ? (ਭਾਵ, ਕਿਵੇਂ ਪਤਾ ਲੱਗੇ ਕਿ ਗੁਰੂ ਦਾ ਦਰ ਪ੍ਰਾਪਤ ਹੋ ਗਿਆ ਹੈ)?", wordMeaning = "ਰੋਸੁ = ਗੁੱਸਾ। ਗੁਰਦੁਆਰੋ = ਗੁਰੂ ਦਾ ਦਰ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-27", gurmukhi = "ਇਹੁ ਮਨੁ ਚਲਤਉ. ਸਚ ਘਰਿ ਬੈਸੈ; ਨਾਨਕ ਨਾਮੁ ਅਧਾਰੋ ॥", transliteration = "ih man chalatau. sach ghar baisai; naanak naam adhaaro ||", translation = "This fickle mind sits in its true home, O Nanak, through the Support of the Naam, the Name of the Lord.", hindi = "इहु मनु चलतउ. सच घरि बैसै; नानक नामु अधारो ॥", punjabi = "(ਉੱਤਰ:) (ਜਦੋਂ ਸੱਚ-ਮੁਚ ਗੁਰੂ ਦਾ ਦਰ ਪ੍ਰਾਪਤ ਹੋ ਜਾਂਦਾ ਹੈ ਤਦੋਂ) ਹੇ ਨਾਨਕ! ਇਹ ਚੰਚਲ ਮਨ ਪ੍ਰਭੂ ਦੀ ਯਾਦ ਵਿਚ ਜੁੜਿਆ ਰਹਿੰਦਾ ਹੈ, (ਪ੍ਰਭੂ ਦਾ) ਨਾਮ (ਜ਼ਿੰਦਗੀ ਦਾ) ਆਸਰਾ ਹੋ ਜਾਂਦਾ ਹੈ।", wordMeaning = "ਚਲਤਉ = ਚੰਚਲ। ਸਚ ਘਰਿ = ਸੱਚੇ ਦੇ ਘਰ ਵਿਚ, ਸਦਾ ਕਾਇਮ ਰਹਿਣ ਵਾਲੇ ਪ੍ਰਭੂ ਦੀ ਯਾਦ ਵਿਚ। ਅਧਾਰੋ = ਆਸਰਾ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-28", gurmukhi = "ਆਪੇ ਮੇਲਿ ਮਿਲਾਏ ਕਰਤਾ; ਲਾਗੈ ਸਾਚਿ ਪਿਆਰੋ ॥੬॥", transliteration = "aape mel milaae kartaa; laagai saach piaaro ||6||", translation = "The Creator Himself unites us in Union, and inspires us to love the Truth. ||6||", hindi = "आपे मेलि मिलाए करता; लागै साचि पिआरो ॥६॥", punjabi = "(ਪਰ ਇਹੋ ਜਿਹਾ) ਪਿਆਰ ਸੱਚੇ ਪ੍ਰਭੂ ਵਿਚ (ਤਦੋਂ ਹੀ) ਲੱਗਦਾ ਹੈ (ਜਦੋਂ) ਕਰਤਾਰ ਆਪ (ਜੀਵ ਨੂੰ) ਆਪਣੀ ਯਾਦ ਵਿਚ ਜੋੜ ਲੈਂਦਾ ਹੈ ॥੬॥", wordMeaning = "ਸਾਚਿ = ਸੱਚੇ ਪ੍ਰਭੂ ਵਿਚ ॥੬॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-29", gurmukhi = "ਹਾਟੀ ਬਾਟੀ ਰਹਹਿ ਨਿਰਾਲੇ; ਰੂਖਿ ਬਿਰਖਿ ਉਦਿਆਨੇ ॥", transliteration = "haatee baatee rahah niraale; rookh birakh udiaane ||", translation = "\"Away from stores and highways, we live in the woods, among plants and trees.", hindi = "हाटी बाटी रहहि निराले; रूखि बिरखि उदिआने ॥", punjabi = "(ਲੋਹਾਰੀਪਾ ਦਾ ਕਥਨ) ਅਸੀਂ (ਦੁਨੀਆ ਦੇ) ਮੇਲਿਆਂ-ਮਸਾਧਿਆਂ (ਭਾਵ, ਸੰਸਾਰਕ ਝੰਬੇਲਿਆਂ) ਤੋਂ ਵੱਖਰੇ ਜੰਗਲ ਵਿਚ ਕਿਸੇ ਰੁੱਖ-ਬਿਰਖ ਹੇਠ ਰਹਿੰਦੇ ਹਾਂ,", wordMeaning = "ਹਾਟੀ = ਮੇਲਾ, ਮੰਡੀ, ਦੁਕਾਨ। ਰੂਖਿ = ਰੁੱਖ ਹੇਠ। ਬਿਰਖਿ = ਬਿਰਖ ਹੇਠ। ਉਦਿਆਨੇ = ਜੰਗਲ ਵਿਚ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-30", gurmukhi = "ਕੰਦ ਮੂਲੁ ਅਹਾਰੋ ਖਾਈਐ; ਅਉਧੂ ਬੋਲੈ ਗਿਆਨੇ ॥", transliteration = "kand mool ahaaro khaaeeai; audhoo bolai giaane ||", translation = "For food, we take fruits and roots. This is the spiritual wisdom spoken by the renunciates.", hindi = "कंद मूलु अहारो खाईऐ; अउधू बोलै गिआने ॥", punjabi = "ਤੇ ਗਾਜਰ-ਮੂਲੀ ਉਤੇ ਗੁਜ਼ਾਰਾ ਕਰਦੇ ਹਾਂ- ਜੋਗੀ (ਲੋਹਾਰੀਪਾ) ਨੇ (ਜੋਗ ਦਾ) ਗਿਆਨ-ਮਾਰਗ ਇਉਂ ਦੱਸਿਆ।", wordMeaning = "ਕੰਦ = ਧਰਤੀ ਦੇ ਅੰਦਰ ਉੱਗਣ ਵਾਲੀਆਂ ਗਾਜਰ ਮੂਲੀ ਵਰਗੀਆਂ ਸਬਜ਼ੀਆਂ। ਕੰਦ ਮੂਲੁ = ਮੂਲੀ। ਅਹਾਰੋ = ਖ਼ੁਰਾਕ। ਅਉਧੂ = ਵਿਰਕਤ, ਜੋਗੀ। ਬੋਲੈ = (ਭਾਵ,) ਬੋਲਿਆ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-31", gurmukhi = "ਤੀਰਥਿ ਨਾਈਐ. ਸੁਖੁ ਫਲੁ ਪਾਈਐ; ਮੈਲੁ. ਨ ਲਾਗੈ ਕਾਈ ॥", transliteration = "teerath naaeeai. sukh phal paaeeai; mail. na laagai kaaee ||", translation = "We bathe at sacred shrines of pilgrimage, and obtain the fruits of peace; not even an iota of filth sticks to us.", hindi = "तीरथि नाईऐ. सुखु फलु पाईऐ; मैलु. न लागै काई ॥", punjabi = "ਤੀਰਥ ਤੇ ਇਸ਼ਨਾਨ ਕਰਦੇ ਹਾਂ; ਇਸ ਦਾ ਫਲ ਮਿਲਦਾ ਹੈ 'ਸੁਖ', ਤੇ (ਮਨ ਨੂੰ) ਕੋਈ ਮੈਲ (ਭੀ) ਨਹੀਂ ਲੱਗਦੀ।", wordMeaning = "ਤੀਰਥਿ = ਤੀਰਥ ਉਤੇ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-32", gurmukhi = "ਗੋਰਖ ਪੂਤੁ. ਲੋਹਾਰੀਪਾ ਬੋਲੈ; ਜੋਗ ਜੁਗਤਿ. ਬਿਧਿ ਸਾਈ ॥੭॥", transliteration = "gorakh poot. lohaareepaa bolai; jog jugat. bidh saaee ||7||", translation = "Luhaareepaa, the disciple of Gorakh says, this is the Way of Yoga.\" ||7||", hindi = "गोरख पूतु. लोहारीपा बोलै; जोग जुगति. बिधि साई ॥७॥", punjabi = "ਗੋਰਖਨਾਥ ਦਾ ਚੇਲਾ ਲੋਹਾਰੀਪਾ ਬੋਲਿਆ ਕਿ ਇਹੀ ਹੈ ਜੋਗ ਦੀ ਜੁਗਤੀ, ਜੋਗ ਦੀ ਵਿਧੀ ॥੭॥", wordMeaning = "ਗੋਰਖ ਪੂਤੁ = ਗੋਰਖਨਾਥ ਦਾ ਚੇਲਾ। ਸਾਈ = ਇਹੀ ॥੭॥", startsAtMs = 0L, endsAtMs = 0L)
)

private fun generatedSidhaGoshtLines1(): List<BaniLine> = listOf(
    BaniLine(id = "sidha-gosht-33", gurmukhi = "ਹਾਟੀ ਬਾਟੀ. ਨੀਦ, ਨ ਆਵੈ; ਪਰ ਘਰਿ ਚਿਤੁ. ਨ ਡੋੁਲਾਈ ॥", transliteration = "haatee baatee. need, na aavai; par ghar chit. na doulaaee ||", translation = "In the stores and on the road, do not sleep; do not let your consciousness covet anyone else's home.", hindi = "हाटी बाटी. नीद, न आवै; पर घरि चितु. न डोुलाई ॥", punjabi = "(ਗੁਰੂ ਜੀ ਦਾ ਕਥਨ) ਹੇ ਨਾਨਕ! ਅਸਲ (ਗਿਆਨ ਦੀ) ਵਿਚਾਰ ਇਹ ਹੈ ਕਿ ਦੁਨੀਆ ਦੇ ਧੰਧਿਆਂ ਵਿਚ ਰਹਿੰਦਿਆਂ ਮਨੁੱਖ ਨੂੰ ਨੀਂਦ ਨਾਹ ਆਵੇ (ਭਾਵ, ਧੰਧਿਆਂ ਵਿਚ ਹੀ ਨਾਹ ਗ਼ਰਕ ਹੋ ਜਾਏ), ਪਰਾਏ ਘਰ ਵਿਚ ਮਨ ਨੂੰ ਡੋਲਣ ਨਾਹ ਦੇਵੇ;", wordMeaning = "ਡਲਾਈ = ਅੱਖਰ 'ਡ' ਦੇ ਨਾਲ ਦੋ 'ਲਗਾਂ' ਹਨ, (ੋ) ਅਤੇ (ੁ)। ਲਫ਼ਜ਼ ਦੀ ਅਸਲ 'ਲਗ' (ੋ) ਹੈ, ਪਰ ਇਥੇ ਛੰਦ ਦੀ ਚਾਲ ਨੂੰ ਪੂਰਾ ਰੱਖਣ ਲਈ (ੁ) ਪੜ੍ਹਨਾ ਹੈ।", startsAtMs = 0L, endsAtMs = 0L),
