    BaniLine(id = "sidha-gosht-36", gurmukhi = "ਖੰਡਿਤ ਨਿਦ੍ਰਾ. ਅਲਪ ਅਹਾਰੰ; ਨਾਨਕ. ਤਤੁ ਬੀਚਾਰੋ ॥੮॥", transliteration = "khandit nidraa. alap ahaaran; naanak. tat beechaaro ||8||", translation = "Sleep little, and eat little; O Nanak, this is the essence of wisdom. ||8||", hindi = "खंडित निद्रा. अलप अहारं; नानक. ततु बीचारो ॥८॥", punjabi = "ਉਸ ਮਨੁੱਖ ਦੀ ਨੀਂਦ ਭੀ ਘੱਟ ਤੇ ਖ਼ੁਰਾਕ ਭੀ ਥੋੜ੍ਹੀ ਹੁੰਦੀ ਹੈ। (ਭਾਵ, ਉਹ ਚਸਕਿਆਂ ਵਿਚ ਨਹੀਂ ਪੈਂਦਾ) ॥੮॥", wordMeaning = "ਖੰਡਿਤ = ਘੱਟ ਕੀਤੀ ਹੋਈ। ਅਲਪ = ਥੋੜ੍ਹਾ ॥੮॥", startsAtMs = 0L, endsAtMs = 0L),
