    BaniLine(id = "sidha-gosht-38", gurmukhi = "ਬਾਰਹ ਅੰਤਰਿ. ਏਕੁ ਸਰੇਵਹੁ; ਖਟੁ ਦਰਸਨ ਇਕ ਪੰਥਾ ॥", transliteration = "baarah antar. ek srevah; khat darasan ik panthaa ||", translation = "Among the twelve schools of Yoga, ours is the highest; among the six schools of philosophy, ours is the best path.", hindi = "बारह अंतरि. एकु सरेवहु; खटु दरसन इक पंथा ॥", punjabi = "ਛੇ ਭੇਖਾਂ ਵਿਚ ਇਕ ਜੋਗੀ ਪੰਥ ਹੈ, ਉਸ ਦੇ ਬਾਰਾਂ ਫ਼ਿਰਕੇ ਹਨ, ਉਹਨਾਂ ਵਿਚੋਂ ਸਾਡੇ 'ਆਈ ਪੰਥ' ਨੂੰ ਧਾਰਨ ਕਰੋ।", wordMeaning = "ਬਾਰਹ = ਜੋਗੀਆਂ ਦੇ ੧੨ ਪੰਥ = ਰਾਵਲ, ਹੇਤੁ ਪੰਥ, ਪਾਵ ਪੰਥ, ਆਈ ਪੰਥ, ਗਮ੍ਯ ਪੰਥ, ਪਾਗਲ-ਪੰਥ, ਗੋਪਾਲ-ਪੰਥ, ਕੰਥੜੀ-ਪੰਥ, ਬਨ ਪੰਥ, ਧ੍ਵਜ ਪੰਥ, ਚੋਲੀ, ਦਾਸ ਪੰਥ। ਏਕੁ = ਇਕ 'ਆਈ ਪੰਥ', ਸਾਡਾ ਆਈ ਪੰਥ। ਸਰੇਵਹੁ = ਧਾਰਨ ਕਰੋ, ਕਬੂਲੋ। ਖਟੁ ਦਰਸਨ = ਛੇ ਭੇਖ: ਜੰਗਮ, ਜੋਗੀ, ਜੈਨੀ, ਸੰਨਿਆਸੀ, ਬੈਰਾਗੀ, ਬੈਸਨੋ। ਇਕ ਪੰਥਾ = ਸਾਡਾ ਜੋਗੀ-ਪੰਥ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-39", gurmukhi = "ਇਨ ਬਿਧਿ ਮਨੁ ਸਮਝਾਈਐ ਪੁਰਖਾ; ਬਾਹੁੜਿ ਚੋਟ. ਨ ਖਾਈਐ ॥", transliteration = "in bidh man samjhaaeeai purkhaa; baahur chot. na khaaeeai ||", translation = "This is the way to instruct the mind, so you will never suffer beatings again.\"", hindi = "इन बिधि मनु समझाईऐ पुरखा; बाहुड़ि चोट. न खाईऐ ॥", punjabi = "ਹੇ ਪੁਰਖਾ! ਇਸ ਤਰ੍ਹਾਂ ਮਨ ਨੂੰ ਅਕਲ ਦਿੱਤੀ ਜਾ ਸਕਦੀ ਹੈ ਤੇ ਮੁੜ (ਮਾਇਆ ਦੀ) ਚੋਟ ਨਹੀਂ ਖਾਈਦੀ।", wordMeaning = "ਪੁਰਖਾ = ਹੇ ਪੁਰਖ ਨਾਨਕ!", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-40", gurmukhi = "ਨਾਨਕੁ ਬੋਲੈ. ਗੁਰਮੁਖਿ ਬੂਝੈ; ਜੋਗ ਜੁਗਤਿ ਇਵ ਪਾਈਐ ॥੯॥", transliteration = "naanak bolai. gurmukh boojhai; jog jugat iv paaeeai ||9||", translation = "Nanak speaks: the Gurmukh understands; this is the way that Yoga is attained. ||9||", hindi = "नानकु बोलै. गुरमुखि बूझै; जोग जुगति इव पाईऐ ॥९॥", punjabi = "(ਉੱਤਰ:) ਨਾਨਕ ਆਖਦਾ ਹੈ ਕਿ ਗੁਰੂ ਦੇ ਸਨਮੁਖ ਹੋਇਆਂ ਮਨੁੱਖ (ਮਨ ਨੂੰ ਸਮਝਾਣ ਦਾ ਢੰਗ) ਸਮਝਦਾ ਹੈ, ਜੋਗ ਦੀ ਜੁਗਤਿ ਇਸ ਤਰ੍ਹਾਂ ਲੱਭਦੀ ਹੈ (ਕਿ) ॥੯॥", wordMeaning = "ਗੁਰਮੁਖਿ = ਗੁਰੂ ਦੇ ਸਨਮੁਖ। {ਨੋਟ: ਇਹ ਲਫ਼ਜ਼ ਦੱਸਦਾ ਹੈ ਕਿ ਇਥੋਂ ਸਤਿਗੁਰੂ ਜੀ ਨੇ ਉੱਤਰ ਸ਼ੁਰੂ ਕਰ ਦਿੱਤਾ ਹੈ}। ਇਵ = ਇਸ ਤਰ੍ਹਾਂ (ਜਿਵੇਂ ਅਗਾਂਹ ਦੱਸਿਆ ਹੈ) ॥੯॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-41", gurmukhi = "ਅੰਤਰਿ ਸਬਦੁ ਨਿਰੰਤਰਿ ਮੁਦ੍ਰਾ; ਹਉਮੈ ਮਮਤਾ ਦੂਰਿ ਕਰੀ ॥", transliteration = "antar sabad nirantar mudraa; haumai mamtaa door kree ||", translation = "Let constant absorption in the Word of the Shabad deep within be your ear-rings; eradicate egotism and attachment.", hindi = "अंतरि सबदु निरंतरि मुद्रा; हउमै ममता दूरि करी ॥", punjabi = "ਮਨ ਵਿਚ ਸਤਿਗੁਰੂ ਦੇ ਸ਼ਬਦ ਨੂੰ ਇੱਕ-ਰਸ ਵਸਾਣਾ-ਇਹ (ਕੰਨਾਂ ਵਿਚ) ਮੁੰਦ੍ਰਾਂ (ਪਾਉਣੀਆਂ) ਹਨ, (ਜੋ ਮਨੁੱਖ ਗੁਰ-ਸ਼ਬਦ ਨੂੰ ਵਸਾਂਦਾ ਹੈ ਉਹ) ਆਪਣੀ ਹਉਮੈ ਅਤੇ ਮਮਤਾ ਨੂੰ ਦੂਰ ਕਰ ਲੈਂਦਾ ਹੈ;", wordMeaning = "ਅੰਤਰਿ = (ਮਨ ਦੇ) ਅੰਦਰ। ਨਿਰੰਤਰਿ = ਨਿਰ-ਅੰਤਰਿ, ਇੱਕ-ਰਸ, ਮਤਵਾਤਰ, ਸਦਾ। ਮਮ = ਮੇਰਾ। ਮਮਤਾ = ਮੇਰ-ਪਨ, ਅਪਣੱਤ, ਦੁਨੀਆਵੀ ਪਦਾਰਥਾਂ ਨੂੰ ਆਪਣਾ ਬਨਾਣ ਦਾ ਖ਼ਿਆਲ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-42", gurmukhi = "ਕਾਮੁ ਕ੍ਰੋਧੁ ਅਹੰਕਾਰੁ ਨਿਵਾਰੈ; ਗੁਰ ਕੈ ਸਬਦਿ. ਸੁ ਸਮਝ ਪਰੀ ॥", transliteration = "kaam krodh ahankaar nivaarai; gur kai sabad. su samajh pree ||", translation = "Discard sexual desire, anger and egotism, and through the Word of the Guru's Shabad, attain true understanding.", hindi = "कामु क्रोधु अहंकारु निवारै; गुर कै सबदि. सु समझ परी ॥", punjabi = "ਕਾਮ, ਕ੍ਰੋਧ ਅਤੇ ਅਹੰਕਾਰ ਨੂੰ ਮਿਟਾ ਲੈਂਦਾ ਹੈ, ਗੁਰੂ ਦੇ ਸ਼ਬਦ ਦੀ ਰਾਹੀਂ ਉਸ ਨੂੰ ਸੋਹਣੀ ਸੂਝ ਪੈ ਜਾਂਦੀ ਹੈ।", wordMeaning = "ਨਿਵਾਰੈ = ਦੂਰ ਕਰਦਾ ਹੈ। ਸਬਦਿ = ਸ਼ਬਦ ਦੀ ਰਾਹੀਂ। ਸੁ = ਚੰਗੀ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-43", gurmukhi = "ਖਿੰਥਾ ਝੋਲੀ ਭਰਿਪੁਰਿ ਰਹਿਆ; ਨਾਨਕ. ਤਾਰੈ ਏਕੁ ਹਰੀ ॥", transliteration = "khinthaa jholee bhripur rhiaa; naanak. taarai ek hree ||", translation = "For your patched coat and begging bowl, see the Lord God pervading and permeating everywhere; O Nanak, the One Lord will carry you across.", hindi = "खिंथा झोली भरिपुरि रहिआ; नानक. तारै एकु हरी ॥", punjabi = "ਹੇ ਨਾਨਕ! ਪ੍ਰਭੂ ਨੂੰ ਸਭ ਥਾਈਂ ਵਿਆਪਕ ਸਮਝਣਾ ਉਸ ਮਨੁੱਖ ਦੀ ਗੋਦੜੀ ਤੇ ਝੋਲੀ ਹੈ।", wordMeaning = "ਭਰਿ ਪੁਰਿ = ਭਰਪੂਰ, ਨਕਾ-ਨਕ, ਸਭ ਥਾਈਂ ਮੌਜੂਦ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-44", gurmukhi = "ਸਾਚਾ ਸਾਹਿਬੁ ਸਾਚੀ ਨਾਈ; ਪਰਖੈ ਗੁਰ ਕੀ ਬਾਤ ਖਰੀ ॥੧੦॥", transliteration = "saachaa saahib saachee naaee; parkhai gur kee baat khree ||10||", translation = "True is our Lord and Master, and True is His Name. Analyze it, and you shall find the Word of the Guru to be True. ||10||", hindi = "साचा साहिबु साची नाई; परखै गुर की बात खरी ॥१०॥", punjabi = "ਸਤਿਗੁਰੂ ਦੇ ਸੱਚੇ ਸ਼ਬਦ ਦੀ ਰਾਹੀਂ ਉਹ ਮਨੁੱਖ ਇਹ ਨਿਰਨਾ ਕਰ ਲੈਂਦਾ ਹੈ ਕਿ ਇਕ ਪਰਮਾਤਮਾ ਹੀ (ਮਾਇਆ ਦੀ ਚੋਟ ਤੋਂ) ਬਚਾਂਦਾ ਹੈ ਜੋ ਸਦਾ ਕਾਇਮ ਰਹਿਣ ਵਾਲਾ ਮਾਲਕ ਹੈ ਤੇ ਜਿਸ ਦੀ ਵਡਿਆਈ ਭੀ ਸਦਾ ਟਿਕੀ ਰਹਿਣ ਵਾਲੀ ਹੈ ॥੧੦॥", wordMeaning = "ਸਾਚਾ = ਸਦਾ ਕਾਇਮ ਰਹਿਣ ਵਾਲਾ। ਨਾਈ = ਵਡਿਆਈ। (ਨੋਟ: ਅਰਬੀ ਲਫ਼ਜ਼ 'स्ना' ਤੋਂ ਦੋ ਪੰਜਾਬੀ ਰੂਪ ਹਨ, 'ਅਸਨਾਈ' ਅਤੇ 'ਨਾਈ'। ਵੇਖੋ 'ਗੁਰਬਾਣੀ ਵਿਆਕਰਣ')। ਖਰੀ ਬਾਤ = ਖਰੀ ਗੱਲ ਦੀ ਰਾਹੀਂ, ਸੱਚੇ ਸ਼ਬਦ ਦੀ ਰਾਹੀਂ ॥੧੦॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-45", gurmukhi = "ਊਂਧਉ ਖਪਰੁ; ਪੰਚ ਭੂ ਟੋਪੀ ॥", transliteration = "oondhau khapar; panch bhoo topee ||", translation = "Let your mind turn away in detachment from the world, and let this be your begging bowl. Let the lessons of the five elements be your cap.", hindi = "ऊंधउ खपरु; पंच भू टोपी ॥", punjabi = "ਸੰਸਾਰਕ ਖ਼ਾਹਸ਼ਾਂ ਵਲੋਂ ਮੁੜੀ ਹੋਈ ਸੁਰਤ ਉਸ (ਮਨੁੱਖ) ਦਾ ਖੱਪਰ ਹੈ, ਪੰਜ ਤੱਤਾਂ ਦੇ ਦੈਵੀ ਗੁਣ ਉਸ ਦੀ ਟੋਪੀ ਹੈ,", wordMeaning = "ਊਂਧਉ = ਉਲਟਿਆ ਹੋਇਆ, ਸੰਸਾਰਕ ਖ਼ਾਹਸ਼ਾਂ ਵਲੋਂ ਮੁੜਿਆ ਹੋਇਆ। ਖਪਰੁ = ਜੋਗੀ ਜਾਂ ਮੰਗਤੇ ਦਾ ਉਹ ਪਿਆਲਾ ਜਿਸ ਵਿਚ ਭਿੱਖਿਆ ਪੁਆਂਦਾ ਹੈ। ਭੂ = ਤੱਤ। ਪੰਚਭੂ = ਪੰਜਾਂ ਤੱਤਾਂ ਦੇ ਉਪਕਾਰੀ ਗੁਣ = (ਅਕਾਸ਼ ਦੀ ਨਿਰਲੇਪਤਾ; ਅਗਨੀ ਦਾ ਸੁਭਾਉ ਮੈਲ ਸਾੜਨਾ; ਵਾਯੂ ਦੀ ਸਮ-ਦਰਸਤਾ; ਜਲ ਦੀ ਸੀਤਲਤਾ; ਧਰਤੀ ਦੀ ਧੀਰਜ)।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-46", gurmukhi = "ਕਾਂਇਆ ਕੜਾਸਣੁ; ਮਨੁ ਜਾਗੋਟੀ ॥", transliteration = "kaaniaa kraasan; man jaagotee ||", translation = "Let the body be your meditation mat, and the mind your loin cloth.", hindi = "कांइआ कड़ासणु; मनु जागोटी ॥", punjabi = "ਸਰੀਰ (ਨੂੰ ਵਿਕਾਰਾਂ ਤੋਂ ਨਿਰਮਲ ਰੱਖਣਾ) ਉਸ ਦਾ ਦੱਭ ਦਾ ਆਸਣ ਹੈ, (ਵੱਸ ਵਿਚ ਆਇਆ ਹੋਇਆ) ਮਨ ਉਸ ਦੀ ਲੰਗੋਟੀ ਹੈ,", wordMeaning = "ਕੜਾਸਣੁ = ਕਟ ਦਾ ਆਸਣ। ਕਟ = ਫੂਹੜੀ (a straw mat)। ਜਾਗੋਟੀ = ਲੰਗੋਟੀ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-47", gurmukhi = "ਸਤੁ ਸੰਤੋਖੁ ਸੰਜਮੁ ਹੈ ਨਾਲਿ ॥", transliteration = "sat santokh sanjam hai naal ||", translation = "Let truth, contentment and self-discipline be your companions.", hindi = "सतु संतोखु संजमु है नालि ॥", punjabi = "ਸਤ ਸੰਤੋਖ ਤੇ ਸੰਜਮ ਉਸ ਦੇ ਨਾਲ (ਤਿੰਨ ਚੇਲੇ) ਹਨ", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-48", gurmukhi = "ਨਾਨਕ. ਗੁਰਮੁਖਿ ਨਾਮੁ ਸਮਾਲਿ ॥੧੧॥", transliteration = "naanak. gurmukh naam smaal ||11||", translation = "O Nanak, the Gurmukh dwells on the Naam, the Name of the Lord. ||11||", hindi = "नानक. गुरमुखि नामु समालि ॥११॥", punjabi = "ਹੇ ਨਾਨਕ! (ਜੋ ਮਨੁੱਖ) ਗੁਰੂ ਦੀ ਰਾਹੀਂ (ਪ੍ਰਭੂ ਦਾ) ਨਾਮ ਯਾਦ ਕਰਦਾ ਹੈ ॥੧੧॥", wordMeaning = "ਗੁਰਮੁਖਿ = ਗੁਰੂ ਦੀ ਰਾਹੀਂ। ਸਮਾਲਿ = ਸਮਾਲੇ, ਸਮ੍ਹਾਲਦਾ ਹੈ ॥੧੧॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-49", gurmukhi = "ਕਵਨੁ ਸੁ ਗੁਪਤਾ; ਕਵਨੁ ਸੁ ਮੁਕਤਾ ॥", transliteration = "kavan su guptaa; kavan su muktaa ||", translation = "\"Who is hidden? Who is liberated?", hindi = "कवनु सु गुपता; कवनु सु मुकता ॥", punjabi = "(ਪ੍ਰਸ਼ਨ:) ਲੁਕਿਆ ਹੋਇਆ ਕੌਣ ਹੈ? ਉਹ ਕੌਣ ਹੈ ਜੋ ਮੁਕਤ ਹੈ?", wordMeaning = "ਗੁਪਤਾ = ਲੁਕਿਆ ਹੋਇਆ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-50", gurmukhi = "ਕਵਨੁ ਸੁ; ਅੰਤਰਿ ਬਾਹਰਿ ਜੁਗਤਾ ॥", transliteration = "kavan su; antar baahar jugtaa ||", translation = "Who is united, inwardly and outwardly?", hindi = "कवनु सु; अंतरि बाहरि जुगता ॥", punjabi = "ਉਹ ਕੌਣ ਹੈ ਜੋ ਅੰਦਰੋਂ ਬਾਹਰੋਂ (ਭਾਵ, ਜਿਸ ਦਾ ਮਨ ਭੀ ਤੇ ਸਰੀਰਕ ਇੰਦ੍ਰੇ ਭੀ ਮਿਲੇ ਹੋਏ ਹਨ) ਮਿਲਿਆ ਹੋਇਆ ਹੈ?", wordMeaning = "ਅੰਤਰਿ = ਅੰਦਰੋਂ। ਬਾਹਰਿ = ਬਾਹਰੋਂ। ਅੰਤਰਿ ਬਾਹਰਿ = (ਭਾਵ,) ਮਨ ਦੀ ਰਾਹੀਂ ਅਤੇ ਸਰੀਰ ਦੀ ਰਾਹੀਂ। ਜੁਗਤਾ = ਜੁੜਿਆ ਹੋਇਆ, ਮਿਲਿਆ ਹੋਇਆ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-51", gurmukhi = "ਕਵਨੁ ਸੁ ਆਵੈ; ਕਵਨੁ ਸੁ ਜਾਇ ॥", transliteration = "kavan su aavai; kavan su jaai ||", translation = "Who comes, and who goes?", hindi = "कवनु सु आवै; कवनु सु जाइ ॥", punjabi = "(ਸਦਾ) ਜੰਮਦਾ ਮਰਦਾ ਕੌਣ ਹੈ?", wordMeaning = "ਆਵੈ ਜਾਇ = ਜੰਮਦਾ ਮਰਦਾ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-52", gurmukhi = "ਕਵਨੁ ਸੁ; ਤ੍ਰਿਭਵਣਿ ਰਹਿਆ ਸਮਾਇ ॥੧੨॥", transliteration = "kavan su; tribhavan rhiaa smaai ||12||", translation = "Who is permeating and pervading the three worlds?\" ||12||", hindi = "कवनु सु; त्रिभवणि रहिआ समाइ ॥१२॥", punjabi = "ਤ੍ਰਿਲੋਕੀ ਦੇ ਨਾਥ ਵਿਚ ਲੀਨ ਕੌਣ ਹੈ? ॥੧੨॥", wordMeaning = "ਤ੍ਰਿਭਵਣ = ਤਿੰਨਾਂ ਭਵਨਾਂ ਦੇ ਮਾਲਕ ਵਿਚ, ਤਿੰਨ-ਭਵਨਾਂ-ਵਿਚ-ਵਿਆਪਕ ਪ੍ਰਭੂ ਵਿਚ {ਤਿੰਨ ਭਵਨ = ਆਕਾਸ਼, ਮਾਤ ਲੋਕ ਤੇ ਪਾਤਾਲ ਸੰ: ਤ੍ਰਿਭਵਨ} ॥੧੨॥", startsAtMs = 0L, endsAtMs = 0L),
