    BaniLine(id = "sidha-gosht-70", gurmukhi = "ਕਿਸੁ ਕਾਰਣਿ; ਇਹੁ ਭੇਖੁ ਨਿਵਾਸੀ ॥", transliteration = "kis kaaran; ih bhekh nivaasee ||", translation = "Why have you adopted these religious robes?", hindi = "किसु कारणि; इहु भेखु निवासी ॥", punjabi = "ਕਿਉਂ ਇਹ (ਉਦਾਸੀ-) ਭੇਖ ਧਾਰਿਆ ਸੀ?", wordMeaning = "ਨਿਵਾਸੀ = ਧਾਰਨ ਵਾਲੇ (ਹੋਏ ਸੀ)।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-71", gurmukhi = "ਕਿਸੁ ਵਖਰ ਕੇ; ਤੁਮ ਵਣਜਾਰੇ ॥", transliteration = "kis vakhar ke; tum vanjaare ||", translation = "What merchandise do you trade?", hindi = "किसु वखर के; तुम वणजारे ॥", punjabi = "ਤੁਸੀ ਕਿਸ ਸੌਦੇ ਦੇ ਵਪਾਰੀ ਹੋ?", wordMeaning = "ਵਣਜਾਰੇ = ਵਪਾਰੀ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-72", gurmukhi = "ਕਿਉ ਕਰਿ; ਸਾਥੁ ਲੰਘਾਵਹੁ ਪਾਰੇ ॥੧੭॥", transliteration = "kiu kar; saath langhaavah paare ||17||", translation = "How will you carry others across with you?\" ||17||", hindi = "किउ करि; साथु लंघावहु पारे ॥१७॥", punjabi = "(ਆਪਣੇ ਸ਼ਰਧਾਲੂਆਂ ਦੀ) ਜਮਾਤ ਨੂੰ (ਇਸ 'ਦੁਤਰ ਸਾਗਰ' ਕਿਵੇਂ ਪਾਰ ਲੰਘਾਵੋਗੇ? (ਭਾਵ, ਆਪਣੇ ਸਿੱਖਾਂ ਨੂੰ ਇਸ ਸੰਸਾਰ ਤੋਂ ਪਾਰ ਲੰਘਣ ਲਈ ਤੁਸਾਂ ਕੇਹੜਾ ਰਾਹ ਦੱਸਿਆ ਹੈ)? ॥੧੭॥", wordMeaning = "ਸਾਥੁ = (ਸੰ: ਸਾਰਥੁ) ਕਾਫ਼ਲਾ। {ਨੋਟ: ਲਫ਼ਜ਼ \"ਸਾਥੁ\" ਅਤੇ \"ਸਾਥਿ\" ਦਾ ਫ਼ਰਕ ਚੇਤੇ ਰੱਖਣ-ਯੋਗ ਹੈ। 'ਸਾਥੁ' ਨਾਂਵ ਹੈ, ਅਤੇ 'ਸਾਥਿ' ਸੰਬੰਧਕ ਹੈ। ਵੇਖੋ 'ਗੁਰਬਾਣੀ ਵਿਆਕਰਣ'} ॥੧੭॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-73", gurmukhi = "ਗੁਰਮੁਖਿ ਖੋਜਤ ਭਏ ਉਦਾਸੀ ॥", transliteration = "gurmukh khojat bhae udaasee ||", translation = "I became a wandering Udaasee, searching for the Gurmukhs.", hindi = "गुरमुखि खोजत भए उदासी ॥", punjabi = "(ਉੱਤਰ:) ਅਸੀਂ ਗੁਰਮੁਖਾਂ ਨੂੰ ਲੱਭਣ ਵਾਸਤੇ ਉਦਾਸੀ ਬਣੇ ਸਾਂ,", wordMeaning = "ਭਏ = ਬਣੇ ਸਾਂ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-74", gurmukhi = "ਦਰਸਨ ਕੈ ਤਾਈ; ਭੇਖ ਨਿਵਾਸੀ ॥", transliteration = "darasan kai taaee; bhekh nivaasee ||", translation = "I have adopted these robes seeking the Blessed Vision of the Lord's Darshan.", hindi = "दरसन कै ताई; भेख निवासी ॥", punjabi = "ਅਸਾਂ ਗੁਰਮੁਖਾਂ ਦੇ ਦਰਸ਼ਨਾਂ ਲਈ (ਉਦਾਸੀ-) ਭੇਖ ਧਾਰਿਆ ਸੀ।", wordMeaning = "ਕੈ ਤਾਈ = ਦੀ ਖ਼ਾਤਰ। ਦਰਸਨ = ਗੁਰਮੁਖਾਂ ਦਾ ਦਰਸ਼ਨ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-75", gurmukhi = "ਸਾਚ ਵਖਰ ਕੇ; ਹਮ ਵਣਜਾਰੇ ॥", transliteration = "saach vakhar ke; ham vanjaare ||", translation = "I trade in the merchandise of Truth.", hindi = "साच वखर के; हम वणजारे ॥", punjabi = "ਅਸੀਂ ਸੱਚੇ ਪ੍ਰਭੂ ਦੇ ਨਾਮ-ਸੌਦੇ ਦੇ ਵਪਾਰੀ ਹਾਂ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-76", gurmukhi = "ਨਾਨਕ; ਗੁਰਮੁਖਿ ਉਤਰਸਿ ਪਾਰੇ ॥੧੮॥", transliteration = "naanak; gurmukh utaras paare ||18||", translation = "O Nanak, as Gurmukh, I carry others across. ||18||", hindi = "नानक; गुरमुखि उतरसि पारे ॥१८॥", punjabi = "ਹੇ ਨਾਨਕ! ਜੋ ਮਨੁੱਖ ਗੁਰੂ ਦੇ ਦੱਸੇ ਰਾਹ ਤੇ ਤੁਰਦਾ ਹੈ ਉਹ ('ਦੁਤਰ ਸਾਗਰ' ਤੋਂ) ਪਾਰ ਲੰਘਦਾ ਹੈ ॥੧੮॥", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-77", gurmukhi = "ਕਿਤੁ ਬਿਧਿ ਪੁਰਖਾ; ਜਨਮੁ ਵਟਾਇਆ ॥", transliteration = "kit bidh purkhaa; janam vtaaiaa ||", translation = "\"How have you changed the course of your life?", hindi = "कितु बिधि पुरखा; जनमु वटाइआ ॥", punjabi = "(ਪ੍ਰਸ਼ਨ:) ਹੇ ਪੁਰਖਾ! ਤੂੰ ਆਪਣੀ ਜ਼ਿੰਦਗੀ ਕਿਸ ਤਰੀਕੇ ਨਾਲ ਪਲਟ ਲਈ ਹੈ?", wordMeaning = "ਕਿਤੁ ਬਿਧਿ = ਕਿਸ ਤਰੀਕੇ ਨਾਲ? ਜਨਮੁ ਵਟਾਇਆ = ਜ਼ਿੰਦਗੀ ਪਲਟ ਲਈ ਹੈ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-78", gurmukhi = "ਕਾਹੇ ਕਉ ਤੁਝੁ; ਇਹੁ ਮਨੁ ਲਾਇਆ ॥", transliteration = "kaahe kau tujh; ih man laaiaa ||", translation = "With what have you linked your mind?", hindi = "काहे कउ तुझु; इहु मनु लाइआ ॥", punjabi = "ਤੂੰ ਆਪਣਾ ਇਹ ਮਨ ਕਿਸ ਵਿਚ ਜੋੜਿਆ ਹੈ?", wordMeaning = "ਕਾਹੇ ਕਉ = ਕਿਸ ਨਾਲ?", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-79", gurmukhi = "ਕਿਤੁ ਬਿਧਿ; ਆਸਾ ਮਨਸਾ ਖਾਈ ॥", transliteration = "kit bidh; aasaa mansaa khaaee ||", translation = "How have you subdued your hopes and desires?", hindi = "कितु बिधि; आसा मनसा खाई ॥", punjabi = "ਮਨ ਦੀਆਂ ਆਸਾਂ ਤੇ ਮਨ ਦੇ ਫੁਰਨੇ ਤੂੰ ਕਿਵੇਂ ਮੁਕਾ ਲਏ ਹਨ?", wordMeaning = "ਮਨਸਾ = ਮਨ ਦਾ ਫੁਰਨਾ। ਖਾਈ = ਖਾ ਲਈ ਹੈ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-80", gurmukhi = "ਕਿਤੁ ਬਿਧਿ; ਜੋਤਿ ਨਿਰੰਤਰਿ ਪਾਈ ॥", transliteration = "kit bidh; jot nirantar paaee ||", translation = "How have you found the Light deep within your nucleus?", hindi = "कितु बिधि; जोति निरंतरि पाई ॥", punjabi = "ਰੱਬੀ ਪ੍ਰਕਾਸ਼ ਤੈਨੂੰ ਇੱਕ-ਰਸ ਕਿਵੇਂ ਮਿਲ ਪਿਆ ਹੈ?", wordMeaning = "ਨਿਰੰਤਰਿ = ਇੱਕ-ਰਸ। ਜੋਤਿ = ਰੱਬੀ ਪ੍ਰਕਾਸ਼।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-81", gurmukhi = "ਬਿਨੁ ਦੰਤਾ; ਕਿਉ ਖਾਈਐ ਸਾਰੁ ॥", transliteration = "bin dantaa; kiu khaaeeai saar ||", translation = "Without teeth, how can you eat iron?", hindi = "बिनु दंता; किउ खाईऐ सारु ॥", punjabi = "(ਮਾਇਆ ਦੇ ਇਸ ਪ੍ਰਭਾਵ ਤੋਂ ਬਚਣਾ ਇਉਂ ਹੀ ਔਖਾ ਹੈ ਜਿਵੇਂ ਬਿਨਾ ਦੰਦਾਂ ਦੇ ਲੋਹਾ ਚੱਬਣਾ) ਦੰਦਾਂ ਤੋਂ ਬਿਨਾ ਲੋਹਾ ਕਿਵੇਂ ਚੱਬਿਆ ਜਾਏ?", wordMeaning = "ਦੰਤ = ਦੰਦ। ਸਾਰੁ = ਲੋਹਾ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-82", gurmukhi = "ਨਾਨਕ. ਸਾਚਾ ਕਰਹੁ ਬੀਚਾਰੁ ॥੧੯॥", transliteration = "naanak. saachaa karah beechaar ||19||", translation = "Give us your true opinion, Nanak.\" ||19||", hindi = "नानक. साचा करहु बीचारु ॥१९॥", punjabi = "ਹੇ ਨਾਨਕ! ਕੋਈ ਸਹੀ ਵੀਚਾਰ ਦੱਸੋ (ਭਾਵ, ਕੋਈ ਐਸਾ ਵੀਚਾਰ ਦੱਸੋ ਜੋ ਅਸਾਡੇ ਮਨ ਲੱਗੇ ਜਾਏ) ॥੧੯॥", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-83", gurmukhi = "ਸਤਿਗੁਰ ਕੈ ਜਨਮੇ; ਗਵਨੁ ਮਿਟਾਇਆ ॥", transliteration = "satigur kai janme; gavan mitaaiaa ||", translation = "Born into the House of the True Guru, my wandering in reincarnation ended.", hindi = "सतिगुर कै जनमे; गवनु मिटाइआ ॥", punjabi = "(ਉੱਤਰ:) ਜਿਉਂ ਜਿਉਂ ਸਤਿਗੁਰੂ ਦੀ ਸਿੱਖਿਆ ਤੇ ਤੁਰੇ, ਤਿਉਂ ਤਿਉਂ ਮਨ ਦੀ ਭਟਕਣਾ ਮੁੱਕਦੀ ਗਈ।", wordMeaning = "ਸਤਿਗੁਰ ਕੈ = ਸਤਿਗੁਰੂ ਦੇ ਘਰ ਵਿਚ। ਸਤਿਗੁਰ ਕੇ ਜਨਮੇ = ਸਤਿਗੁਰੂ ਦੇ ਘਰ ਵਿਚ ਜਨਮ ਲਿਆਂ, ਜਦੋਂ ਗੁਰੂ ਦੀ ਸਰਣ ਆ ਕੇ ਪਿਛਲਾ ਸੁਭਾਉ ਮਿਟਾ ਦਿੱਤਾ। ਗਵਨੁ = ਭਟਕਣਾ, ਆਵਾਗਵਨ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-84", gurmukhi = "ਅਨਹਤਿ ਰਾਤੇ; ਇਹੁ ਮਨੁ ਲਾਇਆ ॥", transliteration = "anahat raate; ih man laaiaa ||", translation = "My mind is attached and attuned to the unstruck sound current.", hindi = "अनहति राते; इहु मनु लाइआ ॥", punjabi = "ਜਿਉਂ ਜਿਉਂ ਇੱਕ-ਰਸ ਵਿਆਪਕ ਪ੍ਰਭੂ ਵਿਚ ਜੁੜਨ ਦਾ ਆਨੰਦ ਆਇਆ, ਤਿਉਂ ਤਿਉਂ ਇਹ ਮਨ ਪਰਚਦਾ ਗਿਆ।", wordMeaning = "ਅਨਹਤਿ = ਅਨਹਤ ਵਿਚ। ਅਨਹਤ = ਇਕ-ਰਸ ਵਿਆਪਕ ਪ੍ਰਭੂ {ਅਨਾਹਤਂ = ਆਹਤਂ ਛੇਦੋ ਭੋਗੋ ਵਾ ਤੱਨਾਸਤਿ ਯਸ੍ਯ। अनाहतं = अहतं छेदो भोगो वा तन्नास्ति यस्य}। ਰਾਤੇ = ਮਸਤ ਹੋਇਆ। ਲਾਇਆ = ਪਰਚਾ ਲਿਆ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-85", gurmukhi = "ਮਨਸਾ ਆਸਾ; ਸਬਦਿ ਜਲਾਈ ॥", transliteration = "mansaa aasaa; sabad jlaaee ||", translation = "Through the Word of the Shabad, my hopes and desires have been burnt away.", hindi = "मनसा आसा; सबदि जलाई ॥", punjabi = "ਮਨ ਦੇ ਫੁਰਨੇ ਤੇ ਦੁਨੀਆ ਵਾਲੀਆਂ ਆਸਾਂ ਅਸਾਂ ਗੁਰੂ ਦੇ ਸ਼ਬਦ ਦੀ ਰਾਹੀਂ ਸਾੜੀਆਂ ਹਨ,", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-86", gurmukhi = "ਗੁਰਮੁਖਿ ਜੋਤਿ ਨਿਰੰਤਰਿ ਪਾਈ ॥", transliteration = "gurmukh jot nirantar paaee ||", translation = "As Gurmukh, I found the Light deep within the nucleus of my self.", hindi = "गुरमुखि जोति निरंतरि पाई ॥", punjabi = "ਗੁਰੂ ਦੇ ਸਨਮੁਖ ਹੋਇਆਂ ਹੀ ਇੱਕ-ਰਸ ਰੱਬੀ ਪ੍ਰਕਾਸ਼ ਲੱਭਾ ਹੈ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-87", gurmukhi = "ਤ੍ਰੈ ਗੁਣ ਮੇਟੇ; ਖਾਈਐ ਸਾਰੁ ॥", transliteration = "trai gun mete; khaaeeai saar ||", translation = "Eradicating the three qualities, one eats iron.", hindi = "त्रै गुण मेटे; खाईऐ सारु ॥", punjabi = "(ਇਸ ਰੱਬੀ ਪ੍ਰਕਾਸ਼ ਦੀ ਬਰਕਤ ਨਾਲ) ਅਸਾਂ ਮਾਇਆ ਦੇ ਝਲਕੇ ਦੇ ਤਿੰਨਾਂ ਹੀ ਕਿਸਮਾਂ ਦੇ ਅਸਰ (ਤਮੋ, ਰਜੋ, ਸਤੋ) ਆਪਣੇ ਉਤੇ ਪੈਣ ਨਹੀਂ ਦਿੱਤੇ, ਤੇ (ਇਸ ਤਰ੍ਹਾਂ ਮਾਇਆ ਦੀ ਚੋਟ ਤੋਂ ਬਚਣ ਦਾ ਇਹ ਅੱਤਿ ਔਖਾ ਕੰਮ-ਰੂਪ) ਲੋਹਾ ਚੱਬਿਆ ਗਿਆ ਹੈ।", wordMeaning = "ਤ੍ਰੈਗੁਣ = ਮਾਇਆ ਦੇ ਤਿੰਨ ਗੁਣ; ਤਮੋ ਗੁਣ, ਰਜੋ ਗੁਣ, ਸਤੋ ਗੁਣ; ਅਗਿਆਨ, ਪ੍ਰਵਿਰਤੀ, ਗਿਆਨ; ਪ੍ਰਕ੍ਰਿਤੀ ਵਿਚੋਂ ਉੱਠੀਆਂ ਲਹਿਰਾਂ ਜੋ ਤਿੰਨ ਕਿਸਮ ਦਾ ਅਸਰ ਸਾਡੇ ਮਨ ਤੇ ਪਾਂਦੀਆਂ ਹਨ, ਇਹ ਤਿੰਨ ਗੁਣ ਹਨ ਮਾਇਆ ਦੇ: ਸੁਸਤੀ, ਚੁਸਤੀ ਤੇ ਸ਼ਾਂਤੀ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-88", gurmukhi = "ਨਾਨਕ; ਤਾਰੇ ਤਾਰਣਹਾਰੁ ॥੨੦॥", transliteration = "naanak; taare taaranhaar ||20||", translation = "O Nanak, the Emancipator emancipates. ||20||", hindi = "नानक; तारे तारणहारु ॥२०॥", punjabi = "(ਪਰ) ਹੇ ਨਾਨਕ! (ਇਸ 'ਦੁਤਰ ਸਾਗਰ' ਤੋਂ) ਤਾਰਣ ਦੇ ਸਮਰੱਥ ਪ੍ਰਭੂ ਆਪ ਹੀ ਤਾਰਦਾ ਹੈ ॥੨੦॥", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-89", gurmukhi = "ਆਦਿ ਕਉ ਕਵਨੁ ਬੀਚਾਰੁ ਕਥੀਅਲੇ; ਸੁੰਨ ਕਹਾ ਘਰ ਵਾਸੋ ॥", transliteration = "aad kau kavan beechaar ktheeale; sunn khaa ghar vaaso ||", translation = "\"What can you tell us about the beginning? In what home did the absolute dwell then?", hindi = "आदि कउ कवनु बीचारु कथीअले; सुंन कहा घर वासो ॥", punjabi = "(ਪ੍ਰਸ਼ਨ:) ਤੁਸੀ (ਸ੍ਰਿਸ਼ਟੀ ਦੇ) ਮੁੱਢ ਦਾ ਕੀਹ ਵਿਚਾਰ ਦੱਸਦੇ ਹੋ? (ਤਦੋਂ) ਅਫੁਰ ਪਰਮਾਤਮਾ ਦਾ ਟਿਕਾਣਾ ਕਿਥੇ ਸੀ?", wordMeaning = "ਆਦਿਕ = ਮੁੱਢ, ਆਰੰਭ, ਜਗਤ-ਰਚਨਾ ਦਾ ਮੁੱਢ। ਕਥੀਅਲੇ = ਕਿਹਾ ਜਾਂਦਾ ਹੈ। ਸੁੰਨ = (ਸੰ: ਸ਼ੂਨ੍ਯ) ਅਫੁਰ ਪਰਮਾਤਮਾ, ਨਿਰਗੁਣ-ਸਰੂਪ ਪ੍ਰਭੂ। ਘਰ ਵਾਸੋ = ਟਿਕਾਣਾ, ਅਸਥਾਨ।", startsAtMs = 0L, endsAtMs = 0L),
