    BaniLine(id = "sidha-gosht-92", gurmukhi = "ਸਹਜ ਸੰਤੋਖ ਕਾ ਆਸਣੁ ਜਾਣੈ; ਕਿਉ. ਛੇਦੇ ਬੈਰਾਈਐ ॥", transliteration = "sahaj santokh kaa aasan jaanai; kiu. chhede bairaaeeai ||", translation = "How can one know the posture of intuition and contentment, and overcome one's adversaries?\"", hindi = "सहज संतोख का आसणु जाणै; किउ. छेदे बैराईऐ ॥", punjabi = "ਕਿਵੇਂ (ਹਉਮੈ) ਵੈਰੀ ਦਾ ਨਾਸ ਹੋਵੇ ਜਿਸ ਕਰਕੇ ਸਹਜ ਤੇ ਸੰਤੋਖ ਦਾ ਆਸਣ ਪਛਾਣ ਲਿਆ ਜਾਏ (ਭਾਵ, ਜਿਸ ਕਰਕੇ ਸਹਜ ਤੇ ਸੰਤੋਖ ਪ੍ਰਾਪਤ ਹੋਵੇ)?", wordMeaning = "ਬੈਰਾਈਐ = ਵੈਰੀ ਨੂੰ।", startsAtMs = 0L, endsAtMs = 0L),
