    BaniLine(id = "sidha-gosht-94", gurmukhi = "ਜਿਨਿ ਰਚਿ ਰਚਿਆ. ਤਿਸੁ ਸਬਦਿ ਪਛਾਣੈ; ਨਾਨਕੁ. ਤਾ ਕਾ ਦਾਸੋ ॥੨੧॥", transliteration = "jin rach rchiaa. tis sabad pchhaanai; naanak. taa kaa daaso ||21||", translation = "One who realizes the Shabad of the One who created the creation - Nanak is his slave. ||21||", hindi = "जिनि रचि रचिआ. तिसु सबदि पछाणै; नानकु. ता का दासो ॥२१॥", punjabi = "ਜਿਸ ਪ੍ਰਭੂ ਨੇ ਰਚਨਾ ਰਚੀ ਹੈ ਜੋ ਮਨੁੱਖ ਉਸ ਨੂੰ ਗੁਰੂ ਦੇ ਸ਼ਬਦ ਵਿਚ ਜੁੜ ਕੇ ਪਛਾਣਦਾ ਹੈ ਨਾਨਕ ਉਸ ਦਾ ਦਾਸ ਹੈ ॥੨੧॥", wordMeaning = "ਜਿਨਿ = ਜਿਸ (ਪ੍ਰਭੂ) ਨੇ ॥੨੧॥", startsAtMs = 0L, endsAtMs = 0L),
