    BaniLine(id = "sidha-gosht-96", gurmukhi = "ਏਸੁ ਸਬਦ ਕਉ, ਜੋ ਅਰਥਾਵੈ; ਤਿਸੁ ਗੁਰ. ਤਿਲੁ, ਨ ਤਮਾਈ ॥", transliteration = "es sabad kau, jo arthaavai; tis gur. til, na tmaaee ||", translation = "One who reveals the meaning of this Shabad is the Guru, who has no greed at all.", hindi = "एसु सबद कउ, जो अरथावै; तिसु गुर. तिलु, न तमाई ॥", punjabi = "ਜੋ ਇਹ ਗੱਲ ਸਮਝਾ ਦੇਵੇ, (ਅਸੀਂ ਮੰਨਾਂਗੇ ਕਿ) ਉਸ ਗੁਰੂ ਨੂੰ ਰਤਾ ਭੀ ਲੋਭ ਨਹੀਂ ਹੈ।", wordMeaning = "ਅਰਥਾਵੈ = ਸਮਝਾ ਦੇਵੇ। ਤਮਾਈ = ਤਮ੍ਹ੍ਹਾ, ਲਾਲਚ।", startsAtMs = 0L, endsAtMs = 0L)
