    BaniLine(id = "sidha-gosht-98", gurmukhi = "ਆਪੇ ਸੁਰਤਾ. ਆਪੇ ਕਰਤਾ; ਕਹੁ ਨਾਨਕ. ਬੀਚਾਰੋ ॥", transliteration = "aape surtaa. aape kartaa; kah naanak. beechaaro ||", translation = "He Himself is consciousness, He Himself is the Creator; share with us, Nanak, your wisdom.\"", hindi = "आपे सुरता. आपे करता; कहु नानक. बीचारो ॥", punjabi = "ਹੇ ਨਾਨਕ! (ਸਾਨੂੰ ਉਸ ਪ੍ਰਭੂ ਦੀ) ਵਿਚਾਰ ਦੱਸ ਜੋ ਆਪ ਹੀ (ਜੀਵਾਂ ਨੂੰ) ਪੈਦਾ ਕਰਨ ਵਾਲਾ ਹੈ ਤੇ ਆਪ ਹੀ, (ਉਹਨਾਂ ਦੀ) ਸੁਣਨ ਵਾਲਾ ਹੈ।", wordMeaning = "ਸੁਰਤਾ = ਸੁਣਨ ਵਾਲਾ।", startsAtMs = 0L, endsAtMs = 0L),
