    BaniLine(id = "sidha-gosht-100", gurmukhi = "ਪੂਰੇ ਗੁਰ ਤੇ ਸਾਚੁ ਕਮਾਵੈ; ਗਤਿ ਮਿਤਿ ਸਬਦੇ ਪਾਈ ॥੨੨॥", transliteration = "poore gur te saach kmaavai; gat mit sabde paaee ||22||", translation = "Through the Perfect Guru, live the Truth; through the Word of the Shabad, the state of dignity is attained. ||22||", hindi = "पूरे गुर ते साचु कमावै; गति मिति सबदे पाई ॥२२॥", punjabi = "ਪੂਰੇ ਗੁਰੂ ਦੀ ਰਾਹੀਂ ਮਨੁੱਖ ਸੱਚੇ ਪ੍ਰਭੂ ਦੇ (ਸਿਮਰਨ ਦੀ) ਕਮਾਈ ਕਰਦਾ ਹੈ, ਇਹ ਗੱਲ ਗੁਰੂ ਦੇ ਸ਼ਬਦ ਤੋਂ ਹੀ ਮਿਲਦੀ ਹੈ ਕਿ ਪ੍ਰਭੂ ਕਿਹੋ ਜਿਹਾ ਹੈ ਤੇ ਕੇਡਾ (ਬੇਅੰਤ) ਹੈ ॥੨੨॥", wordMeaning = "ਗਤਿ = ਹਾਲਤ। ਮਿਤਿ = ਮਾਪ ॥੨੨॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-101", gurmukhi = "ਆਦਿ ਕਉ ਬਿਸਮਾਦੁ ਬੀਚਾਰੁ ਕਥੀਅਲੇ; ਸੁੰਨ ਨਿਰੰਤਰਿ ਵਾਸੁ ਲੀਆ ॥", transliteration = "aad kau bismaad beechaar ktheeale; sunn nirantar vaas leeaa ||", translation = "We can only express a sense of wonder about the beginning. The absolute abided endlessly deep within Himself then.", hindi = "आदि कउ बिसमादु बीचारु कथीअले; सुंन निरंतरि वासु लीआ ॥", punjabi = "(ਪਉੜੀ ਨੰ: ੨੧ ਤੇ ੨੨ ਦਾ ਉੱਤਰ:) ਸ੍ਰਿਸ਼ਟੀ ਦੇ ਮੁੱਢ ਦਾ ਵੀਚਾਰ ਤਾਂ \"ਅਸਚਰਜ, ਅਸਚਰਜ\" ਹੀ ਕਿਹਾ ਜਾ ਸਕਦਾ ਹੈ, (ਤਦੋਂ) ਇੱਕ-ਰਸ ਅਫੁਰ ਪਰਮਾਤਮਾ ਦਾ ਹੀ ਵਜੂਦ ਸੀ।", wordMeaning = "ਬਿਸਮਾਦੁ = ਅਸਚਰਜ। ਨਿਰੰਤਰਿ = ਇੱਕ-ਰਸ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-102", gurmukhi = "ਅਕਲਪਤ ਮੁਦ੍ਰਾ. ਗੁਰ ਗਿਆਨੁ ਬੀਚਾਰੀਅਲੇ; ਘਟਿ ਘਟਿ ਸਾਚਾ, ਸਰਬ ਜੀਆ ॥", transliteration = "akalapat mudraa. gur giaan beechaareeale; ghat ghat saachaa, sarab jeeaa ||", translation = "Consider freedom from desire to be the ear-rings of the Guru's spiritual wisdom. The True Lord, the Soul of all, dwells within each and every heart.", hindi = "अकलपत मुद्रा. गुर गिआनु बीचारीअले; घटि घटि साचा, सरब जीआ ॥", punjabi = "ਗਿਆਨ ਦਾ ਅਸਲੀ ਸਾਧਨ ਇਹ ਸਮਝੋ ਕਿ ਸਤਿਗੁਰੂ ਤੋਂ ਮਿਲਿਆ ਗਿਆਨ ਹੋਵੇ (ਭਾਵ, ਗਿਆਨ ਪ੍ਰਾਪਤ ਕਰਨ ਦਾ ਅਸਲੀ ਸਾਧਨ ਸਤਿਗੁਰੂ ਦੀ ਸਰਣ ਹੀ ਹੈ)। ਹਰੇਕ ਘਟ ਵਿਚ, ਸਾਰੇ ਜੀਵਾਂ ਵਿਚ, ਸਦਾ ਕਾਇਮ ਰਹਿਣ ਵਾਲਾ ਪ੍ਰਭੂ ਹੀ ਵੱਸਦਾ ਹੈ।", wordMeaning = "ਕਲਪਤ = ਬਣਾਈ ਹੋਈ, ਨਕਲੀ, ਫ਼ਰਜ਼ੀ। ਅਕਲਪਤ = ਅਸਲੀ। ਮੁਦ੍ਰਾ = ਸਾਧਨ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-103", gurmukhi = "ਗੁਰ ਬਚਨੀ ਅਵਿਗਤਿ ਸਮਾਈਐ; ਤਤੁ ਨਿਰੰਜਨੁ ਸਹਜਿ ਲਹੈ ॥", transliteration = "gur bachnee avigat smaaeeai; tat niranjan sahaj lhai ||", translation = "Through the Guru's Word, one merges in the absolute, and intuitively receives the immaculate essence.", hindi = "गुर बचनी अविगति समाईऐ; ततु निरंजनु सहजि लहै ॥", punjabi = "ਅਦ੍ਰਿਸ਼ਟ ਪ੍ਰਭੂ ਵਿਚ ਸਤਿਗੁਰੂ ਦੇ ਸ਼ਬਦ ਦੀ ਰਾਹੀਂ ਲੀਨ ਹੋਈਦਾ ਹੈ, (ਗੁਰ-ਸ਼ਬਦ ਦੀ ਰਾਹੀਂ) ਅਡੋਲ ਅਵਸਥਾ ਵਿਚ ਟਿਕਿਆਂ ਜਗਤ ਦਾ ਮੂਲ ਨਿਰੰਜਨ (ਮਾਇਆ ਤੋਂ ਰਹਿਤ ਪ੍ਰਭੂ) ਲੱਭ ਪੈਂਦਾ ਹੈ।", wordMeaning = "ਅਵਿਗਤਿ = ਅਵਿਗਤ ਵਿਚ, ਅੱਵਿਅਕਤ ਹਰੀ ਵਿਚ, ਅਦ੍ਰਿਸ਼ਟ ਪ੍ਰਭੂ ਵਿਚ। ਸਹਜਿ = ਅਡੋਲਤਾ ਵਿਚ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-104", gurmukhi = "ਨਾਨਕ. ਦੂਜੀ ਕਾਰ, ਨ ਕਰਣੀ ਸੇਵੈ; ਸਿਖੁ ਸੁ ਖੋਜਿ ਲਹੈ ॥", transliteration = "naanak. doojee kaar, na karnee sevai; sikh su khoj lhai ||", translation = "O Nanak, that Sikh who seeks and finds the Way does not serve any other.", hindi = "नानक. दूजी कार, न करणी सेवै; सिखु सु खोजि लहै ॥", punjabi = "(ਨਿਰੰਜਨ ਨੂੰ ਲੱਭਣ ਲਈ ਗੁਰੂ ਦੇ ਬਚਨਾਂ ਉੱਤੇ ਤੁਰਨ ਤੋਂ ਛੁਟ) ਹੋਰ ਕੋਈ ਕਾਰ ਕਰਨ ਦੀ ਲੋੜ ਨਹੀਂ, ਜੋ ਸਿੱਖ (ਗੁਰ-ਆਸ਼ੇ ਅਨੁਸਾਰ) ਸੇਵਾ ਕਰਦਾ ਹੈ ਉਹ ਭਾਲ ਕੇ 'ਨਿਰੰਜਨ' ਨੂੰ ਲੱਭ ਲੈਂਦਾ ਹੈ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-105", gurmukhi = "ਹੁਕਮੁ ਬਿਸਮਾਦੁ ਹੁਕਮਿ ਪਛਾਣੈ; ਜੀਅ ਜੁਗਤਿ ਸਚੁ ਜਾਣੈ ਸੋਈ ॥", transliteration = "hukam bismaad hukam pchhaanai; jeea jugat sach jaanai soee ||", translation = "Wonderful and amazing is His Command; He alone realizes His Command and knows the true way of life of His creatures.", hindi = "हुकमु बिसमादु हुकमि पछाणै; जीअ जुगति सचु जाणै सोई ॥", punjabi = "ਹੇ ਨਾਨਕ! 'ਹੁਕਮ' ਮੰਨਣਾ ਅਸਚਰਜ (ਖ਼ਿਆਲ) ਹੈ ਭਾਵ, ਇਹ (ਖ਼ਿਆਲ ਕਿ ਗੁਰੂ ਦੇ ਹੁਕਮ ਵਿਚ ਤੁਰਿਆਂ \"ਅਵਿਗਤ\" ਵਿਚ ਸਮਾਈਦਾ ਹੈ ਹੈਰਾਨਗੀ ਪੈਦਾ ਕਰਨ ਵਾਲਾ ਹੈ; ਪਰ) ਜੋ ਮਨੁੱਖ 'ਹੁਕਮ' ਵਿਚ (ਤੁਰ ਕੇ 'ਹੁਕਮ' ਨੂੰ) ਪਛਾਣਦਾ ਹੈ ਉਹ ਜੀਵਨ ਦੀ (ਸਹੀ) ਜੁਗਤਿ ਤੇ 'ਸਚ' ਨੂੰ ਜਾਣ ਲੈਂਦਾ ਹੈ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-106", gurmukhi = "ਆਪੁ ਮੇਟਿ ਨਿਰਾਲਮੁ ਹੋਵੈ; ਅੰਤਰਿ ਸਾਚੁ. ਜੋਗੀ ਕਹੀਐ ਸੋਈ ॥੨੩॥", transliteration = "aap met niraalam hovai; antar saach. jogee kheeai soee ||23||", translation = "One who eradicates his self-conceit becomes free of desire; he alone is a Yogi, who enshrines the True Lord deep within. ||23||", hindi = "आपु मेटि निरालमु होवै; अंतरि साचु. जोगी कहीऐ सोई ॥२३॥", punjabi = "ਉਹ 'ਆਪਾ ਭਾਵ' ਮਿਟਾ ਕੇ (ਦੁਨੀਆ ਵਿਚ ਰਹਿੰਦਾ ਹੋਇਆ ਭੀ ਦੁਨੀਆ ਤੋਂ) ਵੱਖਰਾ ਹੁੰਦਾ ਹੈ (ਕਿਉਂਕਿ ਉਸ ਦੇ) ਹਿਰਦੇ ਵਿਚ ਸਦਾ ਕਾਇਮ ਰਹਿਣ ਵਾਲਾ ਪ੍ਰਭੂ (ਸਾਖਿਆਤ) ਹੈ, (ਬੱਸ!) ਐਸਾ ਮਨੁੱਖ ਹੀ ਜੋਗੀ ਅਖਵਾਣ ਦੇ ਯੋਗ ਹੈ ॥੨੩॥", wordMeaning = "ਨਿਰਾਲਮੁ = ਨਿਰਾਲਾ, ਨਿਰਲੇਪ ॥੨੩॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-107", gurmukhi = "ਅਵਿਗਤੋ ਨਿਰਮਾਇਲੁ ਉਪਜੇ; ਨਿਰਗੁਣ ਤੇ ਸਰਗੁਣੁ ਥੀਆ ॥", transliteration = "avigto nirmaail upje; nirgun te sargun theeaa ||", translation = "From His state of absolute existence, He assumed the immaculate form; from formless, He assumed the supreme form.", hindi = "अविगतो निरमाइलु उपजे; निरगुण ते सरगुणु थीआ ॥", punjabi = "(ਜਦੋਂ) ਅਦ੍ਰਿਸ਼ਟ ਅਵਸਥਾ ਤੋਂ ਨਿਰਮਲ ਪ੍ਰਭੂ ਪਰਗਟ ਹੁੰਦਾ ਹੈ ਤੇ ਨਿਰਗੁਣ ਰੂਪ ਤੋਂ ਸਰਗੁਣ ਬਣਦਾ ਹੈ (ਭਾਵ, ਆਪਣੇ ਅਦ੍ਰਿਸ਼ਟ ਆਤਮਕ ਸਰੂਪ ਤੋਂ ਆਕਾਰ ਵਾਲਾ ਬਣ ਕੇ ਸੂਖਮ ਤੇ ਅਸਥੂਲ ਰੂਪ ਧਾਰ ਲੈਂਦਾ ਹੈ,", wordMeaning = "ਅਵਿਗਤੋ = ਅੱਵਿਅਕਤ ਤੋਂ, ਅਵਿਗਤ ਤੋਂ, ਅਦ੍ਰਿਸ਼ਟ ਤੋਂ। ਉਪਜੇ = ਪਰਗਟ ਹੁੰਦਾ ਹੈ। ਨਿਰਗੁਣ = ਮਾਇਆ ਦੇ ਤਿੰਨ ਗੁਣਾਂ ਤੋਂ ਰਹਿਤ। ਸਰਗੁਣੁ = ਮਾਇਆ ਦੇ ਤਿੰਨ ਗੁਣਾਂ ਸਮੇਤ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-108", gurmukhi = "ਸਤਿਗੁਰ ਪਰਚੈ ਪਰਮ ਪਦੁ ਪਾਈਐ; ਸਾਚੈ ਸਬਦਿ ਸਮਾਇ ਲੀਆ ॥", transliteration = "satigur parchai param pad paaeeai; saachai sabad smaai leeaa ||", translation = "By pleasing the True Guru, the supreme status is obtained, and one is absorbed in the True Word of the Shabad.", hindi = "सतिगुर परचै परम पदु पाईऐ; साचै सबदि समाइ लीआ ॥", punjabi = "ਤਦੋਂ ਇਸ ਦ੍ਰਿਸ਼ਟਮਾਨ ਸੰਸਾਰ ਵਿਚੋਂ ਜਿਸ ਜੀਵ ਦਾ ਮਨ ਸਤਿਗੁਰੂ ਦੇ ਸ਼ਬਦ ਨਾਲ ਪਤੀਜਦਾ ਜਾਂਦਾ ਹੈ (ਉਸ ਜੀਵ ਨੂੰ) ਉੱਚੀ ਆਤਮਕ ਅਵਸਥਾ ਪ੍ਰਾਪਤ ਹੋ ਜਾਂਦੀ ਹੈ (ਤਦੋਂ ਸਮਝੋ ਕਿ) ਗੁਰੂ ਦੇ ਸ਼ਬਦ ਦੀ ਰਾਹੀਂ ਸੱਚੇ ਪ੍ਰਭੂ ਨੇ (ਉਸ ਨੂੰ ਆਪਣੇ ਵਿਚ) ਲੀਨ ਕਰ ਲਿਆ ਹੈ।", wordMeaning = "ਪਰਚੈ = ਪਤੀਜਣ ਨਾਲ। ਪਰਮ ਪਦੁ = ਉੱਚੀ ਆਤਮਕ ਅਵਸਥਾ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-109", gurmukhi = "ਏਕੇ ਕਉ ਸਚੁ ਏਕਾ ਜਾਣੈ; ਹਉਮੈ ਦੂਜਾ ਦੂਰਿ ਕੀਆ ॥", transliteration = "eke kau sach ekaa jaanai; haumai doojaa door keeaa ||", translation = "He knows the True Lord as the One and only; he sends his egotism and duality far away.", hindi = "एके कउ सचु एका जाणै; हउमै दूजा दूरि कीआ ॥", punjabi = "(ਤਦੋਂ) ਉਹ ਕੇਵਲ ਇਕ ਪ੍ਰਭੂ ਨੂੰ ਹੀ (ਸਦਾ ਰਹਿਣ ਵਾਲੀ ਹਸਤੀ) ਜਾਣਦਾ ਹੈ, ਉਸ ਨੇ ਹਉਮੈ ਅਤੇ ਦੂਜਾ-ਭਾਵ (ਭਾਵ, ਪ੍ਰਭੂ ਤੋਂ ਬਿਨਾ ਕਿਸੇ ਹੋਰ ਅਜੇਹੀ ਹਸਤੀ ਦੀ ਸੰਭਾਵਨਾ ਦਾ ਖ਼ਿਆਲ) ਦੂਰ ਕਰ ਲਿਆ ਹੁੰਦਾ ਹੈ,", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-110", gurmukhi = "ਸੋ ਜੋਗੀ ਗੁਰਸਬਦੁ ਪਛਾਣੈ; ਅੰਤਰਿ ਕਮਲੁ ਪ੍ਰਗਾਸੁ ਥੀਆ ॥", transliteration = "so jogee gurasabad pchhaanai; antar kamal pragaas theeaa ||", translation = "He alone is a Yogi, who realizes the Word of the Guru's Shabad; the lotus of the heart blossoms forth within.", hindi = "सो जोगी गुरसबदु पछाणै; अंतरि कमलु प्रगासु थीआ ॥", punjabi = "(ਬੱਸ!) ਉਹੀ (ਅਸਲ) ਜੋਗੀ ਹੈ, ਉਹ ਸਤਿਗੁਰੂ ਦੇ ਸ਼ਬਦ ਨੂੰ ਸਮਝਦਾ ਹੈ ਉਸ ਦੇ ਅੰਦਰ (ਰਿਹਦਾ-ਰੂਪ) ਕੌਲ ਫੁੱਲ ਖਿੜ ਪਿਆ ਹੁੰਦਾ ਹੈ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-111", gurmukhi = "ਜੀਵਤੁ ਮਰੈ. ਤਾ ਸਭੁ ਕਿਛੁ ਸੂਝੈ; ਅੰਤਰਿ ਜਾਣੈ ਸਰਬ ਦਇਆ ॥", transliteration = "jeevat mrai. taa sabh kichh soojhai; antar jaanai sarab daiaa ||", translation = "If one remains dead while yet alive, then he understands everything; he knows the Lord deep within himself, who is kind and compassionate to all.", hindi = "जीवतु मरै. ता सभु किछु सूझै; अंतरि जाणै सरब दइआ ॥", punjabi = "ਜੋ ਮਨੁੱਖ ਜੀਊਂਦਾ ਹੀ ਮਰਦਾ ਹੈ (ਭਾਵ, 'ਹਉਮੈ' ਦਾ ਤਿਆਗ ਕਰਦਾ ਹੈ, ਸੁਆਰਥ ਮਿਟਾਂਦਾ ਹੈ) ਉਸ ਨੂੰ (ਜ਼ਿੰਦਗੀ ਦੇ) ਹਰੇਕ (ਪਹਿਲੂ) ਦੀ ਸਮਝ ਆ ਜਾਂਦੀ ਹੈ, ਉਹ ਮਨੁੱਖ ਸਾਰੇ ਜੀਵਾਂ ਉਤੇ ਦਇਆ ਕਰਨ (ਦਾ ਅਸੂਲ) ਆਪਣੇ ਮਨ ਵਿਚ ਪੱਕਾ ਕਰ ਲੈਂਦਾ ਹੈ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-112", gurmukhi = "ਨਾਨਕ. ਤਾ ਕਉ ਮਿਲੈ ਵਡਾਈ; ਆਪੁ ਪਛਾਣੈ ਸਰਬ ਜੀਆ ॥੨੪॥", transliteration = "naanak. taa kau milai vdaaee; aap pchhaanai sarab jeeaa ||24||", translation = "O Nanak, he is blessed with glorious greatness; he realizes himself in all beings. ||24||", hindi = "नानक. ता कउ मिलै वडाई; आपु पछाणै सरब जीआ ॥२४॥", punjabi = "ਹੇ ਨਾਨਕ! ਉਸੇ ਮਨੁੱਖ ਨੂੰ ਇੱਜ਼ਤ ਮਿਲਦੀ ਹੈ, ਉਹ ਸਾਰੇ ਜੀਵਾਂ ਵਿਚ ਆਪਣੇ ਆਪ ਨੂੰ ਵੇਖਦਾ ਹੈ (ਭਾਵ, ਉਹ ਉਸੇ ਜੋਤਿ ਨੂੰ ਸਭ ਵਿਚ ਵੇਖਦਾ ਹੈ ਜੋ ਉਸ ਦੇ ਆਪਣੇ ਅੰਦਰ ਹੈ) ॥੨੪॥", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-113", gurmukhi = "ਸਾਚੌ ਉਪਜੈ ਸਾਚਿ ਸਮਾਵੈ; ਸਾਚੇ ਸੂਚੇ ਏਕ ਮਇਆ ॥", transliteration = "saachau upjai saach smaavai; saache sooche ek maiaa ||", translation = "We emerge from Truth, and merge into Truth again. The pure being merges into the One True Lord.", hindi = "साचौ उपजै साचि समावै; साचे सूचे एक मइआ ॥", punjabi = "(ਗੁਰਮੁਖਿ) ਸੱਚੇ ਪ੍ਰਭੂ ਤੋਂ ਪੈਦਾ ਹੁੰਦਾ ਹੈ ਤੇ ਸੱਚੇ ਵਿਚ ਹੀ ਲੀਨ ਰਹਿੰਦਾ ਹੈ; ਪ੍ਰਭੂ ਤੇ ਗੁਰਮੁਖਿ ਇੱਕ-ਰੂਪ ਹੋ ਜਾਂਦੇ ਹਨ।", wordMeaning = "ਸਾਚੌ = ਸਦਾ ਕਾਇਮ ਰਹਿਣ ਵਾਲੇ ਪ੍ਰਭੂ ਤੋਂ। ਸੂਚੇ = ਪਵਿਤ੍ਰ ਮਨੁੱਖ। ਏਕ ਮਇਆ = ਇਕ-ਮਿਕ, ਪੰਨਾ ਇੱਕ-ਰੂਪ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-114", gurmukhi = "ਝੂਠੇ ਆਵਹਿ ਠਵਰ. ਨ ਪਾਵਹਿ; ਦੂਜੈ ਆਵਾ ਗਉਣੁ ਭਇਆ ॥", transliteration = "jhoothe aavah thavar. na paavah; doojai aavaa gaun bhaiaa ||", translation = "The false come, and find no place of rest; in duality, they come and go.", hindi = "झूठे आवहि ठवर. न पावहि; दूजै आवा गउणु भइआ ॥", punjabi = "ਪਰ ਝੂਠੇ (ਭਾਵ, ਨਾਸਵੰਤ ਮਾਇਆ ਵਿਚ ਲੱਗੇ ਹੋਏ ਬੰਦੇ) ਜਗਤ ਆਉਂਦੇ ਹਨ, ਉਹਨਾਂ ਨੂੰ ਮਨ ਦਾ ਟਿਕਾਉ ਨਹੀਂ ਹਾਸਲ ਹੁੰਦਾ (ਸੋ ਇਸ) ਦੂਜੇ-ਭਾਵ ਦੇ ਕਾਰਣ ਉਹਨਾਂ ਦਾ ਜਨਮ ਮਰਨ ਦਾ ਚੱਕਰ ਬਣਿਆ ਰਹਿੰਦਾ ਹੈ।", wordMeaning = "ਆਵਾਗਉਣੁ = ਜਨਮ ਮਰਨ ਦਾ ਗੇੜ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-115", gurmukhi = "ਆਵਾ ਗਉਣੁ ਮਿਟੈ. ਗੁਰਸਬਦੀ; ਆਪੇ ਪਰਖੈ ਬਖਸਿ ਲਇਆ ॥", transliteration = "aavaa gaun mitai. gurasabdee; aape parkhai bakhas laiaa ||", translation = "This coming and going in reincarnation is ended through the Word of the Guru's Shabad; the Lord Himself analyzes and grants His forgiveness.", hindi = "आवा गउणु मिटै. गुरसबदी; आपे परखै बखसि लइआ ॥", punjabi = "ਇਹ ਜਨਮ ਮਰਨ ਦਾ ਚੱਕਰ ਸਤਿਗੁਰੂ ਦੇ ਸ਼ਬਦ ਦੀ ਰਾਹੀਂ ਮਿਟਦਾ ਹੈ (ਗੁਰ-ਸ਼ਬਦ ਵਿਚ ਜੁੜੇ ਮਨੁੱਖ ਨੂੰ) ਪ੍ਰਭੂ ਆਪ ਪਛਾਣ ਲੈਂਦਾ ਹੈ, ਤੇ (ਉਸ ਉਤੇ) ਮੇਹਰ ਕਰਦਾ ਹੈ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-116", gurmukhi = "ਏਕਾ ਬੇਦਨ ਦੂਜੈ ਬਿਆਪੀ; ਨਾਮੁ ਰਸਾਇਣੁ ਵੀਸਰਿਆ ॥", transliteration = "ekaa bedan doojai biaapee; naam rsaain veesriaa ||", translation = "One who suffers from the disease of duality, forgets the Naam, the source of nectar.", hindi = "एका बेदन दूजै बिआपी; नामु रसाइणु वीसरिआ ॥", punjabi = "(ਪਰ ਜਿਨ੍ਹਾਂ ਨੂੰ) ਸਾਰੇ-ਰਸਾਂ-ਦਾ-ਘਰ-ਪ੍ਰਭੂ ਦਾ ਨਾਮ ਵਿੱਸਰ ਜਾਂਦਾ ਹੈ ਉਹਨਾਂ ਨੂੰ ਦੂਜੇ-ਭਾਵ ਵਿਚ ਫਸਣ ਦੇ ਕਾਰਨ ਇਹ ਹਉਮੈ ਦੀ ਪੀੜਾ ਸਤਾਂਦੀ ਹੈ।", wordMeaning = "ਬੇਦਨ = ਵੇਦਨ, ਪੀੜ, ਦੁੱਖ। ਦੂਜੈ = ਪ੍ਰਭੂ ਤੋਂ ਬਿਨਾ ਹੋਰ ਨਾਲ ਪਿਆਰ ਦੇ ਕਾਰਨ। ਬਿਆਪੀ = ਸਤਾ ਰਹੀ ਹੈ। ਰਸਾਇਣੁ = (ਰਸ-ਅਯਨ) ਰਸਾਂ ਦਾ ਘਰ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-117", gurmukhi = "ਸੋ ਬੂਝੈ. ਜਿਸੁ ਆਪਿ ਬੁਝਾਏ; ਗੁਰ ਕੈ ਸਬਦਿ. ਸੁ ਮੁਕਤੁ ਭਇਆ ॥", transliteration = "so boojhai. jis aap bujhaae; gur kai sabad. su mukat bhaiaa ||", translation = "He alone understands, whom the Lord inspires to understand. Through the Word of the Guru's Shabad, one is liberated.", hindi = "सो बूझै. जिसु आपि बुझाए; गुर कै सबदि. सु मुकतु भइआ ॥", punjabi = "(ਇਹ ਭੇਤ) ਉਹ ਮਨੁੱਖ ਸਮਝਦਾ ਹੈ ਜਿਸ ਨੂੰ ਪ੍ਰਭੂ ਆਪ ਸਮਝ ਬਖ਼ਸ਼ਦਾ ਹੈ, ਗੁਰੂ ਦੇ ਸ਼ਬਦ ਵਿਚ ਜੁੜਨ ਦੇ ਕਾਰਨ ਉਹ ਮਨੁੱਖ (ਹਉਮੈ ਤੋਂ) ਆਜ਼ਾਦ ਹੋ ਜਾਂਦਾ ਹੈ।", wordMeaning = "ਆਪਿ = {ਪਉੜੀ ਨੰ: ੨੪ ਵਿਚ ਲਫ਼ਜ਼ 'ਆਪੁ' ਤੇ ਇਸ ਲਫ਼ਜ਼ 'ਆਪਿ' ਦਾ ਫ਼ਰਕ ਸਮਝਣ ਲਈ ਵੇਖੋ 'ਗੁਰਬਾਣੀ ਵਿਆਕਰਣ'}।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-118", gurmukhi = "ਨਾਨਕ. ਤਾਰੇ ਤਾਰਣਹਾਰਾ; ਹਉਮੈ ਦੂਜਾ ਪਰਹਰਿਆ ॥੨੫॥", transliteration = "naanak. taare taaranhaaraa; haumai doojaa parahriaa ||25||", translation = "O Nanak, the Emancipator emancipates one who drives out egotism and duality. ||25||", hindi = "नानक. तारे तारणहारा; हउमै दूजा परहरिआ ॥२५॥", punjabi = "ਹੇ ਨਾਨਕ! ਜਿਸ ਨੇ ਹਉਮੈ ਤੇ ਦੂਜਾ-ਭਾਵ ਤਿਆਗ ਦਿੱਤਾ ਹੈ ਉਸ ਨੂੰ ਤਾਰਣਹਾਰ ਪ੍ਰਭੂ ਤਾਰ ਲੈਂਦਾ ਹੈ ॥੨੫॥", wordMeaning = "ਪਰਹਰਿਆ = ਦੂਰ ਕੀਤਾ ॥੨੫॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-119", gurmukhi = "ਮਨਮੁਖਿ ਭੂਲੈ; ਜਮ ਕੀ ਕਾਣਿ ॥", transliteration = "manmukh bhoolai; jam kee kaan ||", translation = "The self-willed manmukhs are deluded, under the shadow of death.", hindi = "मनमुखि भूलै; जम की काणि ॥", punjabi = "ਜੋ ਮਨੁੱਖ ਆਪਣੇ ਮਨ ਦੇ ਪਿੱਛੇ ਤੁਰਦਾ ਹੈ ਉਹ (ਜੀਵਨ ਦਾ ਸਹੀ ਰਸਤਾ) ਖੁੰਝ ਜਾਂਦਾ ਹੈ ਤੇ ਜਮ ਦੀ ਮੁਥਾਜੀ ਵਿਚ ਹੋ ਜਾਂਦਾ ਹੈ,", wordMeaning = "ਕਾਣਿ = ਮੁਥਾਜੀ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-120", gurmukhi = "ਪਰ ਘਰੁ ਜੋਹੈ; ਹਾਣੇ ਹਾਣਿ ॥", transliteration = "par ghar johai; haane haan ||", translation = "They look into the homes of others, and lose.", hindi = "पर घरु जोहै; हाणे हाणि ॥", punjabi = "ਪਰਾਇਆ ਘਰ ਤੱਕਦਾ ਹੈ, ਉਸ ਨੂੰ (ਇਸ ਕੁਕਰਮ ਵਿਚ) ਘਾਟਾ ਹੀ ਘਾਟਾ ਰਹਿੰਦਾ ਹੈ।", wordMeaning = "ਜੋਹੈ = ਤੱਕਦਾ ਹੈ। ਹਾਣੇ ਹਾਣਿ = ਹਾਣਿ ਹੀ ਹਾਣਿ, ਘਾਟਾ ਹੀ ਘਾਟਾ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-121", gurmukhi = "ਮਨਮੁਖਿ ਭਰਮਿ; ਭਵੈ ਬੇਬਾਣਿ ॥", transliteration = "manmukh bharam; bhvai bebaan ||", translation = "The manmukhs are confused by doubt, wandering in the wilderness.", hindi = "मनमुखि भरमि; भवै बेबाणि ॥", punjabi = "ਭੁਲੇਖੇ ਵਿਚ ਪਿਆ ਹੋਇਆ ਮਨਮੁਖ (ਮਾਨੋ) ਜੰਗਲ ਵਿਚ ਭਟਕ ਰਿਹਾ ਹੈ,", wordMeaning = "ਭਰਮਿ = ਭਰਮ ਵਿਚ, ਭੁਲੇਖੇ ਵਿਚ। ਬੇਬਾਣਿ = ਜੰਗਲ ਵਿਚ।", startsAtMs = 0L, endsAtMs = 0L),
