    BaniLine(id = "sidha-gosht-129", gurmukhi = "ਗੁਰਮੁਖਿ ਰੋਮਿ ਰੋਮਿ ਹਰਿ ਧਿਆਵੈ ॥", transliteration = "gurmukh rom rom har dhiaavai ||", translation = "The Gurmukh meditates on the Lord with every hair of his body.", hindi = "गुरमुखि रोमि रोमि हरि धिआवै ॥", punjabi = "ਗੁਰਮੁਖਿ ਮਨੁੱਖ ਤਨੋਂ ਮਨੋਂ ਪਰਮਾਤਮਾ ਨੂੰ ਯਾਦ ਕਰਦਾ ਹੈ,", wordMeaning = "ਰੋਮਿ ਰੋਮਿ = ਹਰੇਕ ਰੋਮ ਦੀ ਰਾਹੀਂ; (ਭਾਵ,) ਤਨੋਂ ਮਨੋਂ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-130", gurmukhi = "ਨਾਨਕ; ਗੁਰਮੁਖਿ ਸਾਚਿ ਸਮਾਵੈ ॥੨੭॥", transliteration = "naanak; gurmukh saach smaavai ||27||", translation = "O Nanak, the Gurmukh merges in Truth. ||27||", hindi = "नानक; गुरमुखि साचि समावै ॥२७॥", punjabi = "ਹੇ ਨਾਨਕ! (ਬੰਦਗੀ ਦੀ ਰਾਹੀਂ) ਗੁਰਮੁਖ ਸਦਾ ਕਾਇਮ ਰਹਿਣ ਵਾਲੇ ਪ੍ਰਭੂ ਵਿਚ ਲੀਨ ਰਹਿੰਦਾ ਹੈ ॥੨੭॥", wordMeaning = "ਸਾਚਿ = ਸੱਚੇ ਪ੍ਰਭੂ ਵਿਚ ॥੨੭॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-131", gurmukhi = "ਗੁਰਮੁਖਿ ਪਰਚੈ; ਬੇਦ ਬੀਚਾਰੀ ॥", transliteration = "gurmukh parchai; bed beechaaree ||", translation = "The Gurmukh is pleasing to the True Guru; this is contemplation on the Vedas.", hindi = "गुरमुखि परचै; बेद बीचारी ॥", punjabi = "ਜੋ ਮਨੁੱਖ ਗੁਰੂ ਨਾਲ ਡੂੰਘੀ ਸਾਂਝ ਬਣਾ ਲੈਂਦਾ ਹੈ (ਭਾਵ, ਜਿਸ ਨੂੰ ਸਤਿਗੁਰੂ ਵਿਚ ਪੂਰਨ ਵਿਸ਼ਵਾਸ ਹੋ ਜਾਂਦਾ ਹੈ) ਉਹ (ਮਾਨੋ) ਵੇਦਾਂ ਦਾ ਗਿਆਤਾ ਹੋ ਗਿਆ ਹੈ (ਉਸ ਨੂੰ ਵੇਦਾਂ ਦੀ ਲੋੜ ਨਹੀਂ ਰਹਿ ਜਾਂਦੀ)।", wordMeaning = "ਪਰਚਾ = ਡੂੰਘੀ ਸਾਂਝ, ਪਿਆਰ (ਸੰ: परिचिं ਪਰਿਚਿ = ਸਾਂਝ ਬਨਾਣੀ, ਮਿੱਤ੍ਰਤਾ ਕਾਇਮ ਕਰਨੀ)।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-132", gurmukhi = "ਗੁਰਮੁਖਿ ਪਰਚੈ; ਤਰੀਐ ਤਾਰੀ ॥", transliteration = "gurmukh parchai; treeai taaree ||", translation = "Pleasing the True Guru, the Gurmukh is carried across.", hindi = "गुरमुखि परचै; तरीऐ तारी ॥", punjabi = "ਗੁਰੂ ਨਾਲ ਡੂੰਘੀ ਸਾਂਝ ਬਣਾਇਆਂ ਸੰਸਾਰ-ਸਮੁੰਦਰ ਤੋਂ ਤਰ ਜਾਈਦਾ ਹੈ,", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-133", gurmukhi = "ਗੁਰਮੁਖਿ ਪਰਚੈ; ਸੁ ਸਬਦਿ ਗਿਆਨੀ ॥", transliteration = "gurmukh parchai; su sabad giaanee ||", translation = "Pleasing the True Guru, the Gurmukh receives the spiritual wisdom of the Shabad.", hindi = "गुरमुखि परचै; सु सबदि गिआनी ॥", punjabi = "ਗੁਰ-ਸ਼ਬਦ ਦੀ ਰਾਹੀਂ ਪਰਮਾਤਮਾ ਨਾਲ ਜਾਣ-ਪਛਾਣ ਵਾਲਾ ਹੋ ਜਾਈਦਾ ਹੈ,", wordMeaning = "ਗਿਆਨੀ = ਗਿਆਨ ਵਾਲਾ, ਪ੍ਰਭੂ ਨਾਲ ਡੂੰਘੀ ਜਾਣ = ਪਛਾਣ ਵਾਲਾ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-134", gurmukhi = "ਗੁਰਮੁਖਿ ਪਰਚੈ; ਅੰਤਰ ਬਿਧਿ ਜਾਨੀ ॥", transliteration = "gurmukh parchai; antar bidh jaanee ||", translation = "Pleasing the True Guru, the Gurmukh comes to know the path within.", hindi = "गुरमुखि परचै; अंतर बिधि जानी ॥", punjabi = "ਤੇ ਗੁਰ-ਸ਼ਬਦ ਦੀ ਰਾਹੀਂ ਅੰਦਰਲੇ ਦੀ ਸੂਝ ਪੈ ਜਾਂਦੀ ਹੈ।", wordMeaning = "ਅੰਤਰ = ਅੰਦਰ ਦੀ। (ਨੋਟ: ਪਉੜੀ ਨੰ: ੨੪ ਵਿਚ ਦੇ ਲਫ਼ਜ਼ 'ਅੰਤਰਿ' ਤੇ ਇਸ ਲਫ਼ਜ਼ 'ਅੰਤਰ' ਦਾ ਫ਼ਰਕ ਸਮਝਣ-ਜੋਗ ਹੈ)। ਅੰਤਰਿ = ਆਪਣੇ ਅੰਦਰ। ਅੰਤਰ ਬਿਧਿ = ਅੰਦਰ ਦੀ ਹਾਲਤ}।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-135", gurmukhi = "ਗੁਰਮੁਖਿ ਪਾਈਐ ਅਲਖ ਅਪਾਰੁ ॥", transliteration = "gurmukh paaeeai alakh apaar ||", translation = "The Gurmukh attains the unseen and infinite Lord.", hindi = "गुरमुखि पाईऐ अलख अपारु ॥", punjabi = "ਗੁਰੂ ਦੇ ਸਨਮੁਖ ਹੋਇਆਂ ਅਦ੍ਰਿਸ਼ਟ ਤੇ ਬੇ-ਅੰਤ ਪ੍ਰਭੂ ਮਿਲ ਪੈਂਦਾ ਹੈ;", wordMeaning = "ਅਲਖ = ਜਿਸ ਦੇ ਕੋਈ ਖ਼ਾਸ ਚਿਹਨ ਨਿਸ਼ਾਨ ਜਾਂ ਲੱਛਣ ਨਹੀਂ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-136", gurmukhi = "ਨਾਨਕ; ਗੁਰਮੁਖਿ ਮੁਕਤਿ ਦੁਆਰੁ ॥੨੮॥", transliteration = "naanak; gurmukh mukat duaar ||28||", translation = "O Nanak, the Gurmukh finds the door of liberation. ||28||", hindi = "नानक; गुरमुखि मुकति दुआरु ॥२८॥", punjabi = "ਹੇ ਨਾਨਕ! ਗੁਰੂ ਦੀ ਰਾਹੀਂ ਹੀ (ਹਉਮੈ ਤੋਂ) ਖ਼ਲਾਸੀ ਦਾ ਰਸਤਾ ਲੱਭਦਾ ਹੈ ॥੨੮॥", wordMeaning = "ਦੁਆਰੁ = ਦਰਵਾਜ਼ਾ ॥੨੮॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-137", gurmukhi = "ਗੁਰਮੁਖਿ; ਅਕਥੁ ਕਥੈ ਬੀਚਾਰਿ ॥", transliteration = "gurmukh; akath kthai beechaar ||", translation = "The Gurmukh speaks the unspoken wisdom.", hindi = "गुरमुखि; अकथु कथै बीचारि ॥", punjabi = "ਗੁਰੂ ਦੇ ਦੱਸੇ ਰਾਹ ਤੇ ਤੁਰਨ ਵਾਲਾ ਮਨੁੱਖ (ਗੁਰੂ ਦੀ ਦੱਸੀ) ਵੀਚਾਰ ਨਾਲ ਉਸ ਪ੍ਰਭੂ ਦੇ ਗੁਣ ਗਾਉਂਦਾ ਹੈ ਜਿਸ ਦਾ ਸਹੀ ਸਰੂਪ ਬਿਆਨ ਨਹੀਂ ਹੋ ਸਕਦਾ,", wordMeaning = "ਅਕਥੁ = ਜੋ ਕਥਿਆ ਨਾਹ ਜਾ ਸਕੇ, ਜਿਸ ਦਾ ਸਹੀ ਸਰੂਪ ਬਿਆਨ ਨਾਹ ਕੀਤਾ ਜਾ ਸਕੇ। ਬੀਚਾਰਿ = ਵਿਚਾਰ ਦੀ ਰਾਹੀਂ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-138", gurmukhi = "ਗੁਰਮੁਖਿ; ਨਿਬਹੈ ਸਪਰਵਾਰਿ ॥", transliteration = "gurmukh; nibhai saparvaar ||", translation = "In the midst of his family, the Gurmukh lives a spiritual life.", hindi = "गुरमुखि; निबहै सपरवारि ॥", punjabi = "(ਇਸ ਤਰ੍ਹਾਂ) ਗੁਰਮੁਖ ਘਰਬਾਰੀ ਹੁੰਦਾ ਹੋਇਆ ਹੀ (ਜ਼ਿੰਦਗੀ ਦੀ ਬਾਜ਼ੀ ਵਿਚ) ਪੁੱਗ ਜਾਂਦਾ ਹੈ।", wordMeaning = "ਨਿਬਹੈ = ਪੁੱਗਦਾ ਹੈ। ਸਪਰਵਾਰਿ = ਸ-ਪਰਵਾਰਿ, ਪਰਵਾਰ ਵਿਚ ਰਹਿੰਦਿਆਂ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-139", gurmukhi = "ਗੁਰਮੁਖਿ ਜਪੀਐ; ਅੰਤਰਿ ਪਿਆਰਿ ॥", transliteration = "gurmukh jpeeai; antar piaar ||", translation = "The Gurmukh lovingly meditates deep within.", hindi = "गुरमुखि जपीऐ; अंतरि पिआरि ॥", punjabi = "ਗੁਰੂ ਦੇ ਸਨਮੁਖ ਹੋਇਆਂ ਹੀ ਹਿਰਦੇ ਵਿਚ ਪਿਆਰ ਨਾਲ ਪ੍ਰਭੂ ਨੂੰ ਜਪ ਸਕੀਦਾ ਹੈ,", wordMeaning = "ਅੰਤਰਿ = ਹਿਰਦੇ ਵਿਚ। ਪਿਆਰਿ = ਪਿਆਰ ਨਾਲ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-140", gurmukhi = "ਗੁਰਮੁਖਿ ਪਾਈਐ; ਸਬਦਿ ਅਚਾਰਿ ॥", transliteration = "gurmukh paaeeai; sabad achaar ||", translation = "The Gurmukh obtains the Shabad, and righteous conduct.", hindi = "गुरमुखि पाईऐ; सबदि अचारि ॥", punjabi = "ਤੇ ਗੁਰਸ਼ਬਦ ਦੀ ਰਾਹੀਂ ਉੱਚਾ ਆਚਰਣ ਬਣ ਕੇ ਪ੍ਰਭੂ ਮਿਲਦਾ ਹੈ।", wordMeaning = "ਸਬਦਿ = ਗੁਰਸ਼ਬਦ ਦੀ ਰਾਹੀਂ। ਅਚਾਰਿ = ਆਚਾਰ ਦੀ ਰਾਹੀਂ, ਚੰਗੇ ਆਚਰਨ ਨਾਲ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-141", gurmukhi = "ਸਬਦਿ ਭੇਦਿ ਜਾਣੈ ਜਾਣਾਈ ॥", transliteration = "sabad bhed jaanai jaanaaee ||", translation = "He knows the mystery of the Shabad, and inspires others to know it.", hindi = "सबदि भेदि जाणै जाणाई ॥", punjabi = "(ਗੁਰੂ ਦੇ ਦੱਸੇ ਰਾਹ ਤੇ ਤੁਰਨ ਵਾਲਾ ਮਨੁੱਖ) ਗੁਰੂ ਦੇ ਸ਼ਬਦ ਨਾਲ (ਆਪਣੇ ਮਨ ਨੂੰ) ਪ੍ਰੋ ਕੇ (ਪ੍ਰਭੂ ਨੂੰ) ਪਛਾਣਦਾ ਹੈ ਤੇ ਹੋਰਨਾਂ ਨੂੰ ਪਛਾਣ ਕਰਾਂਦਾ ਹੈ।", wordMeaning = "ਭੇਦਿ = ਵਿੰਨ੍ਹ ਕੇ। ਜਾਣਾਈ = ਜਾਣਾਏ, ਜਣਾਏ, ਹੋਰਨਾਂ ਨੂੰ ਦੱਸਦਾ ਹੈ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-142", gurmukhi = "ਨਾਨਕ; ਹਉਮੈ ਜਾਲਿ ਸਮਾਈ ॥੨੯॥", transliteration = "naanak; haumai jaal smaaee ||29||", translation = "O Nanak, burning away his ego, he merges in the Lord. ||29||", hindi = "नानक; हउमै जालि समाई ॥२९॥", punjabi = "ਹੇ ਨਾਨਕ! ਗੁਰਮੁਖ (ਆਪਣੀ) ਹਉਮੈ (ਖ਼ੁਦ-ਗ਼ਰਜ਼ੀ) ਸਾੜ ਕੇ (ਪ੍ਰਭੂ ਵਿਚ) ਲੀਨ ਰਹਿੰਦਾ ਹੈ ॥੨੯॥", wordMeaning = "ਜਾਲਿ = ਸਾੜ ਕੇ ॥੨੯॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-143", gurmukhi = "ਗੁਰਮੁਖਿ; ਧਰਤੀ ਸਾਚੈ ਸਾਜੀ ॥", transliteration = "gurmukh; dhartee saachai saajee ||", translation = "The True Lord fashioned the earth for the sake of the Gurmukhs.", hindi = "गुरमुखि; धरती साचै साजी ॥", punjabi = "ਸੱਚੇ ਪ੍ਰਭੂ ਨੇ ਗੁਰਮੁਖ ਮਨੁੱਖ (ਪੈਦਾ ਕਰਨ) ਵਾਸਤੇ ਧਰਤੀ ਬਣਾਈ ਹੈ;", wordMeaning = "ਸਾਚੈ = ਸੱਚੇ ਪ੍ਰਭੂ ਨੇ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-144", gurmukhi = "ਤਿਸ ਮਹਿ; ਓਪਤਿ ਖਪਤਿ ਸੁ ਬਾਜੀ ॥", transliteration = "tis mah; opat khapat su baajee ||", translation = "There, he set in motion the play of creation and destruction.", hindi = "तिस महि; ओपति खपति सु बाजी ॥", punjabi = "ਇਸ ਧਰਤੀ ਵਿਚ ਉਤਪੱਤੀ ਤੇ ਨਾਸ (ਗੁਰਮੁਖਤਾ ਦੇ ਵਿਕਾਸ ਲਈ) ਇਕ ਖੇਡ ਹੈ;", wordMeaning = "ਤਿਸੁ ਮਹਿ = ਉਸ (ਧਰਤੀ) ਵਿਚ। ਓਪਤਿ = ਉਤਪੱਤੀ। ਖਪਤਿ = ਨਾਸ। ਬਾਜੀ = ਖੇਡ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-145", gurmukhi = "ਗੁਰ ਕੈ ਸਬਦਿ ਰਪੈ ਰੰਗੁ ਲਾਇ ॥", transliteration = "gur kai sabad rpai rang laai ||", translation = "One who is filled with the Word of the Guru's Shabad enshrines love for the Lord.", hindi = "गुर कै सबदि रपै रंगु लाइ ॥", punjabi = "ਜਦੋਂ ਮਨੁੱਖ ਗੁਰੂ ਦੇ ਸ਼ਬਦ ਦੀ ਰਾਹੀਂ ਪ੍ਰਭੂ ਨਾਲ ਪਿਆਰ ਜੋੜ ਕੇ (ਪ੍ਰਭੂ ਦੇ ਰੰਗ ਵਿਚ) ਰੰਗਿਆ ਜਾਂਦਾ ਹੈ,", wordMeaning = "ਰਪੈ = ਰੰਗਿਆ ਜਾਂਦਾ ਹੈ। ਰੰਗੁ = ਪਿਆਰ", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-146", gurmukhi = "ਸਾਚਿ ਰਤਉ; ਪਤਿ ਸਿਉ ਘਰਿ ਜਾਇ ॥", transliteration = "saach ratau; pat siu ghar jaai ||", translation = "Attuned to the Truth, he goes to his home with honor.", hindi = "साचि रतउ; पति सिउ घरि जाइ ॥", punjabi = "ਤਾਂ ਸੱਚੇ ਵਿਚ ਰੱਤਾ ਹੋਇਆ (ਗੁਰਮੁਖ) ਇੱਜ਼ਤ ਲੈ ਕੇ ਆਪਣੇ ਘਰ ਵਿਚ ਅੱਪੜਦਾ ਹੈ (ਤੇ ਉਸ ਦੀ ਘੜਨ ਭੱਜਣ ਦੀ ਖੇਡ ਮੁੱਕ ਜਾਂਦੀ ਹੈ)।", wordMeaning = "ਰਤਉ = ਰੱਤਾ ਹੋਇਆ। ਪਤਿ = ਇੱਜ਼ਤ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-147", gurmukhi = "ਸਾਚ ਸਬਦ ਬਿਨੁ; ਪਤਿ. ਨਹੀ ਪਾਵੈ ॥", transliteration = "saach sabad bin; pat. nhee paavai ||", translation = "Without the True Word of the Shabad, no one receives honor.", hindi = "साच सबद बिनु; पति. नही पावै ॥", punjabi = "ਸੱਚੇ ਸ਼ਬਦ ਤੋਂ ਬਿਨਾ ਕੋਈ ਮਨੁੱਖ ਇਜ਼ਤ ਹਾਸਲ ਨਹੀਂ ਕਰ ਸਕਦਾ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-148", gurmukhi = "ਨਾਨਕ. ਬਿਨੁ ਨਾਵੈ; ਕਿਉ ਸਾਚਿ ਸਮਾਵੈ ॥੩੦॥", transliteration = "naanak. bin naavai; kiu saach smaavai ||30||", translation = "O Nanak, without the Name, how can one be absorbed in Truth? ||30||", hindi = "नानक. बिनु नावै; किउ साचि समावै ॥३०॥", punjabi = "ਹੇ ਨਾਨਕ! ਪ੍ਰਭੂ ਦੇ ਨਾਮ ਤੋਂ ਬਿਨਾ ਪ੍ਰਭੂ ਵਿਚ ਮਨੁੱਖ ਕਿਵੇਂ ਸਮਾ ਸਕਦਾ ਹੈ? (ਨਹੀਂ ਸਮਾ ਸਕਦਾ) ॥੩੦॥", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
