    BaniLine(id = "sidha-gosht-166", gurmukhi = "ਨਾਨਕ. ਨਾਮਿ ਰਤੇ; ਤਿਨ ਕਉ ਜੈਕਾਰੁ ॥੩੩॥", transliteration = "naanak. naam rte; tin kau jaikaar ||33||", translation = "O Nanak, attuned to the Naam, their victory is celebrated. ||33||", hindi = "नानक. नामि रते; तिन कउ जैकारु ॥३३॥", punjabi = "ਹੇ ਨਾਨਕ! ਜੋ ਮਨੁੱਖ ਨਾਮ ਵਿਚ ਰੱਤੇ ਹੋਏ ਹਨ, ਉਹਨਾਂ ਨੂੰ (ਸਾਡੀ) ਨਮਸਕਾਰ ਹੈ ॥੩੩॥", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-167", gurmukhi = "ਪੂਰੇ ਗੁਰ ਤੇ; ਨਾਮੁ ਪਾਇਆ ਜਾਇ ॥", transliteration = "poore gur te; naam paaiaa jaai ||", translation = "Through the Perfect Guru, one obtains the Naam, the Name of the Lord.", hindi = "पूरे गुर ते; नामु पाइआ जाइ ॥", punjabi = "(ਪ੍ਰਭੂ ਦਾ) ਨਾਮ ਗੁਰੂ ਤੋਂ ਮਿਲਦਾ ਹੈ;", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-168", gurmukhi = "ਜੋਗ ਜੁਗਤਿ; ਸਚਿ ਰਹੈ ਸਮਾਇ ॥", transliteration = "jog jugat; sach rhai smaai ||", translation = "The Way of Yoga is to remain absorbed in Truth.", hindi = "जोग जुगति; सचि रहै समाइ ॥", punjabi = "ਸੱਚੇ ਪ੍ਰਭੂ ਵਿਚ ਲੀਨ ਰਹਿਣਾ-ਇਹੀ ਹੈ (ਅਸਲ) ਜੋਗ ਦੀ ਜੁਗਤੀ।", wordMeaning = "ਸਚਿ = ਸੱਚ ਵਿਚ, ਸਦਾ ਕਾਇਮ ਰਹਿਣ ਵਾਲੇ ਪ੍ਰਭੂ ਵਿਚ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-169", gurmukhi = "ਬਾਰਹ ਮਹਿ ਜੋਗੀ ਭਰਮਾਏ; ਸੰਨਿਆਸੀ ਛਿਅ ਚਾਰਿ ॥", transliteration = "baarah mah jogee bharmaae; sanniaasee chhia chaar ||", translation = "The Yogis wander in the twelve schools of Yoga; the Sannyaasis in six and four.", hindi = "बारह महि जोगी भरमाए; संनिआसी छिअ चारि ॥", punjabi = "(ਪਰ) ਜੋਗੀ ਲੋਕ (ਆਪਣੇ) ਬਾਰਾਂ ਫ਼ਿਰਕਿਆਂ (ਦੀ ਵੰਡ) ਵਿਚ (ਇਸ ਅਸਲ ਨਿਸ਼ਾਨੇ ਤੋਂ) ਭੁੱਲ ਰਹੇ ਹਨ ਤੇ ਸੰਨਿਆਸੀ ਲੋਕ (ਆਪਣੇ) ਦਸ ਫ਼ਿਰਕਿਆਂ (ਦੇ ਵਖੋ ਵੱਖ ਸਾਧਨਾਂ) ਵਿਚ।", wordMeaning = "ਬਾਰਹ = ਜੋਗੀਆਂ ਦੇ ਬਾਰਾਂ ਫ਼ਿਰਕੇ: ਹੇਤੂ, ਪਾਵ, ਆਈ, ਗਮ੍ਯ, ਪਾਗਲ, ਕੰਥੜੀ, ਬਨ, ਧ੍ਵਜ, ਚੋਲੀ, ਰਾਵਲ ਅਤੇ ਦਾਸ। ਛਿਅ ਚਾਰਿ = (੬+੪) ਦਸ ਫ਼ਿਰਕੇ ਸੰਨਿਆਸੀਆਂ ਦੇ; ਤੀਰਥ, ਆਸ੍ਰਮ, ਬਨ, ਆਰੰਨ੍ਯ, ਗਿਰਿ, ਪਰਬਤ, ਸਾਗਰ, ਸਰਸ੍ਵਤ, ਭਾਰਤੀ, ਪੁਰੀ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-170", gurmukhi = "ਗੁਰ ਕੈ ਸਬਦਿ. ਜੋ ਮਰਿ ਜੀਵੈ; ਸੋ ਪਾਏ ਮੋਖ ਦੁਆਰੁ ॥", transliteration = "gur kai sabad. jo mar jeevai; so paae mokh duaar ||", translation = "One who remains dead while yet alive, through the Word of the Guru's Shabad, finds the door of liberation.", hindi = "गुर कै सबदि. जो मरि जीवै; सो पाए मोख दुआरु ॥", punjabi = "ਜੋ ਮਨੁੱਖ ਸਤਿਗੁਰੂ ਦੇ ਸ਼ਬਦ ਦੀ ਰਾਹੀਂ (ਮਾਇਆ ਵਲੋਂ) ਮਰ ਕੇ ਜਿਊਂਦਾ ਹੈ ਉਹ (ਹਉਮੈ ਤੋਂ) ਖ਼ਲਾਸੀ ਦਾ ਰਾਹ ਲੱਭ ਲੈਂਦਾ ਹੈ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-171", gurmukhi = "ਬਿਨੁ ਸਬਦੈ. ਸਭਿ ਦੂਜੈ ਲਾਗੇ; ਦੇਖਹੁ ਰਿਦੈ ਬੀਚਾਰਿ ॥", transliteration = "bin sabdai. sabh doojai laage; dekhah ridai beechaar ||", translation = "Without the Shabad, all are attached to duality. Contemplate this in your heart, and see.", hindi = "बिनु सबदै. सभि दूजै लागे; देखहु रिदै बीचारि ॥", punjabi = "ਹਿਰਦੇ ਵਿਚ ਵਿਚਾਰ ਕੇ ਵੇਖ ਲਵੋ (ਭਾਵ, ਆਪਣਾ ਜ਼ਾਤੀ ਤਜਰਬਾ ਹੀ ਇਸ ਗੱਲ ਦੀ ਗਵਾਹੀ ਦੇ ਦੇਵੇਗਾ ਕਿ) ਗੁਰੂ ਦੇ ਸ਼ਬਦ (ਵਿਚ ਜੁੜਨ) ਤੋਂ ਬਿਨਾ ਸਾਰੇ ਲੋਕ (ਪ੍ਰਭੂ ਨੂੰ ਛੱਡ ਕੇ) ਹੋਰ (ਰੁਝੇਵੇਂ) ਵਿਚ ਲੱਗੇ ਰਹਿੰਦੇ ਹਨ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-172", gurmukhi = "ਨਾਨਕ. ਵਡੇ ਸੇ ਵਡਭਾਗੀ; ਜਿਨੀ ਸਚੁ ਰਖਿਆ ਉਰ ਧਾਰਿ ॥੩੪॥", transliteration = "naanak. vde se vadbhaagee; jinee sach rkhiaa ur dhaar ||34||", translation = "O Nanak, blessed and very fortunate are those who keep the True Lord enshrined in their hearts. ||34||", hindi = "नानक. वडे से वडभागी; जिनी सचु रखिआ उर धारि ॥३४॥", punjabi = "ਹੇ ਨਾਨਕ! ਉਹ ਮਨੁੱਖ ਵੱਡੇ ਹਨ ਤੇ ਵੱਡੇ ਭਾਗਾਂ ਵਾਲੇ ਹਨ ਜਿਨ੍ਹਾਂ ਨੇ ਸੱਚੇ ਪ੍ਰਭੂ ਨੂੰ ਆਪਣੇ ਹਿਰਦੇ ਵਿਚ ਟਿਕਾ ਰੱਖਿਆ ਹੈ ॥੩੪॥", wordMeaning = "ਉਰਧਾਰਿ = ਉਰਿ-ਧਾਰਿ, ਹਿਰਦੇ ਵਿਚ ਧਾਰ ਕੇ। ਉਰ = ਹਿਰਦਾ ॥੩੪॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-173", gurmukhi = "ਗੁਰਮੁਖਿ ਰਤਨੁ ਲਹੈ; ਲਿਵ ਲਾਇ ॥", transliteration = "gurmukh ratan lhai; liv laai ||", translation = "The Gurmukh obtains the jewel, lovingly focused on the Lord.", hindi = "गुरमुखि रतनु लहै; लिव लाइ ॥", punjabi = "ਜੋ ਮਨੁੱਖ ਗੁਰੂ ਦੇ ਕਹੇ ਤੇ ਤੁਰਦਾ ਹੈ ਉਹ (ਪ੍ਰਭੂ ਵਿਚ) ਸੁਰਤ ਜੋੜ ਕੇ ਪ੍ਰਭੂ-ਨਾਮ-ਰੂਪ ਰਤਨ ਲੱਭ ਲੈਂਦਾ ਹੈ,", wordMeaning = "ਗੁਰਮੁਖਿ = ਜੋ ਮਨੁੱਖ ਗੁਰੂ ਦੇ ਸਨਮੁਖ ਹੈ। ਰਤਨੁ = ਪ੍ਰਭੂ ਦਾ ਨਾਮ-ਰੂਪ ਕੀਮਤੀ ਪਦਾਰਥ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-174", gurmukhi = "ਗੁਰਮੁਖਿ; ਪਰਖੈ ਰਤਨੁ ਸੁਭਾਇ ॥", transliteration = "gurmukh; parkhai ratan subhaai ||", translation = "The Gurmukh intuitively recognizes the value of this jewel.", hindi = "गुरमुखि; परखै रतनु सुभाइ ॥", punjabi = "ਉਹ ਮਨੁੱਖ (ਇਸ) ਆਪਣੀ ਲਗਨ ਨਾਲ ਹੀ ਨਾਮ-ਰਤਨ ਦੀ ਕਦਰ ਜਾਣ ਲੈਂਦਾ ਹੈ।", wordMeaning = "ਸੁਭਾਇ = ਸੁਤੇ ਹੀ, ਸੁਭਾਵਕ ਹੀ {ਨੋਟ: ਜਿਵੇਂ 'ਨਾਉ' ਤੋਂ 'ਨਾਇ' ਕਰਣ ਕਾਰਕ ਹੈ ਤਿਵੇਂ 'ਭਾਉ' ਤੋਂ 'ਭਾਇ'। 'ਸੁਭਾਉ' ਅਸਲ ਵਿਚ ਹੈ 'ਸ੍ਵਭਾਵ' = ਆਪਣਾ ਪਿਆਰ, ਆਪਣੀ ਲਗਨ}, ਆਪਣੀ ਲਗਨ ਨਾਲ ਹੀ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-175", gurmukhi = "ਗੁਰਮੁਖਿ; ਸਾਚੀ ਕਾਰ ਕਮਾਇ ॥", transliteration = "gurmukh; saachee kaar kmaai ||", translation = "The Gurmukh practices Truth in action.", hindi = "गुरमुखि; साची कार कमाइ ॥", punjabi = "(ਬੱਸ! ਇਹੀ) ਸੱਚੀ ਕਾਰ ਗੁਰਮੁਖ ਕਮਾਂਦਾ ਹੈ,", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-176", gurmukhi = "ਗੁਰਮੁਖਿ; ਸਾਚੇ ਮਨੁ ਪਤੀਆਇ ॥", transliteration = "gurmukh; saache man pteeaai ||", translation = "The mind of the Gurmukh is pleased with the True Lord.", hindi = "गुरमुखि; साचे मनु पतीआइ ॥", punjabi = "ਤੇ ਗੁਰਮੁਖ ਸੱਚੇ ਪ੍ਰਭੂ ਵਿਚ ਆਪਣੇ ਮਨ ਨੂੰ ਗਿਝਾ ਲੈਂਦਾ ਹੈ।", wordMeaning = "ਪਤੀਆਇ = ਤਸੱਲੀ ਕਰਾ ਲੈਂਦਾ ਹੈ, ਗਿਝਾ ਲੈਂਦਾ ਹੈ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-177", gurmukhi = "ਗੁਰਮੁਖਿ ਅਲਖੁ ਲਖਾਏ; ਤਿਸੁ ਭਾਵੈ ॥", transliteration = "gurmukh alakh lkhaae; tis bhaavai ||", translation = "The Gurmukh sees the unseen, when it pleases the Lord.", hindi = "गुरमुखि अलखु लखाए; तिसु भावै ॥", punjabi = "(ਜਦੋਂ) ਉਸ ਪ੍ਰਭੂ ਨੂੰ ਭਾਉਂਦਾ ਹੈ ਤਾਂ ਗੁਰਮੁਖ ਉਸ ਅਲੱਖ ਪ੍ਰਭੂ (ਦੇ ਗੁਣਾਂ ਦੀ ਹੋਰਨਾਂ ਨੂੰ ਭੀ) ਸੂਝ ਪਾ ਦੇਂਦਾ ਹੈ।", wordMeaning = "ਅਲਖੁ = ਜਿਸ ਦਾ ਕੋਈ ਖ਼ਾਸ ਲੱਛਣ ਨਾਹ ਦਿੱਸੇ। ਲਖਾਏ = ਸੂਝ ਪੈਦਾ ਕਰ ਦੇਂਦਾ ਹੈ। ਤਿਸੁ = ਉਸ ਪ੍ਰਭੂ ਨੂੰ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-178", gurmukhi = "ਨਾਨਕ ਗੁਰਮੁਖਿ; ਚੋਟ. ਨ ਖਾਵੈ ॥੩੫॥", transliteration = "naanak gurmukh; chot. na khaavai ||35||", translation = "O Nanak, the Gurmukh does not have to endure punishment. ||35||", hindi = "नानक गुरमुखि; चोट. न खावै ॥३५॥", punjabi = "ਹੇ ਨਾਨਕ! ਜੋ ਮਨੁੱਖ ਗੁਰੂ ਦੇ ਕਹੇ ਤੇ ਤੁਰਦਾ ਹੈ ਉਹ (ਵਿਕਾਰਾਂ ਦੀ) ਮਾਰ ਨਹੀਂ ਖਾਂਦਾ ॥੩੫॥", wordMeaning = "ਚੋਟ = ਮਾਰ ॥੩੫॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-179", gurmukhi = "ਗੁਰਮੁਖਿ; ਨਾਮੁ ਦਾਨੁ ਇਸਨਾਨੁ ॥", transliteration = "gurmukh; naam daan isnaan ||", translation = "The Gurmukh is blessed with the Name, charity and purification.", hindi = "गुरमुखि; नामु दानु इसनानु ॥", punjabi = "ਜੋ ਮਨੁੱਖ ਗੁਰੂ ਦੇ ਦੱਸੇ ਰਾਹ ਤੇ ਤੁਰਦਾ ਹੈ, ਉਸ ਦਾ ਨਾਮ ਜਪਣਾ ਦਾਨ ਕਰਨਾ ਤੇ ਇਸ਼ਨਾਨ ਕਰਨਾ ਪ੍ਰਵਾਨ ਹੈ।", wordMeaning = "ਗੁਰਮੁਖਿ ਨਾਮੁ = ਗੁਰਮੁਖਿ ਮਨੁੱਖ ਦਾ ਹੀ ਨਾਮ (ਜਪਣਾ ਪ੍ਰਵਾਨ ਹੈ), ਗੁਰੂ ਦੇ ਹੁਕਮ ਵਿਚ ਤੁਰ ਕੇ ਹੀ ਨਾਮ ਸਿਮਰਨਾ ਠੀਕ ਹੈ। ਸਤਗੁਰੁ ਪੁਰਖ ਨ ਮੰਨਿਓ ਸਬਦਿ ਨ ਲਗੋ ਪਿਆਰ ॥ ਇਸਨਾਨੁ ਦਾਨੁ ਜੇਤਾ ਕਰਹਿ ਦੂਜੈ ਭਾਇ ਖੁਆਰ ਸਿਰੀ ਰਾਗੁ ਮ: ੩ ॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-180", gurmukhi = "ਗੁਰਮੁਖਿ; ਲਾਗੈ ਸਹਜਿ ਧਿਆਨੁ ॥", transliteration = "gurmukh; laagai sahaj dhiaan ||", translation = "The Gurmukh centers his meditation on the celestial Lord.", hindi = "गुरमुखि; लागै सहजि धिआनु ॥", punjabi = "ਗੁਰੂ ਦੇ ਸਨਮੁਖ ਹੋਇਆਂ ਹੀ ਅਡੋਲ ਅਵਸਥਾ ਵਿਚ ਸੁਰਤ ਜੁੜਦੀ ਹੈ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-181", gurmukhi = "ਗੁਰਮੁਖਿ; ਪਾਵੈ ਦਰਗਹ ਮਾਨੁ ॥", transliteration = "gurmukh; paavai daragah maan ||", translation = "The Gurmukh obtains honor in the Court of the Lord.", hindi = "गुरमुखि; पावै दरगह मानु ॥", punjabi = "ਜੋ ਮਨੁੱਖ ਗੁਰੂ ਦੇ ਸਨਮੁਖ ਹੈ ਉਹ ਪ੍ਰਭੂ ਦੀ ਹਜ਼ੂਰੀ ਵਿਚ ਆਦਰ ਪਾਂਦਾ ਹੈ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-182", gurmukhi = "ਗੁਰਮੁਖਿ; ਭਉ ਭੰਜਨੁ ਪਰਧਾਨੁ ॥", transliteration = "gurmukh; bhau bhanjan pardhaan ||", translation = "The Gurmukh obtains the Supreme Lord, the Destroyer of fear.", hindi = "गुरमुखि; भउ भंजनु परधानु ॥", punjabi = "ਉਹ ਉਸ ਪ੍ਰਭੂ ਨੂੰ ਮਿਲ ਪੈਂਦਾ ਹੈ ਜੋ ਡਰ-ਸਹਿਮ ਨਾਸ ਕਰਨ ਵਾਲਾ ਹੈ ਤੇ ਜੋ ਸਭ ਦਾ ਮਾਲਕ ਹੈ।", wordMeaning = "ਭਉ ਭੰਜਨੁ = ਦੁਨੀਆ ਵਾਲੇ ਡਰ-ਸਹਿਮ ਨਾਸ ਕਰਨ ਵਾਲਾ ਪ੍ਰਭੂ। ਪਰਧਾਨੁ = ਸਭ ਦਾ ਮੁਖੀ, ਸਭ ਦਾ ਮਾਲਕ। ਗੁਰਮੁਖਿ...ਪਰਧਾਨੁ = ਗੁਰਮੁਖਿ (ਪਾਵੈ) ਭਉ ਭੰਜਨੁ ਪਰਧਾਨੁ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-183", gurmukhi = "ਗੁਰਮੁਖਿ; ਕਰਣੀ ਕਾਰ ਕਰਾਏ ॥", transliteration = "gurmukh; karnee kaar kraae ||", translation = "The Gurmukh does good deeds, an inspires others to do so.", hindi = "गुरमुखि; करणी कार कराए ॥", punjabi = "ਗੁਰਮੁਖ ਮਨੁੱਖ (ਹੋਰਨਾਂ ਪਾਸੋਂ ਭੀ ਇਹੀ, ਭਾਵ, ਗੁਰੂ ਦੇ ਹੁਕਮ ਵਿਚ ਤੁਰਨ ਵਾਲਾ) ਕਰਨ-ਜੋਗ ਕੰਮ ਕਰਾਂਦਾ ਹੈ,", wordMeaning = "ਕਰਣੀ ਕਾਰ = ਕਰਨ-ਯੋਗ ਕੰਮ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-184", gurmukhi = "ਨਾਨਕ ਗੁਰਮੁਖਿ; ਮੇਲਿ ਮਿਲਾਏ ॥੩੬॥", transliteration = "naanak gurmukh; mel milaae ||36||", translation = "O Nanak, the Gurmukh unites in the Lord's Union. ||36||", hindi = "नानक गुरमुखि; मेलि मिलाए ॥३६॥", punjabi = "(ਤੇ ਇਸ ਤਰ੍ਹਾਂ ਉਹਨਾਂ ਨੂੰ) ਹੇ ਨਾਨਕ! (ਪ੍ਰਭੂ ਦੇ) ਮੇਲ ਵਿਚ ਮਿਲਾ ਦੇਂਦਾ ਹੈ ॥੩੬॥", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
