    BaniLine(id = "sidha-gosht-262", gurmukhi = "ਪ੍ਰਣਵਤਿ ਨਾਨਕੁ; ਕਾਲੁ. ਨ ਖਾਇ ॥੪੯॥", transliteration = "pranavat naanak; kaal. na khaai ||49||", translation = "and then, prays Nanak, one is not consumed by Death. ||49||", hindi = "प्रणवति नानकु; कालु. न खाइ ॥४९॥", punjabi = "ਤੇ ਨਾਨਕ ਬੇਨਤੀ ਕਰਦਾ ਹੈ ਉਸ ਨੂੰ ਮੌਤ ਦਾ ਡਰ ਨਹੀਂ ਵਿਆਪਦਾ ॥੪੯॥", wordMeaning = "ਪ੍ਰਣਵਤਿ = ਬੇਨਤੀ ਕਰਦਾ ਹੈ ॥੪੯॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-263", gurmukhi = "ਨਾਮ ਤਤੁ; ਸਭ ਹੀ ਸਿਰਿ ਜਾਪੈ ॥", transliteration = "naam tat; sabh hee sir jaapai ||", translation = "The essence of the Naam, the Name of the Lord, is known to be the most exalted and excellent of all.", hindi = "नाम ततु; सभ ही सिरि जापै ॥", punjabi = "ਪ੍ਰਭੂ ਦੇ ਨਾਮ ਦੀ ਸੱਚਾਈ (ਹਿਰਦੇ ਵਿਚ ਸਹੀ ਕਰਨੀ) ਸਾਰੇ ਜਾਪਾਂ ਦਾ ਸ਼ਿਰੋਮਣੀ (ਜਾਪ) ਹੈ।", wordMeaning = "ਤਤੁ = ਅਸਲੀਅਤ, ਸੱਚਾਈ। ਨਾਮ ਤਤੁ = ਪ੍ਰਭੂ ਦੇ ਨਾਮ ਦੀ ਸੱਚਾਈ। ਸਭ ਹੀ ਸਿਰਿ ਜਾਪੈ = ਸਾਰੇ ਜਾਪਾਂ ਦੇ ਸਿਰ ਤੇ ਹੈ, ਸਾਰੇ ਜਾਪਾਂ ਤੋਂ ਸ੍ਰੇਸ਼ਟ ਹੈ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-264", gurmukhi = "ਬਿਨੁ ਨਾਵੈ; ਦੁਖੁ ਕਾਲੁ ਸੰਤਾਪੈ ॥", transliteration = "bin naavai; dukh kaal santaapai ||", translation = "Without the Name, one is afflicted by pain and death.", hindi = "बिनु नावै; दुखु कालु संतापै ॥", punjabi = "ਜਦ ਤਕ ਹਿਰਦੇ ਵਿਚ ਨਾਮ (-ਤੱਤ) ਸਹੀ ਨਹੀਂ ਹੁੰਦਾ, (ਮਨੁੱਖ ਨੂੰ ਕਈ ਕਿਸਮ ਦਾ) ਦੁੱਖ ਸਤਾਂਦਾ ਹੈ ਮੌਤ ਦਾ ਡਰ ਦੁਖੀ ਕਰਦਾ ਹੈ।", wordMeaning = "ਸੰਤਾਪੈ = ਦੁਖੀ ਕਰਦਾ ਹੈ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-265", gurmukhi = "ਤਤੋ ਤਤੁ ਮਿਲੈ; ਮਨੁ ਮਾਨੈ ॥", transliteration = "tato tat milai; man maanai ||", translation = "When one's essence merges into the essence, the mind is satisfied and fulfilled.", hindi = "ततो ततु मिलै; मनु मानै ॥", punjabi = "(ਜਦੋਂ ਹਿਰਦੇ ਵਿਚ) ਨਿਰੋਲ ਪ੍ਰਭੂ-ਨਾਮ ਦੀ ਸੱਚਾਈ (ਭਾਵ, ਇਹ ਸਰਧਾ ਕਿ ਪ੍ਰਭੂ ਦਾ ਨਾਮ ਹੀ ਸਦਾ-ਥਿਰ ਰਹਿਣ ਵਾਲਾ ਹੈ) ਪਰਗਟ ਹੋ ਜਾਂਦੀ ਹੈ ਤਾਂ (ਮਨੁੱਖ ਦਾ) ਮਨ (ਉਸ ਸੱਚਾਈ ਵਿਚ) ਪਤੀਜ ਜਾਂਦਾ ਹੈ,", wordMeaning = "ਤਤੋ ਤਤੁ = ਤੱਤ ਹੀ ਤੱਤ, ਨਿਰੋਲ ਤੱਤ, ਨਿਰੋਲ ਪ੍ਰਭੂ-ਨਾਮ ਦੀ ਸੱਚਾਈ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-266", gurmukhi = "ਦੂਜਾ ਜਾਇ; ਇਕਤੁ ਘਰਿ ਆਨੈ ॥", transliteration = "doojaa jaai; ikat ghar aanai ||", translation = "Duality is gone, and one enters into the home of the One Lord.", hindi = "दूजा जाइ; इकतु घरि आनै ॥", punjabi = "ਮੇਰ-ਤੇਰ ਵਾਲਾ ਸੁਭਾਉ ਦੂਰ ਹੋ ਜਾਂਦਾ ਹੈ, ਮਨੁੱਖ ਏਕਤਾ ਦੇ ਘਰ ਵਿਚ ਆ ਟਿਕਦਾ ਹੈ।", wordMeaning = "ਇਕਤੁ ਘਰਿ = ਇੱਕ ਘਰ ਵਿਚ (ਭਾਵ, ਏਕਤਾ ਦੇ ਘਰ ਵਿਚ)।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-267", gurmukhi = "ਬੋਲੈ ਪਵਨਾ; ਗਗਨੁ ਗਰਜੈ ॥", transliteration = "bolai pavnaa; gagan garjai ||", translation = "The breath blows across the sky of the Tenth Gate and vibrates.", hindi = "बोलै पवना; गगनु गरजै ॥", punjabi = "ਰੱਬੀ ਜੀਵਨ ਦੀ ਲਹਿਰ ਚੱਲ ਪੈਂਦੀ ਹੈ, ਰੱਬੀ ਮਿਲਾਪ ਦੀ ਅਵਸਥਾ ਬਲਵਾਨ ਹੋ ਜਾਂਦੀ ਹੈ,", wordMeaning = "ਪਵਨ = ਪ੍ਰਾਣ। ਬੋਲੈ ਪਵਨਾ = ਪ੍ਰਾਣ ਬੋਲਦਾ ਹੈ, ਰੱਬੀ ਜੀਵਨ ਦੀ ਲਹਿਰ ਚੱਲ ਪੈਂਦੀ ਹੈ। ਗਗਨੁ = ਆਕਾਸ਼, ਦਸਮ-ਦੁਆਰ, ਰੱਬੀ ਮਿਲਾਪ ਦੀ ਅਵਸਥਾ। ਗਰਜੈ = ਗੱਜਦਾ ਹੈ, ਬਲਵਾਨ ਹੁੰਦਾ ਹੈ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-268", gurmukhi = "ਨਾਨਕ; ਨਿਹਚਲੁ ਮਿਲਣੁ ਸਹਜੈ ॥੫੦॥", transliteration = "naanak; nihachal milan sahjai ||50||", translation = "O Nanak, the mortal then intuitively meets the eternal, unchanging Lord. ||50||", hindi = "नानक; निहचलु मिलणु सहजै ॥५०॥", punjabi = "(ਤੇ, ਇਸ ਤਰ੍ਹਾਂ) ਹੇ ਨਾਨਕ! ਸਹਜ ਅਵਸਥਾ ਵਿਚ ਟਿਕਿਆਂ (ਜੀਵ ਤੇ ਪ੍ਰਭੂ ਦਾ) ਮਿਲਾਪ (ਸਦਾ ਲਈ) ਪੱਕਾ ਹੋ ਜਾਂਦਾ ਹੈ ॥੫੦॥", wordMeaning = "ਮਿਲਣੁ = ਮਿਲਾਪ। ਸਹਜੈ = ਸਹਜ ਅਵਸਥਾ ਵਿਚ, ਆਤਮਕ ਅਡੋਲਤਾ ਵਿਚ ॥੫੦॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-269", gurmukhi = "ਅੰਤਰਿ ਸੁੰਨੰ. ਬਾਹਰਿ ਸੁੰਨੰ; ਤ੍ਰਿਭਵਣ; ਸੁੰਨ ਮਸੁੰਨੰ ॥", transliteration = "antar sunnan. baahar sunnan; tribhavan; sunn msunnan ||", translation = "The absolute Lord is deep within; the absolute Lord is outside us as well. The absolute Lord totally fills the three worlds.", hindi = "अंतरि सुंनं. बाहरि सुंनं; त्रिभवण; सुंन मसुंनं ॥", punjabi = "(ਜਦੋਂ ਹਿਰਦੇ ਵਿਚ ਨਿਰੋਲ ਪ੍ਰਭੂ-ਨਾਮ ਦੀ ਸੱਚਾਈ ਪਰਗਟ ਹੋ ਪੈਂਦੀ ਹੈ ਤਾਂ ਇਹ ਯਕੀਨ ਬਣ ਜਾਂਦਾ ਹੈ ਕਿ) ਅੰਦਰ ਤੇ ਬਾਹਰ (ਭਾਵ, ਗੁਪਤ ਤੇ ਪਰਗਟ, ਦਿੱਸਦੇ ਤੇ ਅਣਦਿੱਸਦੇ ਪਦਾਰਥਾਂ ਵਿਚ ਹਰ ਥਾਂ) ਸਾਰੀ ਤ੍ਰਿਲੋਕੀ ਵਿਚ ਉਹੀ ਪ੍ਰਭੂ ਵਿਆਪਕ ਹੈ ਜਿਸ ਵਿਚ ਮਾਇਆ ਵਾਲੇ ਫੁਰਨੇ ਨਹੀਂ ਉਠਦੇ (ਕਿਉਂਕਿ ਮਾਇਆ ਤਾਂ ਉਸ ਦੀ ਆਪਣੀ ਬਣਾਈ ਖੇਡ ਹੈ)।", wordMeaning = "ਸੁੰਨ = ਨਿਰਗੁਣ ਪ੍ਰਭੂ, ਉਹ ਪ੍ਰਭੂ ਜਿਸ ਵਿਚ ਮਾਇਆ ਵਾਲੇ ਫੁਰਨੇ ਨਹੀਂ ਉਠਦੇ। ਸੁੰਨ ਮਸੁੰਨ = ਸੁੰਨ ਹੀ ਸੁੰਞ, ਨਿਰੋਲ ਨਿਰਗੁਣ ਪ੍ਰਭੂ ਹੀ, ਨਿਰੋਲ ਉਹੀ ਪ੍ਰਭੂ ਜੋ ਮਾਇਆ ਦੇ ਫੁਰਨਿਆਂ ਦੇ ਅਸਰ ਹੇਠ ਨਹੀਂ ਆ ਸਕਦਾ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-270", gurmukhi = "ਚਉਥੇ ਸੁੰਨੈ. ਜੋ ਨਰੁ ਜਾਣੈ; ਤਾ ਕਉ. ਪਾਪੁ ਨ ਪੁੰਨੰ ॥", transliteration = "chauthe sunnai. jo nar jaanai; taa kau. paap na punnan ||", translation = "One who knows the Lord in the fourth state, is not subject to virtue or vice.", hindi = "चउथे सुंनै. जो नरु जाणै; ता कउ. पापु न पुंनं ॥", punjabi = "ਜੋ ਮਨੁੱਖ ਤ੍ਰਿਗੁਣੀ ਮਾਇਆ ਦੇ ਅਸਰ ਤੋਂ ਉੱਚੇ ਰਹਿਣ ਵਾਲੇ ਉਸ ਪ੍ਰਭੂ ਨੂੰ (ਸਹੀ ਤੌਰ ਤੇ) ਸਮਝ ਲੈਂਦਾ ਹੈ, ਉਸ ਨੂੰ ਭੀ (ਚਉਥੀ ਅਵਸਥਾ ਵਿਚ ਟਿਕਿਆ ਹੋਣ ਕਰਕੇ) ਪਾਪ ਤੇ ਪੁੰਨ ਪੋਹ ਨਹੀਂ ਸਕਦਾ (ਭਾਵ, ਕੋਈ ਪਾਪ ਕਿਸੇ ਕੁਕਰਮ ਵਲ ਨਹੀਂ ਪ੍ਰੇਰਦਾ ਅਤੇ ਕੋਈ ਪੁੰਨ-ਕਰਮ ਉਸ ਦੇ ਅੰਦਰ ਕਿਸੇ ਸਵਰਗ ਆਦਿਕ ਦੀ ਲਾਲਸਾ ਪੈਦਾ ਨਹੀਂ ਕਰਦਾ)।", wordMeaning = "ਚਉਥੇ ਸੁੰਨ = ਚਉਥੀ ਅਵਸਥਾ ਵਾਲੇ ਨਿਰਗੁਣ ਪ੍ਰਭੂ ਨੂੰ, ਉਸ ਨਿਰਗੁਣ ਪ੍ਰਭੂ ਨੂੰ ਜੋ ਤ੍ਰਿਗੁਣੀ ਮਾਇਆ ਦੇ ਅਸਰ ਤੋਂ ਉੱਚਾ ਹੈ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-271", gurmukhi = "ਘਟਿ; ਘਟਿ; ਸੁੰਨ ਕਾ ਜਾਣੈ ਭੇਉ ॥", transliteration = "ghat; ghat; sunn kaa jaanai bheu ||", translation = "One who knows the mystery of God the Absolute, who pervades each and every heart,", hindi = "घटि; घटि; सुंन का जाणै भेउ ॥", punjabi = "ਜੋ ਮਨੁੱਖ ਹਰੇਕ ਘਟ ਵਿਚ ਵਿਆਪਕ ਨਿਰਗੁਣ ਪ੍ਰਭੂ ਦਾ ਭੇਤ ਜਾਣ ਲੈਂਦਾ ਹੈ (ਭਾਵ, ਜੋ ਮਨੁੱਖ ਇਹ ਦ੍ਰਿੜ੍ਹ ਕਰ ਲੈਂਦਾ ਹੈ ਕਿ ਪ੍ਰਭੂ ਹਰੇਕ ਘਟ ਵਿਚ ਮੌਜੂਦ ਭੀ ਹੈ, ਤੇ ਫਿਰ ਭੀ ਨਿਰਲੇਪ ਹੈ, ਉਹ ਮਨੁੱਖ ਭੀ ਦੁਨੀਆ ਵਿਚ ਰਹਿੰਦਾ ਹੋਇਆ ਨਿਰਲੇਪ ਹੋ ਕੇ)", wordMeaning = "ਘਟਿ ਘਟਿ ਸੁੰਨ ਕਾ = ਹਰੇਕ ਘਟ ਵਿਚ ਵਿਆਪਕ ਨਿਰਗੁਣ ਪ੍ਰਭੂ ਦਾ; ਉਸ ਪ੍ਰਭੂ ਦਾ ਜੋ ਹਰੇਕ ਘਟ ਵਿਚ ਮੌਜੂਦ ਭੀ ਹੈ ਤੇ ਨਿਰਲੇਪ ਹੈ। ਭੇਉ = ਭੇਤ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-272", gurmukhi = "ਆਦਿ ਪੁਰਖੁ; ਨਿਰੰਜਨ ਦੇਉ ॥", transliteration = "aad purakh; niranjan deu ||", translation = "Knows the Primal Being, the Immaculate Divine Lord.", hindi = "आदि पुरखु; निरंजन देउ ॥", punjabi = "ਆਦਿ ਪੁਰਖ ਨਿਰੰਜਨ ਪ੍ਰਭੂ ਦਾ ਰੂਪ ਹੋ ਜਾਂਦਾ ਹੈ।", wordMeaning = "ਆਦਿ = ਸਭ ਦਾ ਮੁੱਢ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-273", gurmukhi = "ਜੋ ਜਨੁ; ਨਾਮ ਨਿਰੰਜਨ ਰਾਤਾ ॥", transliteration = "jo jan; naam niranjan raataa ||", translation = "That humble being who is imbued with the Immaculate Naam,", hindi = "जो जनु; नाम निरंजन राता ॥", punjabi = "ਜੋ ਮਨੁੱਖ ਮਾਇਆ ਤੋਂ ਰਹਿਤ ਪਰਮਾਤਮਾ ਦੇ ਨਾਮ ਦਾ ਮਤਵਾਲਾ ਹੈ,", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-274", gurmukhi = "ਨਾਨਕ; ਸੋਈ ਪੁਰਖੁ ਬਿਧਾਤਾ ॥੫੧॥", transliteration = "naanak; soee purakh bidhaataa ||51||", translation = "O Nanak, is himself the Primal Lord, the Architect of Destiny. ||51||", hindi = "नानक; सोई पुरखु बिधाता ॥५१॥", punjabi = "ਹੇ ਨਾਨਕ! ਉਹੀ ਸਿਰਜਨਹਾਰ ਪ੍ਰਭੂ ਦਾ ਰੂਪ ਹੋ ਜਾਂਦਾ ਹੈ ॥੫੧॥", wordMeaning = "ਬਿਧਾਤਾ = ਕਰਤਾ, ਸਿਰਜਨਹਾਰ ॥੫੧॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-275", gurmukhi = "ਸੁੰਨੋ ਸੁੰਨੁ ਕਹੈ ਸਭੁ ਕੋਈ ॥", transliteration = "sunno sunn khai sabh koee ||", translation = "\"Everyone speaks of the Absolute Lord, the unmanifest void.", hindi = "सुंनो सुंनु कहै सभु कोई ॥", punjabi = "ਹਰੇਕ ਮਨੁੱਖ \"ਅਫੁਰ ਅਵਸਥਾ\" ਦਾ ਜ਼ਿਕਰ ਕਰਦਾ ਹੈ,", wordMeaning = "ਸੁੰਨੋ ਸੁੰਨੁ = ਸੁੰਞ ਹੀ ਸੁੰਞ, ਨਿਰੋਲ ਉਹ ਅਵਸਥਾ ਜਿਥੇ ਮਾਇਆ ਦੇ ਫੁਰਨੇ ਨਾਹ ਉੱਠਣ। ਸਭੁ ਕੋਈ = ਹਰੇਕ ਮਨੁੱਖ", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-276", gurmukhi = "ਅਨਹਤ ਸੁੰਨੁ; ਕਹਾ ਤੇ ਹੋਈ ॥", transliteration = "anahat sunn; khaa te hoee ||", translation = "How can one find this absolute void?", hindi = "अनहत सुंनु; कहा ते होई ॥", punjabi = "(ਪਰ ਅਮਲੀ ਜੀਵਨ ਵਿਚ ਇਹ ਗੱਲ ਕੋਈ ਵਿਰਲਾ ਹੀ ਜਾਣਦਾ ਹੈ ਕਿ) ਸਦਾ ਟਿਕੀ ਰਹਿਣ ਵਾਲੀ ਅਫੁਰ ਅਵਸਥਾ ਕਿਵੇਂ ਬਣ ਸਕਦੀ ਹੈ (ਕਿਉਂਕਿ ਇਸ ਅਵਸਥਾ ਵਾਲਾ ਜੀਵਨ ਜੀਵਿਆਂ ਹੀ ਇਸ ਅਵਸਥਾ ਦੀ ਸਮਝ ਪੈ ਸਕਦੀ ਹੈ)।", wordMeaning = "ਅਨਹਤ = ਇੱਕ-ਰਸ, ਸਦਾ ਟਿਕੀ ਰਹਿਣ ਵਾਲੀ। ਕਹਾ ਤੇ = ਕਿਸ ਤੋਂ? ਕਿਥੋਂ? ਕਿਵੇਂ?", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-277", gurmukhi = "ਅਨਹਤ ਸੁੰਨਿ ਰਤੇ; ਸੇ ਕੈਸੇ ॥", transliteration = "anahat sunn rte; se kaise ||", translation = "Who are they, who are attuned to this absolute void?\"", hindi = "अनहत सुंनि रते; से कैसे ॥", punjabi = "(ਕਹਣ-ਮਾਤ੍ਰ ਜੇ ਕੋਈ ਪੁੱਛੇ ਕਿ) ਅਫੁਰ ਅਵਸਥਾ ਵਿਚ ਜੁੜੇ ਹੋਏ ਬੰਦੇ ਕਿਹੋ ਜਿਹੇ ਹੁੰਦੇ ਹਨ,", wordMeaning = "ਸੁੰਨਿ = ਅਫੁਰ ਅਵਸਥਾ ਵਿਚ।", startsAtMs = 0L, endsAtMs = 0L),
