    BaniLine(id = "sidha-gosht-294", gurmukhi = "ਕਿਉ ਤਤੁ. ਨ ਬੂਝੈ; ਚੋਟਾ ਖਾਇ ॥", transliteration = "kiu tat. na boojhai; chotaa khaai ||", translation = "The mortal does not understand the essence of reality; why must he suffer in pain?\"", hindi = "किउ ततु. न बूझै; चोटा खाइ ॥", punjabi = "ਮਨੁੱਖ ਕਿਉਂ ਅਸਲੀਅਤ ਨਹੀਂ ਸਮਝਦਾ ਤੇ ਦੁਖੀ ਹੁੰਦਾ ਹੈ,", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-295", gurmukhi = "ਜਮ ਦਰਿ ਬਾਧੇ; ਕੋਇ. ਨ ਰਾਖੈ ॥", transliteration = "jam dar baadhe; koi. na raakhai ||", translation = "No one can save one who is tied up at Death's door.", hindi = "जम दरि बाधे; कोइ. न राखै ॥", punjabi = "ਜਮ ਦੇ ਦਰ ਤੇ ਬੱਧੇ ਹੋਏ ਦੀ ਕੋਈ ਸਹੈਤਾ ਨਹੀਂ ਕਰ ਸਕਦਾ,", wordMeaning = "ਦਰਿ = ਦਰ ਤੇ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-296", gurmukhi = "ਬਿਨੁ ਸਬਦੈ; ਨਾਹੀ ਪਤਿ ਸਾਖੈ ॥", transliteration = "bin sabdai; naahee pat saakhai ||", translation = "Without the Shabad, no one has any credit or honor.", hindi = "बिनु सबदै; नाही पति साखै ॥", punjabi = "ਸਤਿਗੁਰੂ ਦੇ ਸ਼ਬਦ ਤੋਂ ਬਿਨਾ ਇਸ ਦੀ ਕਿਤੇ ਇੱਜ਼ਤ ਨਹੀਂ, ਇਤਬਾਰ ਨਹੀਂ (ਭਾਵ, ਗੁਰੂ ਦੇ ਸ਼ਬਦ ਅਨੁਸਾਰ ਨਾਹ ਤੁਰਨ ਕਰਕੇ ਮਨੁੱਖ ਲੋਕਾਂ ਵਿਚ ਇੱਜ਼ਤ ਇਤਬਾਰ ਗਵਾ ਲੈਂਦਾ ਹੈ, ਦੁਨੀਆ ਦੀਆਂ ਮੌਜਾਂ ਵਿਚ ਫਸਿਆ ਹੋਣ ਕਰਕੇ ਮੌਤ ਤੋਂ ਭੀ ਹਰ ਵੇਲੇ ਡਰਦਾ ਹੈ ਇਹੋ ਜਿਹੀਆ ਸੱਟਾਂ ਸਦਾ ਖਾਂਦਾ ਰਹਿੰਦਾ ਹੈ, ਦੁਖੀ ਰਹਿੰਦਾ ਹੈ, ਫਿਰ ਭੀ ਅਸਲੀਅਤ ਨੂੰ ਸਮਝਦਾ ਨਹੀਂ। ਇਹ ਕਿਉਂ?)।", wordMeaning = "ਪਤਿ ਸਾਖ = ਇੱਜ਼ਤ ਤੇ ਇਤਬਾਰ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-297", gurmukhi = "ਕਿਉ ਕਰਿ ਬੂਝੈ; ਪਾਵੈ ਪਾਰੁ ॥", transliteration = "kiu kar boojhai; paavai paar ||", translation = "\"How can one obtain understanding and cross over?\"", hindi = "किउ करि बूझै; पावै पारु ॥", punjabi = "ਇਹ ਕਿਵੇਂ ਸਮਝੇ ਤੇ ('ਦੁੱਤਰ ਸਾਗਰ' ਦੇ) ਪਾਰਲੇ ਕੰਢੇ ਲੱਗੇ?", wordMeaning = "ਪਾਰੁ = ਪਾਰਲਾ ਬੰਨਾ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-298", gurmukhi = "ਨਾਨਕ; ਮਨਮੁਖਿ. ਨ ਬੁਝੈ, ਗਵਾਰੁ ॥੫੫॥", transliteration = "naanak; manmukh. na bujhai, gvaar ||55||", translation = "O Nanak, the foolish self-willed manmukh does not understand. ||55||", hindi = "नानक; मनमुखि. न बुझै, गवारु ॥५५॥", punjabi = "ਹੇ ਨਾਨਕ! ਮਨਮੁਖ ਮੂਰਖ ਸਮਝਦਾ ਨਹੀਂ ॥੫੫॥", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-299", gurmukhi = "ਕੁਬੁਧਿ ਮਿਟੈ; ਗੁਰਸਬਦੁ ਬੀਚਾਰਿ ॥", transliteration = "kubudh mitai; gurasabad beechaar ||", translation = "Evil thoughts are erased, contemplating the Word of the Guru's Shabad.", hindi = "कुबुधि मिटै; गुरसबदु बीचारि ॥", punjabi = "(ਉੱਤਰ:) ਸਤਿਗੁਰੂ ਦਾ ਸ਼ਬਦ ਵੀਚਾਰਿਆਂ ਭੈੜੀ ਮਤ ਦੂਰ ਹੁੰਦੀ ਹੈ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-300", gurmukhi = "ਸਤਿਗੁਰੁ ਭੇਟੈ; ਮੋਖ ਦੁਆਰ ॥", transliteration = "satigur bhetai; mokh duaar ||", translation = "Meeting with the True Guru, the door of liberation is found.", hindi = "सतिगुरु भेटै; मोख दुआर ॥", punjabi = "ਜਦੋਂ ਗੁਰੂ ਮਿਲ ਪੈਂਦਾ ਹੈ, ਤਦੋਂ ਇਸ ਭੈੜੀ ਮਤ ਤੋਂ ਖ਼ਲਾਸੀ ਦਾ ਰਾਹ ਲੱਭ ਪੈਂਦਾ ਹੈ।", wordMeaning = "ਭੇਟੈ = ਮਿਲੈ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-301", gurmukhi = "ਤਤੁ. ਨ ਚੀਨੈ; ਮਨਮੁਖੁ ਜਲਿ ਜਾਇ ॥", transliteration = "tat. na cheenai; manmukh jal jaai ||", translation = "The self-willed manmukh does not understand the essence of reality, and is burnt to ashes.", hindi = "ततु. न चीनै; मनमुखु जलि जाइ ॥", punjabi = "(ਪਰ) ਜੋ ਮਨੁੱਖ ਮਨ ਦੇ ਪਿੱਛੇ ਤੁਰਦਾ ਹੈ ਉਹ ਅਸਲੀਅਤ ਨਹੀਂ ਪਛਾਣਦਾ, (ਵਿਕਾਰਾਂ ਵਿਚ) ਸੜਦਾ ਰਹਿੰਦਾ ਹੈ,", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-302", gurmukhi = "ਦੁਰਮਤਿ ਵਿਛੁੜਿ; ਚੋਟਾ ਖਾਇ ॥", transliteration = "duramat vichhur; chotaa khaai ||", translation = "His evil-mindedness separates him from the Lord, and he suffers.", hindi = "दुरमति विछुड़ि; चोटा खाइ ॥", punjabi = "ਦੁਰਮੱਤ ਦੇ ਕਾਰਨ (ਪ੍ਰਭੂ ਤੋਂ) ਵਿਛੁੜ ਕੇ ਦੁਖੀ ਹੁੰਦਾ ਹੈ।", wordMeaning = "ਦੁਰਮਤਿ = ਭੈੜੀ ਅਕਲ ਦੇ ਕਾਰਨ। ਚੋਟਾ ਖਾਇ = ਮਾਰ ਖਾਂਦਾ ਹੈ, ਦੁਖੀ ਹੁੰਦਾ ਹੈ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-303", gurmukhi = "ਮਾਨੈ ਹੁਕਮੁ; ਸਭੇ ਗੁਣ ਗਿਆਨ ॥", transliteration = "maanai hukam; sbhe gun giaan ||", translation = "Accepting the Hukam of the Lord's Command, he is blessed with all virtues and spiritual wisdom.", hindi = "मानै हुकमु; सभे गुण गिआन ॥", punjabi = "ਜੋ ਮਨੁੱਖ ਗੁਰੂ ਦਾ ਹੁਕਮ ਮੰਨਦਾ ਹੈ, ਉਸ ਵਿਚ ਸਾਰੇ ਗੁਣ ਆ ਜਾਂਦੇ ਹਨ, ਉਸ ਨੂੰ ਸਾਰੀ ਸੂਝ ਪ੍ਰਾਪਤ ਹੋ ਜਾਂਦੀ ਹੈ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-304", gurmukhi = "ਨਾਨਕ; ਦਰਗਹ ਪਾਵੈ ਮਾਨੁ ॥੫੬॥", transliteration = "naanak; daragah paavai maan ||56||", translation = "O Nanak, he is honored in the Court of the Lord. ||56||", hindi = "नानक; दरगह पावै मानु ॥५६॥", punjabi = "ਹੇ ਨਾਨਕ!ਉਹ ਪ੍ਰਭੂ ਦੀ ਹਜ਼ੂਰੀ ਵਿਚ ਆਦਰ ਪਾਂਦਾ ਹੈ ॥੫੬॥", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-305", gurmukhi = "ਸਾਚੁ ਵਖਰੁ ਧਨੁ; ਪਲੈ ਹੋਇ ॥", transliteration = "saach vakhar dhan; plai hoi ||", translation = "One who possesses the merchandise, the wealth of the True Name,", hindi = "साचु वखरु धनु; पलै होइ ॥", punjabi = "ਜਿਸ ਮਨੁੱਖ ਨੇ ਸੱਚਾ ਸਉਦਾ ਨਾਮ-ਧਨ ਖੱਟਿਆ ਹੈ,", wordMeaning = "ਪਲੈ ਹੋਇ = ਹਾਸਲ ਕੀਤਾ ਹੋਵੇ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-306", gurmukhi = "ਆਪਿ ਤਰੈ; ਤਾਰੇ ਭੀ ਸੋਇ ॥", transliteration = "aap trai; taare bhee soi ||", translation = "crosses over, and carries others across with him as well.", hindi = "आपि तरै; तारे भी सोइ ॥", punjabi = "ਉਹ ਆਪ ('ਦੁੱਤਰ ਸਾਗਰ' ਤੋਂ) ਤਰਦਾ ਹੈ ਤੇ (ਹੋਰਨਾਂ ਨੂੰ) ਤਾਰਦਾ ਹੈ।", wordMeaning = "ਸੋਇ = ਉਹ ਮਨੁੱਖ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-307", gurmukhi = "ਸਹਜਿ ਰਤਾ; ਬੂਝੈ ਪਤਿ ਹੋਇ ॥", transliteration = "sahaj rtaa; boojhai pat hoi ||", translation = "One who intuitively understands, and is attuned to the Lord, is honored.", hindi = "सहजि रता; बूझै पति होइ ॥", punjabi = "ਅਡੋਲ ਅਵਸਥਾ ਵਿਚ ਮਸਤ ਰਹਿ ਕੇ ਅਸਲੀਅਤ ਨੂੰ ਸਮਝਦਾ ਹੈ ਤੇ ਆਦਰ ਪਾਂਦਾ ਹੈ,", wordMeaning = "ਸਹਜਿ = ਸਹਿਜ ਵਿਚ, ਅਡੋਲਤਾ ਵਿਚ। ਪਤਿ = ਇੱਜ਼ਤ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-308", gurmukhi = "ਤਾ ਕੀ ਕੀਮਤਿ; ਕਰੈ. ਨ ਕੋਇ ॥", transliteration = "taa kee keemat; krai. na koi ||", translation = "No one can estimate his worth.", hindi = "ता की कीमति; करै. न कोइ ॥", punjabi = "ਅਜੇਹੇ ਮਨੁੱਖ ਦਾ ਕੋਈ ਮੁੱਲ ਨਹੀਂ ਪਾ ਸਕਦਾ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-309", gurmukhi = "ਜਹ ਦੇਖਾ; ਤਹ ਰਹਿਆ ਸਮਾਇ ॥", transliteration = "jah dekhaa; tah rhiaa smaai ||", translation = "Wherever I look, I see the Lord permeating and pervading.", hindi = "जह देखा; तह रहिआ समाइ ॥", punjabi = "ਉਹ ਜਿੱਧਰ ਤੱਕਦਾ ਹੈ ਉਧਰ ਪ੍ਰਭੂ ਹੀ ਪ੍ਰਭੂ ਉਸ ਨੂੰ ਵਿਆਪਕ ਦਿੱਸਦਾ ਹੈ", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-310", gurmukhi = "ਨਾਨਕ. ਪਾਰਿ ਪਰੈ; ਸਚ ਭਾਇ ॥੫੭॥", transliteration = "naanak. paar prai; sach bhaai ||57||", translation = "O Nanak, through the Love of the True Lord, one crosses over. ||57||", hindi = "नानक. पारि परै; सच भाइ ॥५७॥", punjabi = "ਹੇ ਨਾਨਕ! ਸੱਚੇ ਦੀ ਰਜ਼ਾ ਵਿਚ ਰਹਿ ਕੇ ਉਹ ਮਨੁੱਖ ('ਦੁਤਰ ਸਾਗਰ' ਤੋਂ) ਪਾਰ ਲੰਘ ਜਾਂਦਾ ਹੈ ॥੫੭॥", wordMeaning = "ਸਚ ਭਾਇ = ਸੱਚ ਦੇ ਭਾਵ ਵਿਚ, ਸੱਚੇ ਪ੍ਰਭੂ ਦੇ ਅਨੁਸਾਰ ਹੋ ਕੇ, ਸੱਚੇ ਦੀ ਰਜ਼ਾ ਵਿਚ ਰਹਿ ਕੇ। {ਨੋਟ: ਪਉੜੀ ਨੰ: ੫੫ ਵਿਚ ਦੇ ਲਫ਼ਜ਼ 'ਪਾਰੁ' ਅਤੇ ਇਥੇ ਲਫ਼ਜ਼ 'ਪਾਰਿ' ਦਾ ਫ਼ਰਕ ਚੇਤੇ ਰੱਖਣ-ਜੋਗ ਹੈ। 'ਪਾਰੁ' ਹੈ 'ਨਾਂਵ' (ਪਾਰਲਾ ਕੰਢਾ) 'ਪਾਰਿ', ਹੈ 'ਕ੍ਰਿਆ ਵਿਸ਼ੇਸ਼ਣ' (ਪਾਰਲੇ ਕੰਢੇ)} ॥੫੭॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-311", gurmukhi = "ਸੁ ਸਬਦ ਕਾ ਕਹਾ ਵਾਸੁ ਕਥੀਅਲੇ; ਜਿਤੁ ਤਰੀਐ ਭਵਜਲੁ ਸੰਸਾਰੋ ॥", transliteration = "su sabad kaa khaa vaas ktheeale; jit treeai bhavajal sansaaro ||", translation = "\"Where is the Shabad said to dwell? What will carry us across the terrifying world-ocean?", hindi = "सु सबद का कहा वासु कथीअले; जितु तरीऐ भवजलु संसारो ॥", punjabi = "(ਪ੍ਰਸ਼ਨ:) ਜਿਸ ਸ਼ਬਦ ਦੀ ਰਾਹੀਂ ਸੰਸਾਰ-ਸਮੁੰਦਰ ਤਰੀਦਾ ਹੈ ਉਸ ਸ਼ਬਦ ਦਾ ਟਿਕਾਣਾ ਕਿੱਥੇ ਕਿਹਾ ਜਾ ਸਕਦਾ ਹੈ?", wordMeaning = "ਸੁ = ਉਸ। ਜਿਤੁ = ਜਿਸ (ਸ਼ਬਦ) ਦੀ ਰਾਹੀਂ। ਕਥੀਅਲੇ = ਕਿਹਾ ਜਾਏ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-312", gurmukhi = "ਤ੍ਰੈ ਸਤ ਅੰਗੁਲ, ਵਾਈ ਕਹੀਐ; ਤਿਸੁ ਕਹੁ ਕਵਨੁ ਅਧਾਰੋ ॥", transliteration = "trai sat angul, vaaee kheeai; tis kah kavan adhaaro ||", translation = "The breath, when exhaled, extends out ten finger lengths; what is the support of the breath?", hindi = "त्रै सत अंगुल, वाई कहीऐ; तिसु कहु कवनु अधारो ॥", punjabi = "'ਪ੍ਰਾਣ' (ਭਾਵ ਸੁਆਸ) ਨੂੰ ਦਸ-ਉਂਗਲ-ਪ੍ਰਮਾਣ ਕਹੀਦਾ ਹੈ ਦੱਸੋ, ਇਸ ਦਾ ਕੀਹ ਆਸਰਾ ਹੈ?", wordMeaning = "ਤ੍ਰੈ ਸਤ = ਤਿੰਨ ਤੇ ਸੱਤ, ਦਸ। ਵਾਈ = ਪ੍ਰਾਣ {ਨੋਟ: ਜੋਗੀਆਂ ਦੇ ਖ਼ਿਆਲ ਅਨੁਸਾਰ ਸਾਹ ਬਾਹਰ ਵਲ ਕੱਢਿਆਂ ਹਵਾ ਦਸ ਉਂਗਲ ਦੇ ਫ਼ਾਸਲੇ ਤਕ ਬਾਹਰ ਜਾਂਦੀ ਹੈ, ਫਿਰ ਸਾਹ ਅੰਦਰ ਵਲ ਖਿੱਚੀਦਾ ਹੈ}। ਤ੍ਰੈ ਸਤ ਅੰਗੁਲ ਵਾਈ = ਦਸ ਉਂਗਲ-ਪ੍ਰਮਾਣ ਪ੍ਰਾਣ। ਕਹੁ = ਦੱਸੋ। ਕਵਨੁ = ਕੀਹ?", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-313", gurmukhi = "ਬੋਲੈ ਖੇਲੈ ਅਸਥਿਰੁ ਹੋਵੈ; ਕਿਉ ਕਰਿ. ਅਲਖੁ ਲਖਾਏ ॥", transliteration = "bolai khelai asthir hovai; kiu kar. alakh lkhaae ||", translation = "Speaking and playing, how can one be stable and steady? How can the unseen be seen?\"", hindi = "बोलै खेलै असथिरु होवै; किउ करि. अलखु लखाए ॥", punjabi = "(ਜੋ ਜੀਵਾਤਮਾ ਇਸ ਸਰੀਰ ਵਿਚ) ਬੋਲਦਾ ਤੇ ਕਲੋਲ ਕਰਦਾ ਹੈ, ਉਹ ਸਦਾ ਲਈ ਕਿਵੇਂ ਅਡੋਲ ਹੋ ਸਕਦਾ ਹੈ ਤੇ ਕਿਵੇਂ ਉਸ ਪ੍ਰਭੂ ਨੂੰ ਵੇਖੇ ਜਿਸ ਦਾ ਕੋਈ ਖ਼ਾਸ ਚਿਹਨ ਚੱਕ੍ਰ ਨਹੀਂ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-314", gurmukhi = "ਸੁਣਿ ਸੁਆਮੀ ਸਚੁ ਨਾਨਕੁ ਪ੍ਰਣਵੈ; ਅਪਣੇ ਮਨ ਸਮਝਾਏ ॥", transliteration = "sun suaamee sach naanak pranvai; apne man samjhaae ||", translation = "Listen, O master; Nanak prays truly. Instruct your own mind.", hindi = "सुणि सुआमी सचु नानकु प्रणवै; अपणे मन समझाए ॥", punjabi = "ਨਾਨਕ ਕਹਿੰਦਾ ਹੈ (ਜੋਗੀਆਂ ਨੇ ਪੁੱਛਿਆ) ਹੇ ਸੁਆਮੀ! ਸੱਚੇ ਪ੍ਰਭੂ ਦੀ ਗੱਲ ਸੁਣ ਕੇ ਮਨੁੱਖ ਆਪਣੇ ਮਨ ਨੂੰ ਕਿਵੇਂ ਸੁਮੱਤੇ ਲਾ ਸਕਦਾ ਹੈ?", wordMeaning = "ਸੁਣਿ = ਸੁਣ ਕੇ। ਮਨ ਸਮਝਾਏ = ਕਿਉਂਕਰਿ ਆਪਣੇ ਮਨ ਸਮਝਾਏ। {ਨੋਟ: ਪਹਿਲੀਆਂ ਚਾਰ ਤੁਕਾਂ ਵਿਚ ਜੋਗੀ ਦਾ ਪ੍ਰਸ਼ਨ ਹੈ, ਪੰਜਵੀਂ ਤੁਕ ਤੋਂ ਉੱਤਰ ਸ਼ੁਰੂ ਹੁੰਦਾ ਹੈ}।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-315", gurmukhi = "ਗੁਰਮੁਖਿ ਸਬਦੇ ਸਚਿ ਲਿਵ ਲਾਗੈ; ਕਰਿ ਨਦਰੀ ਮੇਲਿ ਮਿਲਾਏ ॥", transliteration = "gurmukh sabde sach liv laagai; kar nadree mel milaae ||", translation = "The Gurmukh is lovingly attuned to the True Shabad. Bestowing His Glance of Grace, He unites us in His Union.", hindi = "गुरमुखि सबदे सचि लिव लागै; करि नदरी मेलि मिलाए ॥", punjabi = "(ਉੱਤਰ:) ਜੋ ਮਨੁੱਖ ਗੁਰੂ ਦੇ ਹੁਕਮ ਵਿਚ ਤੁਰਦਾ ਹੈ, ਗੁਰੂ ਸ਼ਬਦ ਦੀ ਰਾਹੀਂ ਉਸ ਦੀ ਲਿਵ ਸੱਚੇ ਪ੍ਰਭੂ ਵਿਚ ਲੱਗ ਜਾਂਦੀ ਹੈ, (ਤੇ, ਪ੍ਰਭੂ) ਮੇਹਰ ਦੀ ਨਜ਼ਰ ਕਰ ਕੇ ਉਸ ਨੂੰ ਆਪਣੇ ਵਿਚ ਜੋੜ ਲੈਂਦਾ ਹੈ,", wordMeaning = "ਗੁਰਮੁਖਿ = ਗੁਰੂ ਦੇ ਹੁਕਮ ਵਿਚ ਤੁਰਨ ਵਾਲਾ ਮਨੁੱਖ। ਸਬਦੇ = ਸ਼ਬਦ ਦੀ ਰਾਹੀਂ। ਸਚਿ = ਸੱਚੇ ਪ੍ਰਭੂ ਵਿਚ। ਨਦਰੀ = ਮੇਹਰ ਦੀ ਨਜ਼ਰ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-316", gurmukhi = "ਆਪੇ ਦਾਨਾ ਆਪੇ ਬੀਨਾ; ਪੂਰੈ ਭਾਗਿ ਸਮਾਏ ॥੫੮॥", transliteration = "aape daanaa aape beenaa; poorai bhaag smaae ||58||", translation = "He Himself is all-knowing and all-seeing. By perfect destiny, we merge in Him. ||58||", hindi = "आपे दाना आपे बीना; पूरै भागि समाए ॥५८॥", punjabi = "(ਕਿਉਂਕਿ) ਪ੍ਰਭੂ (ਉਸ ਦੇ ਦਿਲ ਦੀ) ਆਪ ਹੀ ਜਾਣਦਾ ਹੈ, ਆਪ ਹੀ ਪਛਾਣਦਾ ਹੈ। (ਇਸ ਤਰ੍ਹਾਂ) ਉੱਚੀ ਕਿਸਮਤ ਕਰਕੇ (ਗੁਰਮੁਖਿ ਮਨੁੱਖ ਪ੍ਰਭੂ ਵਿਚ) ਟਿਕਿਆ ਰਹਿੰਦਾ ਹੈ ॥੫੮॥", wordMeaning = "ਦਾਨਾ = ਦਿਲ ਦੀ ਜਾਣਨ ਵਾਲਾ ਪ੍ਰਭੂ। ਬੀਨਾ = ਪਛਾਣਨ ਵਾਲਾ। ਪੂਰੈ ਭਾਗਿ = ਉੱਚੀ ਕਿਸਮਤ ਦੇ ਕਾਰਨ। ਸਮਾਏ = (ਪ੍ਰਭੂ ਵਿਚ) ਟਿਕਿਆ ਰਹਿੰਦਾ ਹੈ ॥੫੮॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-317", gurmukhi = "ਸੁ ਸਬਦ ਕਉ ਨਿਰੰਤਰਿ ਵਾਸੁ ਅਲਖੰ; ਜਹ ਦੇਖਾ ਤਹ ਸੋਈ ॥", transliteration = "su sabad kau nirantar vaas alakhan; jah dekhaa tah soee ||", translation = "That Shabad dwells deep within the nucleus of all beings. God is invisible; wherever I look, there I see Him.", hindi = "सु सबद कउ निरंतरि वासु अलखं; जह देखा तह सोई ॥", punjabi = "(ਜਿਸ 'ਸ਼ਬਦ' ਦੀ ਰਾਹੀਂ \"ਦੁੱਤਰ ਸਾਗਰ\" ਤਰੀਦਾ ਹੈ) ਉਸ 'ਸ਼ਬਦ' ਨੂੰ ਇੱਕ-ਰਸ ਥਾਂ (ਮਿਲਿਆ ਹੋਇਆ) ਹੈ (ਭਾਵ, ਉਹ ਸ਼ਬਦ ਹਰ ਥਾਂ ਭਰਪੂਰ ਹੈ), 'ਸ਼ਬਦ' ਅਲੱਖ (ਪ੍ਰਭੂ ਦਾ ਰੂਪ) ਹੈ, ਮੈਂ ਜਿਧਰ ਵੇਖਦਾ ਹਾਂ ਉਹ ਸ਼ਬਦ ਹੀ ਸ਼ਬਦ ਹੈ।", wordMeaning = "ਕਉ = ਨੂੰ। ਨਿਰੰਤਰਿ = ਇੱਕ-ਰਸ। ਦੇਖਾ = ਵੇਖਦਾ ਹਾਂ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-318", gurmukhi = "ਪਵਨ ਕਾ ਵਾਸਾ. ਸੁੰਨ ਨਿਵਾਸਾ; ਅਕਲ ਕਲਾ ਧਰ ਸੋਈ ॥", transliteration = "pavan kaa vaasaa. sunn nivaasaa; akal klaa dhar soee ||", translation = "The air is the dwelling place of the absolute Lord. He has no qualities; He has all qualities.", hindi = "पवन का वासा. सुंन निवासा; अकल कला धर सोई ॥", punjabi = "ਜਿਵੇਂ ਅਫੁਰ ਪ੍ਰਭੂ ਦਾ ਵਾਸ (ਹਰ ਥਾਂ) ਹੈ ਤਿਵੇਂ 'ਸ਼ਬਦ' ਦਾ ਵਾਸ (ਹਰ ਥਾਂ) ਹੈ। 'ਸ਼ਬਦ' ਉਹੀ ਹੈ ਜੋ ਸੰਪੂਰਣ ਸੱਤਿਆ-ਧਾਰੀ (ਪ੍ਰਭੂ) ਹੈ (ਭਾਵ 'ਪ੍ਰਭੂ' ਤੇ ਪ੍ਰਭੂ ਦੀ ਸਿਫ਼ਤ ਦਾ 'ਸ਼ਬਦ' ਇੱਕ ਹੀ ਹਨ)।", wordMeaning = "ਪਵਨ = ਸ਼ਬਦ, ਗੁਰੂ ਦਾ ਸ਼ਬਦ, ਪ੍ਰਭੂ ਦੀ ਸਿਫ਼ਤ-ਸਾਲਾਹ ਦਾ ਸ਼ਬਦ। {ਨੋਟ: \"ਤ੍ਰੈ ਸਤ ਅੰਗੁਲ ਵਾਈ\" ਦਾ ਉੱਤਰ ਪਉੜੀ ਨੰ: ੬੦ ਵਿਚ ਹੈ। ਸੋ, ਇਥੇ 'ਪਵਨ' ਦਾ ਅਰਥ 'ਵਾਈ' ਜਾਂ 'ਹਵਾ' ਨਹੀਂ ਹੈ। ਭਾਈ ਗੁਰਦਾਸ ਜੀ ਲਿਖਦੇ ਹਨ: \"ਪਵਨ ਗੁਰੂ ਗੁਰਸਬਦੁ ਹੈ,\" ਭਾਵ, 'ਪਵਨ' = 'ਗੁਰਸਬਦੁ' ਹੈ}। ਅਕਲ {ਸੰ: ਅਕਲ = ਨਾਸਤਿ ਕਲਾ ਅਵਯਵੋ ਯਸ੍ਯ नास्ति कला अवयवो यस्य} ਜਿਸ ਦੇ ਟੋਟੇ ਟੋਟੇ ਨਹੀਂ ਹਨ, ਪੂਰਨ ਪਾਰਬ੍ਰਹਮ। ਕਲਾਧਰ = ਸੱਤਾ ਧਾਰਨ ਵਾਲਾ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-319", gurmukhi = "ਨਦਰਿ ਕਰੇ. ਸਬਦੁ ਘਟ ਮਹਿ ਵਸੈ; ਵਿਚਹੁ ਭਰਮੁ ਗਵਾਏ ॥", transliteration = "nadar kre. sabad ghat mah vsai; vichah bharam gvaae ||", translation = "When He bestows His Glance of Grace, the Shabad comes to abide within the heart, and doubt is eradicated from within.", hindi = "नदरि करे. सबदु घट महि वसै; विचहु भरमु गवाए ॥", punjabi = "ਜਿਸ ਮਨੁੱਖ ਉਤੇ ਪ੍ਰਭੂ ਮੇਹਰ ਦੀ ਨਜ਼ਰ ਕਰਦਾ ਹੈ, ਉਸ ਦੇ ਹਿਰਦੇ ਵਿਚ ਇਹ 'ਸ਼ਬਦ' ਵੱਸਦਾ ਹੈ, ਉਹ ਮਨੁੱਖ ਹਿਰਦੇ ਵਿਚੋਂ ਭਟਕਣਾ ਦੂਰ ਕਰ ਲੈਂਦਾ ਹੈ,", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-320", gurmukhi = "ਤਨੁ ਮਨੁ ਨਿਰਮਲੁ ਨਿਰਮਲ ਬਾਣੀ; ਨਾਮੋੁ ਮੰਨਿ ਵਸਾਏ ॥", transliteration = "tan man niramal niramal baanee; naamo mann vsaae ||", translation = "The body and mind become immaculate, through the Immaculate Word of His Bani. Let His Name be enshrined in your mind.", hindi = "तनु मनु निरमलु निरमल बाणी; नामोु मंनि वसाए ॥", punjabi = "ਉਸ ਦਾ ਤਨ ਤੇ ਉਸ ਦਾ ਮਨ ਤੇ ਉਸ ਦੀ ਬਾਣੀ ਪਵਿਤ੍ਰ ਹੋ ਜਾਂਦੇ ਹਨ। ਪ੍ਰਭੂ ਦਾ ਨਾਮ ਹੀ ਉਹ ਮਨੁੱਖ ਆਪਣੇ ਮਨ ਵਿਚ ਵਸਾਈ ਰੱਖਦਾ ਹੈ।", wordMeaning = "ਨਾਮ = {ਅੱਖਰ 'ਮ' ਦੇ ਨਾਲ ਦੋ 'ਲਗਾਂ' ਹਨ, ਪਾਠ ਵਿਚ (ਮੋ) ਪੜ੍ਹਨਾ ਹੈ। ਵੇਖੋ 'ਗੁਰਬਾਣੀ ਵਿਆਕਰਣ'}। ਮੰਨਿ = ਮਨ ਵਿਚ।", startsAtMs = 0L, endsAtMs = 0L)
)

private fun generatedSidhaGoshtLines10(): List<BaniLine> = listOf(
    BaniLine(id = "sidha-gosht-321", gurmukhi = "ਸਬਦਿ ਗੁਰੂ. ਭਵਸਾਗਰੁ ਤਰੀਐ; ਇਤ ਉਤ ਏਕੋ ਜਾਣੈ ॥", transliteration = "sabad guroo. bhavsaagar treeai; it ut eko jaanai ||", translation = "The Shabad is the Guru, to carry you across the terrifying world-ocean. Know the One Lord alone, here and hereafter.", hindi = "सबदि गुरू. भवसागरु तरीऐ; इत उत एको जाणै ॥", punjabi = "ਸਤਿਗੁਰ ਦੇ 'ਸ਼ਬਦ' ਦੀ ਰਾਹੀਂ ਸੰਸਾਰ-ਸਮੁੰਦਰ ਤਰੀਦਾ ਹੈ। (ਜੋ ਤਰਿਆ ਹੈ ਉਹ) ਇਥੇ ਉਥੇ (ਲੋਕ ਪਰਲੋਕ ਵਿਚ ਹਰ ਥਾਂ) ਇੱਕ ਪ੍ਰਭੂ ਨੂੰ ਵਿਆਪਕ ਜਾਣਦਾ ਹੈ।", wordMeaning = "ਭਵ = ਸੰਸਾਰ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-322", gurmukhi = "ਚਿਹਨੁ ਵਰਨੁ ਨਹੀ ਛਾਇਆ ਮਾਇਆ; ਨਾਨਕ. ਸਬਦੁ ਪਛਾਣੈ ॥੫੯॥", transliteration = "chihan varan nhee chhaaiaa maaiaa; naanak. sabad pchhaanai ||59||", translation = "He has no form or color, shadow or illusion; O Nanak, realize the Shabad. ||59||", hindi = "चिहनु वरनु नही छाइआ माइआ; नानक. सबदु पछाणै ॥५९॥", punjabi = "ਹੇ ਨਾਨਕ! ਜੋ ਮਨੁੱਖ ਇਸ 'ਸ਼ਬਦ' ਨੂੰ ਪਛਾਣ ਲੈਂਦਾ ਹੈ 'ਸ਼ਬਦ' ਨਾਲ ਡੂੰਘੀ ਸਾਂਝ ਪਾ ਲੈਂਦਾ ਹੈ ਉਸ ਉਤੇ ਮਾਇਆ ਦਾ ਪ੍ਰਭਾਵ ਨਹੀਂ ਰਹਿੰਦਾ ਤੇ ਉਸ ਦਾ ਆਪਣਾ ਵੱਖਰਾ ਚਿਹਨ ਤੇ ਵਰਨ ਨਹੀਂ ਰਹਿ ਜਾਂਦਾ (ਭਾਵ, ਉਸ ਦਾ ਵੱਖਰਾ-ਪਨ ਮਿਟ ਜਾਂਦਾ ਹੈ, ਉਸ ਦੇ ਅੰਦਰੋਂ ਮੇਰ-ਤੇਰ ਦੂਰ ਹੋ ਜਾਂਦੀ ਹੈ) ॥੫੯॥", wordMeaning = "ਛਾਇਆ = ਪ੍ਰਭਾਵ, ਸਾਇਆ ॥੫੯॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-323", gurmukhi = "ਤ੍ਰੈ ਸਤ ਅੰਗੁਲ ਵਾਈ ਅਉਧੂ; ਸੁੰਨ ਸਚੁ ਆਹਾਰੋ ॥", transliteration = "trai sat angul vaaee audhoo; sunn sach aahaaro ||", translation = "O reclusive hermit, the True, Absolute Lord is the support of the exhaled breath, which extends out ten finger lengths.", hindi = "त्रै सत अंगुल वाई अउधू; सुंन सचु आहारो ॥", punjabi = "(ਉੱਤਰ:) ਹੇ ਜੋਗੀ! ਦਸ-ਉਂਗਲ-ਪ੍ਰਮਾਣ ਪ੍ਰਾਣਾਂ ਦੀ ਖ਼ੁਰਾਕ ਅਫੁਰ ਸੱਚਾ ਪ੍ਰਭੂ ਹੈ (ਭਾਵ, ਸੁਆਸ ਸੁਆਸ ਪ੍ਰਭੂ ਦਾ ਨਾਮ ਹੀ ਜਪਣਾ ਹੈ, ਪ੍ਰਭੂ ਦਾ ਨਾਮ ਹੀ ਪ੍ਰਾਣਾਂ ਦਾ ਆਸਰਾ ਹੈ)।", wordMeaning = "ਅਉਧੂ = ਹੇ ਜੋਗੀ! ਆਹਾਰੋ = ਖ਼ੁਰਾਕ, ਆਸਰਾ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-324", gurmukhi = "ਗੁਰਮੁਖਿ ਬੋਲੈ ਤਤੁ ਬਿਰੋਲੈ; ਚੀਨੈ ਅਲਖ ਅਪਾਰੋ ॥", transliteration = "gurmukh bolai tat birolai; cheenai alakh apaaro ||", translation = "The Gurmukh speaks and churns the essence of reality, and realizes the unseen, infinite Lord.", hindi = "गुरमुखि बोलै ततु बिरोलै; चीनै अलख अपारो ॥", punjabi = "ਜੋ ਮਨੁੱਖ ਗੁਰੂ ਦੇ ਹੁਕਮ ਵਿਚ ਤੁਰ ਕੇ (ਸੁਆਸ ਸੁਆਸ ਪ੍ਰਭੂ ਦਾ ਨਾਮ) ਜਪਦਾ ਹੈ, ਉਹ ਅਸਲੀਅਤ (ਭਾਵ, ਜਗਤ ਦਾ ਮੂਲ) ਹਾਸਲ ਕਰ ਲੈਂਦਾ ਹੈ, ਉਹ ਅਲੱਖ ਤੇ ਅਪਾਰ ਪ੍ਰਭੂ ਨੂੰ ਪਛਾਣ ਲੈਂਦਾ ਹੈ (ਪ੍ਰਭੂ ਨਾਲ ਡੂੰਘੀ ਸਾਂਝ ਪਾ ਲੈਂਦਾ ਹੈ)।", wordMeaning = "ਬੋਲੈ = ਜਪਦਾ ਹੈ। ਤਤੁ = ਅਸਲੀਅਤ। ਵਿਰੋਲੈ = ਰਿੜਕਦਾ ਹੈ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-325", gurmukhi = "ਤ੍ਰੈ ਗੁਣ ਮੇਟੈ. ਸਬਦੁ ਵਸਾਏ; ਤਾ ਮਨਿ ਚੂਕੈ ਅਹੰਕਾਰੋ ॥", transliteration = "trai gun metai. sabad vsaae; taa man chookai ahankaaro ||", translation = "Eradicating the three qualities, he enshrines the Shabad within, and then, his mind is rid of egotism.", hindi = "त्रै गुण मेटै. सबदु वसाए; ता मनि चूकै अहंकारो ॥", punjabi = "ਜਦੋਂ ਮਨੁੱਖ ਗੁਰੂ ਦਾ ਸ਼ਬਦ ਹਿਰਦੇ ਵਿਚ ਵਸਾਂਦਾ ਹੈ (ਸ਼ਬਦ ਦੀ ਬਰਕਤਿ ਨਾਲ ਮਾਇਆ ਦਾ) ਤ੍ਰੈ-ਗੁਣੀ ਪ੍ਰਭਾਵ ਮਿਟਾ ਲੈਂਦਾ ਹੈ, ਤਾਂ ਉਸ ਦੇ ਮਨ ਵਿਚੋਂ ਅਹੰਕਾਰ ਨਾਸ ਹੋ ਜਾਂਦਾ ਹੈ।", wordMeaning = "ਚੂਕੈ = ਮੁੱਕ ਜਾਂਦਾ ਹੈ", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-326", gurmukhi = "ਅੰਤਰਿ ਬਾਹਰਿ ਏਕੋ ਜਾਣੈ; ਤਾ ਹਰਿ ਨਾਮਿ ਲਗੈ ਪਿਆਰੋ ॥", transliteration = "antar baahar eko jaanai; taa har naam lgai piaaro ||", translation = "Inside and out, he knows the One Lord alone; he is in love with the Name of the Lord.", hindi = "अंतरि बाहरि एको जाणै; ता हरि नामि लगै पिआरो ॥", punjabi = "(ਇਸ ਤਰ੍ਹਾਂ) ਜਦੋਂ ਉਹ ਆਪਣੇ ਅੰਦਰ ਤੇ ਬਾਹਰ (ਜਗਤ ਵਿਚ) ਇੱਕ ਪ੍ਰਭੂ ਨੂੰ ਹੀ ਵੇਖਦਾ ਹੈ, ਤਾਂ ਉਸ ਦਾ ਪਿਆਰ ਪ੍ਰਭੂ ਦੇ ਨਾਮ ਵਿਚ ਬਣ ਜਾਂਦਾ ਹੈ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-327", gurmukhi = "ਸੁਖਮਨਾ ਇੜਾ ਪਿੰਗੁਲਾ ਬੂਝੈ; ਜਾ ਆਪੇ ਅਲਖੁ ਲਖਾਏ ॥", transliteration = "sukhamnaa iraa pingulaa boojhai; jaa aape alakh lkhaae ||", translation = "He understands the Sushmana, Ida and Pingala, when the unseen Lord reveals Himself.", hindi = "सुखमना इड़ा पिंगुला बूझै; जा आपे अलखु लखाए ॥", punjabi = "ਹੇ ਨਾਨਕ! ਜਦੋਂ ਅਲੱਖ ਪ੍ਰਭੂ ਆਪਣਾ ਆਪ ਲਖਾਂਦਾ ਹੈ (ਆਪਣੇ ਸਰੂਪ ਦੀ ਸਮਝ ਬਖ਼ਸ਼ਦਾ ਹੈ), ਤਦੋਂ ਗੁਰਮੁਖ ਇੜਾ ਪਿੰਗੁਲਾ ਸੁਖਮਨਾ ਨੂੰ ਸਮਝ ਲੈਂਦਾ ਹੈ,", wordMeaning = "ਇੜਾ = ਖੱਬੀ ਨਾਸ ਦੀ ਨਾੜੀ। ਪਿੰਗੁਲਾ = ਸੱਜੀ ਨਾਸ ਦੀ ਨਾੜੀ। ਸੁਖਮਨਾ = ਵਿਚਕਾਰਲੀ ਨਾੜੀ ਜਿਥੇ ਪ੍ਰਾਣਾਯਾਮ ਵੇਲੇ ਸੁਆਸ ਟਿਕਾਈਦੇ ਹਨ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-328", gurmukhi = "ਨਾਨਕ. ਤਿਹੁ ਤੇ ਊਪਰਿ ਸਾਚਾ; ਸਤਿਗੁਰ ਸਬਦਿ ਸਮਾਏ ॥੬੦॥", transliteration = "naanak. tih te oopar saachaa; stigur sabad smaae ||60||", translation = "O Nanak, the True Lord is above these three energy channels. Through the Word, the Shabad of the True Guru, one merges with Him. ||60||", hindi = "नानक. तिहु ते ऊपरि साचा; सतिगुर सबदि समाए ॥६०॥", punjabi = "(ਭਾਵ, ਗੁਰਮੁਖਿ ਨੂੰ ਇਹ ਸਮਝ ਆ ਜਾਂਦੀ ਹੈ ਕਿ) ਸਦਾ ਕਾਇਮ ਰਹਿਣ ਵਾਲਾ ਪ੍ਰਭੂ ਇੜਾ ਪਿੰਗੁਲਾ ਸੁਖਮਨਾ ਦੇ ਅੱਭਿਆਸ ਤੋਂ ਉਤਾਂਹ ਹੈ, ਉਸ ਵਿਚ ਤਾਂ ਸਤਿਗੁਰੂ ਦੇ ਸ਼ਬਦ ਦੀ ਰਾਹੀਂ (ਹੀ) ਸਮਾਈਦਾ ਹੈ ॥੬੦॥", wordMeaning = "ਤਿਹੁ ਤੇ = ਤਿਨ੍ਹਾਂ ਤੋਂ, ਇੜਾ ਪਿੰਗੁਲਾ ਸੁਖਮਨਾ ਦੇ ਅੱਭਿਆਸ ਤੋਂ, ਪ੍ਰਾਣਾਯਾਮ ਤੋਂ। ਮਨਿ = ਮਨ ਵਿਚੋਂ ॥੬੦॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-329", gurmukhi = "ਮਨ ਕਾ ਜੀਉ ਪਵਨੁ ਕਥੀਅਲੇ; ਪਵਨੁ ਕਹਾ ਰਸੁ ਖਾਈ ॥", transliteration = "man kaa jeeu pavan ktheeale; pavan khaa ras khaaee ||", translation = "\"The air is said to be the soul of the mind. But what does the air feed on?", hindi = "मन का जीउ पवनु कथीअले; पवनु कहा रसु खाई ॥", punjabi = "(ਪ੍ਰਸ਼ਨ:) ਮਨ ਦਾ ਆਸਰਾ ਪ੍ਰਾਣ ਕਹੀਦੇ ਹਨ, ਪ੍ਰਾਣ ਕਿਥੋਂ ਖ਼ੁਰਾਕ ਲੈਂਦੇ ਹਨ? (ਭਾਵ, ਪ੍ਰਾਣਾਂ ਦਾ ਆਸਰਾ ਕੌਣ ਹੈ?)", wordMeaning = "ਜੀਉ = ਜਿੰਦ, ਆਸਰਾ। ਪਵਨੁ = ਪ੍ਰਾਣ। ਰਸੁ = ਖ਼ੁਰਾਕ। ਕਹਾ = ਕਿਥੋਂ?", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-330", gurmukhi = "ਗਿਆਨ ਕੀ ਮੁਦ੍ਰਾ ਕਵਨ ਅਉਧੂ; ਸਿਧ ਕੀ ਕਵਨ ਕਮਾਈ ॥", transliteration = "giaan kee mudraa kavan audhoo; sidh kee kavan kmaaee ||", translation = "What is the way of the spiritual teacher, and the reclusive hermit? What is the occupation of the Siddha?\"", hindi = "गिआन की मुद्रा कवन अउधू; सिध की कवन कमाई ॥", punjabi = "ਹੇ ਜੋਗੀ! ਗਿਆਨ ਦੀ ਪ੍ਰਾਪਤੀ ਦਾ ਕੇਹੜਾ ਸਾਧਨ ਹੈ? ਜੋਗ-ਸਾਧਨਾਂ ਵਿਚ ਪੁੱਗੇ ਹੋਏ ਜੋਗੀ ਨੂੰ ਕੀਹ ਪ੍ਰਾਪਤ ਹੋ ਜਾਂਦਾ ਹੈ?", wordMeaning = "ਮੁਦ੍ਰਾ = ਸਾਧਨ। ਅਉਧੂ = ਹੇ ਜੋਗੀ! ਸਿਧ = ਜੋਗ-ਸਾਧਨਾਂ ਵਿਚ ਪੁੱਗਾ ਹੋਇਆ ਜੋਗੀ। ਕਵਨ ਕਮਾਈ = ਕੀਹ ਮਿਲ ਜਾਂਦਾ ਹੈ?", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-331", gurmukhi = "ਬਿਨੁ ਸਬਦੈ. ਰਸੁ, ਨ ਆਵੈ ਅਉਧੂ; ਹਉਮੈ ਪਿਆਸ. ਨ ਜਾਈ ॥", transliteration = "bin sabdai. ras, na aavai audhoo; haumai piaas. na jaaee ||", translation = "Without the Shabad, the essence does not come, O hermit, and the thirst of egotism does not depart.", hindi = "बिनु सबदै. रसु, न आवै अउधू; हउमै पिआस. न जाई ॥", punjabi = "(ਉੱਤਰ:) ਹੇ ਜੋਗੀ! ਸਤਿਗੁਰੂ ਦੇ ਸ਼ਬਦ ਤੋਂ ਬਿਨਾਂ (ਪ੍ਰਾਣਾਂ ਨੂੰ) ਰਸ ਨਹੀਂ ਆਉਂਦਾ (ਭਾਵ, ਗੁਰੂ ਦਾ ਸ਼ਬਦ ਹੀ ਪ੍ਰਾਣਾਂ ਦਾ ਆਸਰਾ ਹੈ, ਪ੍ਰਾਨਾਂ ਦੀ ਖ਼ੁਰਾਕ ਹੈ)। ਗੁਰੂ-ਸ਼ਬਦ ਤੋਂ ਬਿਨਾ ਹਉਮੈ ਦੀ ਤ੍ਰੇਹ ਨਹੀਂ ਮਿਟਦੀ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-332", gurmukhi = "ਸਬਦਿ ਰਤੇ ਅੰਮ੍ਰਿਤ ਰਸੁ ਪਾਇਆ; ਸਾਚੇ ਰਹੇ ਅਘਾਈ ॥", transliteration = "sabad rte amrit ras paaiaa; saache rhe aghaaee ||", translation = "Imbued with the Shabad, one finds the ambrosial essence, and remains fulfilled with the True Name.", hindi = "सबदि रते अंम्रित रसु पाइआ; साचे रहे अघाई ॥", punjabi = "ਜੋ ਮਨੁੱਖ ਗੁਰੂ ਦੇ ਸ਼ਬਦ ਵਿਚ ਰੰਗੇ ਜਾਂਦੇ ਹਨ, ਉਹਨਾਂ ਨੂੰ ਸਦਾ ਟਿਕੇ ਰਹਿਣ ਵਾਲਾ ਨਾਮ-ਰਸ ਮਿਲ ਜਾਂਦਾ ਹੈ, ਉਹ ਸੱਚੇ ਪ੍ਰਭੂ ਵਿਚ ਰੱਜੇ ਰਹਿੰਦੇ ਹਨ (ਭਾਵ, ਨਾਮ ਵਿਚ ਜੁੜ ਕੇ ਸੰਤੋਖੀ ਹੋ ਜਾਂਦੇ ਹਨ)।", wordMeaning = "ਅਘਾਇ ਰਹੇ = ਰੱਜੇ ਰਹਿੰਦੇ ਹਨ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-333", gurmukhi = "ਕਵਨ ਬੁਧਿ ਜਿਤੁ ਅਸਥਿਰੁ ਰਹੀਐ; ਕਿਤੁ ਭੋਜਨਿ ਤ੍ਰਿਪਤਾਸੈ ॥", transliteration = "kavan budh jit asthir rheeai; kit bhojan triptaasai ||", translation = "\"What is that wisdom, by which one remains steady and stable? What food brings satisfaction?\"", hindi = "कवन बुधि जितु असथिरु रहीऐ; कितु भोजनि त्रिपतासै ॥", punjabi = "(ਪ੍ਰਸ਼ਨ:) ਉਹ ਕੇਹੜੀ ਮਤ ਹੈ ਜਿਸ ਦੀ ਰਾਹੀ ਮਨ ਸਦਾ ਟਿਕਿਆ ਰਹਿ ਸਕਦਾ ਹੈ? ਕੇਹੜੀ ਖ਼ੁਰਾਕ ਨਾਲ ਮਨ ਸਦਾ ਰੱਜਿਆ ਰਹਿ ਸਕੇ?", wordMeaning = "ਕਿਤੁ ਭੋਜਨਿ = ਕਿਸ ਭੋਜਨ ਨਾਲ? ਤ੍ਰਿਪਤਾਸੈ = ਤ੍ਰਿਪਤ ਰਹੀਦਾ ਹੈ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-334", gurmukhi = "ਨਾਨਕ. ਦੁਖੁ ਸੁਖੁ ਸਮ ਕਰਿ ਜਾਪੈ; ਸਤਿਗੁਰ ਤੇ. ਕਾਲੁ, ਨ ਗ੍ਰਾਸੈ ॥੬੧॥", transliteration = "naanak. dukh sukh sam kar jaapai; stigur te. kaal, na graasai ||61||", translation = "O Nanak, when one looks upon pain and pleasure alike, through the True Guru, then he is not consumed by Death. ||61||", hindi = "नानक. दुखु सुखु सम करि जापै; सतिगुर ते. कालु, न ग्रासै ॥६१॥", punjabi = "(ਉੱਤਰ:) ਹੇ ਨਾਨਕ! ਸਤਿਗੁਰੂ ਤੋਂ (ਜੋ ਮਤ ਮਿਲਦੀ ਹੈ ਉਸ ਨਾਲ) ਦੁੱਖ ਤੇ ਸੁਖ ਇੱਕ-ਸਮਾਨ ਜਾਪਦਾ ਹੈ, ਸਤਿਗੁਰੂ ਤੋਂ (ਜੋ ਨਾਮ-ਭੋਜਨ ਮਿਲਦਾ ਹੈ, ਉਸ ਕਰਕੇ) ਮੌਤ (ਦਾ ਡਰ) ਪੋਹ ਨਹੀਂ ਸਕਦਾ ॥੬੧॥", wordMeaning = "ਸਮ = ਬਰਾਬਰ, ਇਕ-ਸਮਾਨ। ਗ੍ਰਾਸੈ = ਗ੍ਰਸਦਾ, ਵਿਆਪਦਾ ॥੬੧॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-335", gurmukhi = "ਰੰਗਿ. ਨ ਰਾਤਾ; ਰਸਿ ਨਹੀ ਮਾਤਾ ॥", transliteration = "rang. na raataa; ras nhee maataa ||", translation = "If one is not imbued with the Lord's Love, nor intoxicated with His subtle essence,", hindi = "रंगि. न राता; रसि नही माता ॥", punjabi = "(ਸ਼ਬਦ ਦੀ ਕਮਾਈ ਤੋਂ ਬਿਨਾ ਮਨੁੱਖ ਦਾ ਮਨ) ਪ੍ਰਭੂ ਦੇ ਪਿਆਰ ਵਿਚ ਰੰਗਿਆ ਨਹੀਂ ਜਾਂਦਾ ਤੇ ਉਹ ਪ੍ਰਭੂ ਦੇ ਆਨੰਦ ਵਿਚ ਖੀਵਾ ਨਹੀਂ ਹੁੰਦਾ।", wordMeaning = "ਰੰਗਿ = ਰੰਗ ਵਿਚ, ਪਿਆਰ ਵਿਚ। ਰਸਿ = ਰਸ ਵਿਚ। ਮਾਤਾ = ਮਸਤ, ਖੀਵਾ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-336", gurmukhi = "ਬਿਨੁ ਗੁਰਸਬਦੈ; ਜਲਿ ਬਲਿ ਤਾਤਾ ॥", transliteration = "bin gurasabdai; jal bal taataa ||", translation = "without the Word of the Guru's Shabad, he is frustrated, and consumed by his own inner fire.", hindi = "बिनु गुरसबदै; जलि बलि ताता ॥", punjabi = "ਸਤਿਗੁਰੂ ਦੇ ਸ਼ਬਦ (ਦੀ ਕਮਾਈ ਕਰਨ) ਤੋਂ ਬਿਨਾ ਮਨੁੱਖ (ਮਾਇਕ ਧੰਧਿਆਂ ਵਿਚ) ਸੜ ਬਲ ਕੇ ਖਿੱਝਦਾ ਰਹਿੰਦਾ ਹੈ,", wordMeaning = "ਤਾਤਾ = ਸੜਦਾ, ਖਿੱਝਦਾ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-337", gurmukhi = "ਬਿੰਦੁ. ਨ ਰਾਖਿਆ; ਸਬਦੁ. ਨ ਭਾਖਿਆ ॥", transliteration = "bind. na raakhiaa; sabad. na bhaakhiaa ||", translation = "He does not preserve his semen and seed, and does not chant the Shabad.", hindi = "बिंदु. न राखिआ; सबदु. न भाखिआ ॥", punjabi = "ਜਿਸ ਮਨੁੱਖ ਨੇ ਗੁਰ-ਸ਼ਬਦ ਨਹੀਂ ਉਚਾਰਿਆ, ਉਸ ਨੇ ਜਤੀ ਬਣ ਕੇ ਕੁਝ ਨਹੀਂ ਖੱਟਿਆ।", wordMeaning = "ਬਿੰਦੁ = ਵੀਰਜ। ਬਿੰਦੁ ਨ ਰਾਖਿਆ = ਉਸ ਮਨੁੱਖ ਨੇ ਵੀਰ੍ਯ ਨਹੀਂ ਸਾਂਭਿਆ, (ਭਾਵ) ਉਹ ਕਾਹਦਾ ਜਤੀ?", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-338", gurmukhi = "ਪਵਨੁ. ਨ ਸਾਧਿਆ; ਸਚੁ. ਨ ਅਰਾਧਿਆ ॥", transliteration = "pavan. na saadhiaa; sach. na araadhiaa ||", translation = "He does not control his breath; he does not worship and adore the True Lord.", hindi = "पवनु. न साधिआ; सचु. न अराधिआ ॥", punjabi = "ਜਿਸ ਨੇ ਸੱਚੇ ਪ੍ਰਭੂ ਨੂੰ ਸਿਮਰਿਆ ਨਹੀਂ, ਉਸ ਨੇ ਪ੍ਰਾਣਾਯਾਮ ਕਰ ਕੇ ਕੀਹ ਲਿਆ?", wordMeaning = "ਪਵਨੁ ਨ ਸਾਧਿਆ = (ਪ੍ਰਾਣਾਯਾਮ ਦੀ ਰਾਹੀਂ) ਪ੍ਰਾਣ ਵੱਸ ਵਿਚ ਨਹੀਂ ਕੀਤੇ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-339", gurmukhi = "ਅਕਥ ਕਥਾ ਲੇ; ਸਮ ਕਰਿ ਰਹੈ ॥", transliteration = "akath kthaa le; sam kar rhai ||", translation = "But one who speaks the Unspoken Speech, and remains balanced,", hindi = "अकथ कथा ले; सम करि रहै ॥", punjabi = "ਜੇ ਮਨੁੱਖ ਅਕੱਥ ਪ੍ਰਭੂ ਦੇ ਗੁਣ ਗਾ ਕੇ (ਦੁਖ ਸੁਖ ਨੂੰ) ਇੱਕ-ਸਮਾਨ ਜਾਣ ਕੇ ਜੀਵਨ ਬਿਤੀਤ ਕਰੇ,", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-340", gurmukhi = "ਤਉ ਨਾਨਕ; ਆਤਮ ਰਾਮ ਕਉ ਲਹੈ ॥੬੨॥", transliteration = "tau naanak; aatam raam kau lhai ||62||", translation = "O Nanak, attains the Lord, the Supreme Soul. ||62||", hindi = "तउ नानक; आतम राम कउ लहै ॥६२॥", punjabi = "ਤਾਂ ਹੇ ਨਾਨਕ! ਉਹ ਸਾਰੇ-ਸੰਸਾਰ-ਦੀ-ਜਿੰਦ ਪ੍ਰਭੂ ਦੀ ਪ੍ਰਾਪਤੀ ਕਰ ਲੈਂਦਾ ਹੈ ॥੬੨॥", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-341", gurmukhi = "ਗੁਰ ਪਰਸਾਦੀ ਰੰਗੇ ਰਾਤਾ ॥", transliteration = "gur parsaadee range raataa ||", translation = "By Guru's Grace, one is attuned to the Lord's Love.", hindi = "गुर परसादी रंगे राता ॥", punjabi = "ਸਤਿਗੁਰੂ ਦੀ ਮੇਹਰ ਨਾਲ ਜੋ ਮਨੁੱਖ ਪ੍ਰਭੂ ਦੇ ਪਿਆਰ ਵਿਚ ਰੰਗੀਜਦਾ ਹੈ,", wordMeaning = "ਰੰਗੇ = (ਪ੍ਰਭੂ ਦੇ) ਪਿਆਰ ਵਿਚ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-342", gurmukhi = "ਅੰਮ੍ਰਿਤੁ ਪੀਆ; ਸਾਚੇ ਮਾਤਾ ॥", transliteration = "amrit peeaa; saache maataa ||", translation = "Drinking in the Ambrosial Nectar, he is intoxicated with the Truth.", hindi = "अंम्रितु पीआ; साचे माता ॥", punjabi = "ਉਹ ਨਾਮ-ਅੰਮ੍ਰਿਤ ਪੀ ਲੈਂਦਾ ਹੈ, ਤੇ ਸੱਚੇ ਪ੍ਰਭੂ ਵਿਚ ਖੀਵਾ ਰਹਿੰਦਾ ਹੈ।", wordMeaning = "ਪੀਆ = ਪੀਤਾ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-343", gurmukhi = "ਗੁਰ ਵੀਚਾਰੀ; ਅਗਨਿ ਨਿਵਾਰੀ ॥", transliteration = "gur veechaaree; agan nivaaree ||", translation = "Contemplating the Guru, the fire within is put out.", hindi = "गुर वीचारी; अगनि निवारी ॥", punjabi = "ਜੋ ਮਨੁੱਖ ਗੁਰ-(ਸ਼ਬਦ) ਦੀ ਰਾਹੀਂ ਵਿਚਾਰਵਾਨ ਹੋ ਗਿਆ ਹੈ ਉਸ ਨੇ (ਤ੍ਰਿਸ਼ਨਾ) ਅੱਗ ਬੁਝਾ ਲਈ ਹੈ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-344", gurmukhi = "ਅਪਿਉ ਪੀਓ; ਆਤਮ ਸੁਖੁ ਧਾਰੀ ॥", transliteration = "apiu peeo; aatam sukh dhaaree ||", translation = "Drinking in the Ambrosial Nectar, the soul settles in peace.", hindi = "अपिउ पीओ; आतम सुखु धारी ॥", punjabi = "ਉਸ ਨੇ (ਨਾਮ-) ਅੰਮ੍ਰਿਤ ਪੀ ਲਿਆ ਹੈ, ਉਸ ਨੂੰ ਆਤਮਕ ਸੁਖ ਲੱਭ ਪਿਆ ਹੈ।", wordMeaning = "ਅਪਿਉ = ਅੰਮ੍ਰਿਤ, ਆਤਮਕ ਜੀਵਨ ਦੇਣ ਵਾਲਾ ਨਾਮ ਜਲ। ਪੀਓ = ਪੀਤਾ। ਧਾਰੀ = ਧਾਰਿਆ, ਲੱਭਾ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-345", gurmukhi = "ਸਚੁ ਅਰਾਧਿਆ; ਗੁਰਮੁਖਿ ਤਰੁ ਤਾਰੀ ॥", transliteration = "sach araadhiaa; gurmukh tar taaree ||", translation = "Worshipping the True Lord in adoration, the Gurmukh crosses over the river of life.", hindi = "सचु अराधिआ; गुरमुखि तरु तारी ॥", punjabi = "(ਹੇ ਜੋਗੀ!) ਗੁਰੂ ਦੇ ਰਾਹ ਤੇ ਤੁਰ ਕੇ ਸੱਚੇ ਪ੍ਰਭੂ ਦਾ ਸਿਮਰਨ ਕਰ ਕੇ ('ਦੁਤਰ ਸਾਗਰ' ਤੋਂ) ਪਾਰ ਲੰਘ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-346", gurmukhi = "ਨਾਨਕ ਬੂਝੈ; ਕੋ ਵੀਚਾਰੀ ॥੬੩॥", transliteration = "naanak boojhai; ko veechaaree ||63||", translation = "O Nanak, after deep contemplation, this is understood. ||63||", hindi = "नानक बूझै; को वीचारी ॥६३॥", punjabi = "(ਪਰ) ਹੇ ਨਾਨਕ! ਕੋਈ ਵਿਰਲਾ ਵਿਚਾਰਵਾਨ (ਇਸ ਗੱਲ ਨੂੰ) ਸਮਝਦਾ ਹੈ ॥੬੩॥", wordMeaning = "ਵੀਚਾਰੀ = ਵਿਚਾਰ-ਵਾਨ। ਤਰੁ ਤਾਰੀ = ਤਾਰੀ ਤਰੁ, ਪਾਰ ਲੰਘ। ਕੋ = ਕੋਈ ਵਿਰਲਾ ॥੬੩॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-347", gurmukhi = "ਇਹੁ ਮਨੁ ਮੈਗਲੁ. ਕਹਾ ਬਸੀਅਲੇ; ਕਹਾ ਬਸੈ ਇਹੁ ਪਵਨਾ ॥", transliteration = "ih man maigal. khaa bseeale; khaa bsai ih pavnaa ||", translation = "\"Where does this mind-elephant live? Where does the breath reside?", hindi = "इहु मनु मैगलु. कहा बसीअले; कहा बसै इहु पवना ॥", punjabi = "(ਪ੍ਰਸ਼ਨ:) ਮਸਤ ਹਾਥੀ (ਵਰਗਾ) ਇਹ ਮਨ ਕਿਥੇ ਵੱਸਦਾ ਹੈ? ਇਹ ਪ੍ਰਾਣ ਕਿਥੇ ਵੱਸਦੇ ਹਨ?", wordMeaning = "ਮੈਗਲੁ = (ਸੰ: ਮਦਕਲ; मदकल) ਮਸਤ ਹਾਥੀ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-348", gurmukhi = "ਕਹਾ ਬਸੈ ਸੁ ਸਬਦੁ ਅਉਧੂ; ਤਾ ਕਉ ਚੂਕੈ ਮਨ ਕਾ ਭਵਨਾ ॥", transliteration = "kahaa bsai su sabad audhoo; taa kau chookai man kaa bhavnaa ||", translation = "Where should the Shabad reside, so that the wanderings of the mind may cease?\"", hindi = "कहा बसै सु सबदु अउधू; ता कउ चूकै मन का भवना ॥", punjabi = "ਹੇ ਜੋਗੀ (ਨਾਨਕ!) ਉਹ ਸ਼ਬਦ ਕਿਥੇ ਵੱਸਦਾ ਹੈ (ਜਿਸ ਦੀ ਰਾਹੀਂ ਤੁਹਾਡੇ ਮਤ-ਅਨੁਸਾਰ) ਮਨ ਦੀ ਭਟਕਣਾ ਮੁੱਕਦੀ ਹੈ?", wordMeaning = "ਭਵਨਾ = ਭਟਕਣਾ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-349", gurmukhi = "ਨਦਰਿ ਕਰੇ ਤਾ ਸਤਿਗੁਰੁ ਮੇਲੇ; ਤਾ ਨਿਜ ਘਰਿ ਵਾਸਾ ਇਹੁ ਮਨੁ ਪਾਏ ॥", transliteration = "nadar kre taa stigur mele; taa nij ghar vaasaa ih man paae ||", translation = "When the Lord blesses one with His Glance of Grace, he leads him to the True Guru. Then, this mind dwells in its own home within.", hindi = "नदरि करे ता सतिगुरु मेले; ता निज घरि वासा इहु मनु पाए ॥", punjabi = "(ਉੱਤਰ:) ਜੇ ਪ੍ਰਭੂ ਮੇਹਰ ਦੀ ਨਿਗਾਹ ਕਰੇ ਤਾਂ ਉਹ ਸਤਿਗੁਰੂ ਮਿਲਾਂਦਾ ਹੈ ਤੇ (ਗੁਰੂ ਮਿਲਿਆਂ) ਇਹ ਮਨ ਆਪਣੇ ਹੀ ਘਰ ਵਿਚ (ਭਾਵ, ਆਪਣੇ ਆਪ ਵਿਚ) ਟਿਕ ਜਾਂਦਾ ਹੈ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-350", gurmukhi = "ਆਪੈ ਆਪੁ ਖਾਇ. ਤਾ ਨਿਰਮਲੁ ਹੋਵੈ; ਧਾਵਤੁ ਵਰਜਿ ਰਹਾਏ ॥", transliteration = "aapai aap khaai. taa niramal hovai; dhaavat varaj rhaae ||", translation = "When the individual consumes his egotism, he becomes immaculate, and his wandering mind is restrained.", hindi = "आपै आपु खाइ. ता निरमलु होवै; धावतु वरजि रहाए ॥", punjabi = "(ਗੁਰੂ ਦੇ ਹੁਕਮ ਵਿਚ ਤੁਰ ਕੇ ਜਦੋਂ) ਮਨ ਆਪਣੇ ਆਪ ਨੂੰ ਖਾ ਜਾਂਦਾ ਹੈ (ਭਾਵ, ਆਪਣੇ ਸੰਕਲਪ ਵਿਕਲਪ ਮੁਕਾ ਦੇਂਦਾ ਹੈ, ਜਦੋਂ ਮਨੁੱਖ ਮਨ ਦੇ ਪਿੱਛੇ ਤੁਰਨ ਦੇ ਥਾਂ ਗੁਰੂ ਦੇ ਹੁਕਮ ਵਿਚ ਤੁਰਦਾ ਹੈ) ਤਾਂ ਮਨ ਪਵਿਤ੍ਰ ਹੋ ਜਾਂਦਾ ਹੈ (ਕਿਉਂਕਿ ਇਸ ਤਰ੍ਹਾਂ ਗੁਰੂ ਦੇ ਉਪਦੇਸ਼ ਨਾਲ ਮਨੁੱਖ) ਮਾਇਆ ਵਲ ਦੌੜਦੇ ਮਨ ਨੂੰ ਰੋਕ ਰੱਖਦਾ ਹੈ।", wordMeaning = "ਆਪੈ ਆਪੁ = ਆਪਣੇ ਆਪ ਨੂੰ। ਧਾਵਤੁ = (ਵਿਕਾਰਾਂ ਵਲ) ਦੌੜਦਾ। ਵਰਜਿ = ਰੋਕ ਕੇ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-351", gurmukhi = "ਕਿਉ ਮੂਲੁ ਪਛਾਣੈ. ਆਤਮੁ ਜਾਣੈ; ਕਿਉ ਸਸਿ ਘਰਿ. ਸੂਰੁ ਸਮਾਵੈ ॥", transliteration = "kiu mool pchhaanai. aatam jaanai; kiu sas ghar. soor smaavai ||", translation = "\"How can the root, the source of all be realized? How can the soul know itself? How can the sun enter into the house of the moon?\"", hindi = "किउ मूलु पछाणै. आतमु जाणै; किउ ससि घरि. सूरु समावै ॥", punjabi = "(ਪ੍ਰਸ਼ਨ:) ਮਨੁੱਖ (ਜਗਤ ਦੇ) ਮੁੱਢ (ਪ੍ਰਭੂ) ਨੂੰ ਕਿਵੇਂ ਪਛਾਣੇ? ਆਪਣੇ ਆਤਮਾ ਨੂੰ ਕਿਵੇਂ ਸਮਝੇ? ਚੰਦ੍ਰਮਾ ਦੇ ਘਰ ਵਿਚ ਸੂਰਜ ਕਿਵੇਂ ਟਿਕੇ?", wordMeaning = "ਸਸਿ = ਚੰਦ੍ਰਮਾ। ਹਉਮੈ = ਹਉ ਮੈਂ, ਮੈਂ ਮੈਂ, ਮੈਂ ਦਾ ਹਰ ਵੇਲੇ ਧਿਆਨ, ਹਰ ਵੇਲੇ ਆਪਣੇ ਆਪ ਦਾ ਖ਼ਿਆਲ, ਵੱਖਰਾ-ਪਨ, ਖ਼ੁਦਗ਼ਰਜ਼ੀ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-352", gurmukhi = "ਗੁਰਮੁਖਿ. ਹਉਮੈ ਵਿਚਹੁ ਖੋਵੈ; ਤਉ ਨਾਨਕ. ਸਹਜਿ ਸਮਾਵੈ ॥੬੪॥", transliteration = "gurmukh. haumai vichah khovai; tau naanak. sahaj smaavai ||64||", translation = "The Gurmukh eliminates egotism from within; then, O Nanak, the sun naturally enters into the home of the moon. ||64||", hindi = "गुरमुखि. हउमै विचहु खोवै; तउ नानक. सहजि समावै ॥६४॥", punjabi = "(ਉੱਤਰ:) ਜੋ ਮਨੁੱਖ ਗੁਰੂ ਦੇ ਹੁਕਮ ਵਿਚ ਤੁਰਦਾ ਹੈ ਉਹ ਆਪਣੇ ਅੰਦਰੋਂ 'ਹਉਮੈ' ਦੂਰ ਕਰਦਾ ਹੈ, ਤਦੋਂ ਹੇ ਨਾਨਕ! ਉਹ ਸਹਿਜ ਅਵਸਥਾ ਵਿਚ ਟਿਕ ਜਾਂਦਾ ਹੈ ॥੬੪॥", wordMeaning = "ਸਹਜਿ = ਸਹਿਜ ਵਿਚ, ਅਡੋਲ ਅਵਸਥਾ ਵਿਚ ॥੬੪॥", startsAtMs = 0L, endsAtMs = 0L)
)

