    BaniLine(id = "sidha-gosht-353", gurmukhi = "ਇਹੁ ਮਨੁ ਨਿਹਚਲੁ ਹਿਰਦੈ ਵਸੀਅਲੇ; ਗੁਰਮੁਖਿ ਮੂਲੁ ਪਛਾਣਿ ਰਹੈ ॥", transliteration = "ih man nihachal hirdai vseeale; gurmukh mool pchhaan rhai ||", translation = "When the mind becomes steady and stable, it abides in the heart, and then the Gurmukh realizes the root, the source of all.", hindi = "इहु मनु निहचलु हिरदै वसीअले; गुरमुखि मूलु पछाणि रहै ॥", punjabi = "ਜਦੋਂ ਮਨੁੱਖ ਗੁਰੂ ਦੇ ਹੁਕਮ ਤੇ ਤੁਰ ਕੇ (ਜਗਤ ਦੇ) ਮੂਲ-(ਪ੍ਰਭੂ) ਨੂੰ ਪਛਾਣਦਾ ਹੈ (ਪ੍ਰਭੂ ਨਾਲ ਸਾਂਝ ਪਾਂਦਾ ਹੈ), ਤਾਂ ਇਹ ਮਨ ਅਡੋਲ ਹੋ ਕੇ ਹਿਰਦੇ ਵਿਚ ਟਿਕਦਾ ਹੈ।", wordMeaning = "ਨਿਹਚਲੁ = ਅਡੋਲ ਹੋ ਕੇ (ਭਾਵ, ਭਟਕਣੋਂ ਹਟ ਕੇ)। ਹਿਰਦੈ = ਹਿਰਦੇ ਵਿਚ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-354", gurmukhi = "ਨਾਭਿ ਪਵਨੁ ਘਰਿ ਆਸਣਿ ਬੈਸੈ; ਗੁਰਮੁਖਿ ਖੋਜਤ ਤਤੁ ਲਹੈ ॥", transliteration = "naabh pavan ghar aasan baisai; gurmukh khojat tat lhai ||", translation = "The breath is seated in the home of the navel; the Gurmukh searches, and finds the essence of reality.", hindi = "नाभि पवनु घरि आसणि बैसै; गुरमुखि खोजत ततु लहै ॥", punjabi = "ਪ੍ਰਾਣ (ਭਾਵ, ਸੁਆਸ) ਨਾਭੀ-ਰੂਪ ਘਰ ਵਿਚ ਆਸਣ ਤੇ ਬੈਠਦਾ ਹੈ (ਭਾਵ, ਪ੍ਰਾਣਾਂ ਦਾ ਆਰੰਭ ਨਾਭੀ ਤੋਂ ਹੁੰਦਾ ਹੈ), ਗੁਰੂ ਦੀ ਰਾਹੀਂ ਖੋਜ ਕਰ ਕੇ ਮਨੁੱਖ ਅਸਲੀਅਤ ਲੱਭਦਾ ਹੈ।", wordMeaning = "ਆਸਣਿ = ਆਸਣ ਉੱਤੇ। ਬੈਸੈ = ਬੈਠਦਾ ਹੈ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-355", gurmukhi = "ਸੁ ਸਬਦੁ ਨਿਰੰਤਰਿ ਨਿਜ ਘਰਿ ਆਛੈ; ਤ੍ਰਿਭਵਣ ਜੋਤਿ ਸੁ ਸਬਦਿ ਲਹੈ ॥", transliteration = "su sabad nirantar nij ghar aachhai; tribhavan jot su sabad lhai ||", translation = "This Shabad permeates the nucleus of the self, deep within, in its own home; the Light of this Shabad pervades the three worlds.", hindi = "सु सबदु निरंतरि निज घरि आछै; त्रिभवण जोति सु सबदि लहै ॥", punjabi = "ਉਹ ਸ਼ਬਦ (ਜੋ 'ਦੁਤਰ ਸਾਗਰ' ਤੋਂ ਤਾਰਦਾ ਹੈ) ਇਕ-ਰਸ ਆਪਣੇ ਅਸਲ ਘਰ ਵਿਚ (ਭਾਵ, ਸੁੰਨ ਪ੍ਰਭੂ ਵਿਚ) ਟਿਕਦਾ ਹੈ, ਮਨੁੱਖ ਉਸ ਸ਼ਬਦ ਦੀ ਰਾਹੀਂ (ਹੀ) ਤ੍ਰਿਲੋਕੀ ਵਿਚ ਵਿਆਪਕ ਪ੍ਰਭੂ ਦੀ ਜੋਤਿ ਨੂੰ ਲੱਭਦਾ ਹੈ।", wordMeaning = "ਨਿਜ ਘਰਿ = ਆਪਣੇ ਅਸਲ ਘਰ ਵਿਚ। ਆਛੈ = ਹੈ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-356", gurmukhi = "ਖਾਵੈ ਦੂਖ. ਭੂਖ ਸਾਚੇ ਕੀ; ਸਾਚੇ ਹੀ ਤ੍ਰਿਪਤਾਸਿ ਰਹੈ ॥", transliteration = "khaavai dookh. bhookh saache kee; saache hee triptaas rhai ||", translation = "Hunger for the True Lord shall consume your pain, and through the True Lord, you shall be satisfied.", hindi = "खावै दूख. भूख साचे की; साचे ही त्रिपतासि रहै ॥", punjabi = "(ਜਿਉਂ ਜਿਉਂ) ਸੱਚੇ ਪ੍ਰਭੂ ਨੂੰ ਮਿਲਣ ਦੀ ਤਾਂਘ ਵਧਦੀ ਹੈ (ਤਿਉਂ ਤਿਉਂ) ਮਨੁੱਖ ਦੁੱਖਾਂ ਨੂੰ ਮੁਕਾ ਲੈਂਦਾ ਹੈ; ਸੱਚੇ ਪ੍ਰਭੂ ਵਿਚ ਹੀ ਤ੍ਰਿਪਤ ਰਹਿੰਦਾ ਹੈ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-357", gurmukhi = "ਅਨਹਦ ਬਾਣੀ ਗੁਰਮੁਖਿ ਜਾਣੀ; ਬਿਰਲੋ ਕੋ ਅਰਥਾਵੈ ॥", transliteration = "anahad baanee gurmukh jaanee; birlo ko arthaavai ||", translation = "The Gurmukh knows the unstruck sound current of the Bani; how rare are those who understand.", hindi = "अनहद बाणी गुरमुखि जाणी; बिरलो को अरथावै ॥", punjabi = "ਇਕ-ਰਸ ਵਿਆਪਕ ਰੱਬੀ ਜੀਵਨ-ਰੌ ਨੂੰ ਕਿਸੇ ਵਿਰਲੇ ਗੁਰਮੁਖ ਨੇ ਜਾਣਿਆ ਹੈ ਕਿਸੇ ਵਿਰਲੇ ਨੇ ਇਹ ਰਾਜ਼ ਸਮਝਿਆ ਹੈ।", wordMeaning = "ਅਰਥਾਵੈ = ਅਰਥ ਸਮਝਦਾ ਹੈ, ਅਸਲੀਅਤ ਸਮਝਦਾ ਹੈ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-358", gurmukhi = "ਨਾਨਕੁ ਆਖੈ. ਸਚੁ ਸੁਭਾਖੈ; ਸਚਿ ਰਪੈ ਰੰਗੁ. ਕਬਹੂ, ਨ ਜਾਵੈ ॥੬੫॥", transliteration = "naanak aakhai. sach subhaakhai; sach rpai rang. kabhoo, na jaavai ||65||", translation = "Says Nanak, one who speaks the Truth is dyed in the color of Truth, which will never fade away. ||65||", hindi = "नानकु आखै. सचु सुभाखै; सचि रपै रंगु. कबहू, न जावै ॥६५॥", punjabi = "ਨਾਨਕ ਆਖਦਾ ਹੈ (ਜਿਸ ਨੇ ਸਮਝਿਆ ਹੈ) ਉਹ ਸੱਚੇ ਪ੍ਰਭੂ ਨੂੰ ਸਿਮਰਦਾ ਹੈ, ਸੱਚੇ ਵਿਚ ਰੰਗਿਆ ਰਹਿੰਦਾ ਹੈ, ਉਸ ਦਾ ਇਹ ਰੰਗ ਕਦੇ ਉਤਰਦਾ ਨਹੀਂ ॥੬੫॥", wordMeaning = "ਸਚਿ = ਸੱਚ ਵਿਚ। ਰਪੈ = ਰੰਗਿਆ ਜਾਂਦਾ ਹੈ ॥੬੫॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-359", gurmukhi = "ਜਾ ਇਹੁ ਹਿਰਦਾ ਦੇਹ. ਨ ਹੋਤੀ; ਤਉ ਮਨੁ ਕੈਠੈ ਰਹਤਾ ॥", transliteration = "jaa ih hirdaa deh. na hotee; tau man kaithai rahtaa ||", translation = "\"When this heart and body did not exist, where did the mind reside?", hindi = "जा इहु हिरदा देह. न होती; तउ मनु कैठै रहता ॥", punjabi = "(ਪ੍ਰਸ਼ਨ:) ਜਦੋਂ ਨਾਹ ਇਹ ਹਿਰਦਾ ਸੀ ਨਾਹ ਇਹ ਸਰੀਰ ਸੀ, ਤਦੋਂ ਮਨ (ਚੇਤਨ ਸੱਤਾ) ਕਿੱਥੇ ਰਹਿੰਦਾ ਸੀ?", wordMeaning = "ਦੇਹ = ਸਰੀਰ। ਮਨੁ = ਚੇਤਨ ਸੱਤਾ। ਕੈਠੈ = ਕਿਹ ਠਾਂ? ਕਿਸ ਥਾਂ ਤੇ?", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-360", gurmukhi = "ਨਾਭਿ ਕਮਲ ਅਸਥੰਭੁ. ਨ ਹੋਤੋ; ਤਾ ਪਵਨੁ ਕਵਨ ਘਰਿ ਸਹਤਾ ॥", transliteration = "naabh kamal asathambh. na hoto; taa pavan kavan ghar sahtaa ||", translation = "When there was no support of the navel lotus, then in which home did the breath reside?", hindi = "नाभि कमल असथंभु. न होतो; ता पवनु कवन घरि सहता ॥", punjabi = "ਜਦੋਂ ਨਾਭੀ ਦੇ ਚੱਕਰ ਦੀ ਥੰਮ੍ਹੀ ਨਹੀਂ ਸੀ ਤਾਂ ਪ੍ਰਾਣ (ਸੁਆਸ) ਕਿਸ ਘਰ ਵਿਚ ਆਸਰਾ ਲੈਂਦਾ ਸੀ?", wordMeaning = "ਅਸਥੰਭੁ = ਥੰਮ੍ਹੀ, ਸਹਾਰਾ {स्तम्भ}। ਪਵਨੁ = ਪ੍ਰਾਣ, ਸੁਆਸ। ਸਹਤਾ = ਆਸਰਾ ਲੈਂਦਾ ਸੀ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-361", gurmukhi = "ਰੂਪੁ ਨ ਹੋਤੋ. ਰੇਖ ਨ ਕਾਈ; ਤਾ ਸਬਦਿ ਕਹਾ ਲਿਵ ਲਾਈ ॥", transliteration = "roop na hoto. rekh na kaaee; taa sabad khaa liv laaee ||", translation = "When there was no form or shape, then how could anyone lovingly focus on the Shabad?", hindi = "रूपु न होतो. रेख न काई; ता सबदि कहा लिव लाई ॥", punjabi = "ਜਦੋਂ ਕੋਈ ਰੂਪ ਰੇਖ ਨਹੀਂ ਸੀ ਤਦੋਂ ਸ਼ਬਦ ਨੇ ਕਿਥੇ ਲਿਵ ਲਾਈ ਹੋਈ ਸੀ?", wordMeaning = "ਸਬਦਿ = ਸ਼ਬਦ ਨੇ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-362", gurmukhi = "ਰਕਤੁ ਬਿੰਦੁ ਕੀ, ਮੜੀ ਨ ਹੋਤੀ; ਮਿਤਿ ਕੀਮਤਿ. ਨਹੀ ਪਾਈ ॥", transliteration = "rakat bind kee, mree na hotee; mit keemat. nhee paaee ||", translation = "When there was no dungeon formed from egg and sperm, who could measure the Lord's value and extent?", hindi = "रकतु बिंदु की, मड़ी न होती; मिति कीमति. नही पाई ॥", punjabi = "ਜਦੋਂ (ਮਾਂ ਦੀ) ਰੱਤ ਤੇ (ਪਿਤਾ ਦੇ) ਬੀਰਜ ਤੋਂ ਬਣਿਆ ਇਹ ਸਰੀਰ ਨਹੀਂ ਸੀ ਤਦੋਂ ਜਿਸ ਪ੍ਰਭੂ ਦਾ ਅੰਦਾਜ਼ਾ ਤੇ ਮੁੱਲ ਨਹੀਂ ਪੈ ਸਕਦਾ ਉਸ ਵਿਚ ਲਿਵ ਕਿਵੇਂ ਇਹ ਮਨ ਲਾਂਦਾ ਸੀ?", wordMeaning = "ਰਕਤੁ = ਰੁੱਤ। ਬਿੰਦੁ = ਬੀਰਜ। ਮੜੀ = ਸਰੀਰ। ਮਿਤਿ = ਅੰਦਾਜ਼ਾ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-363", gurmukhi = "ਵਰਨੁ ਭੇਖੁ ਅਸਰੂਪੁ ਨ ਜਾਪੀ; ਕਿਉ ਕਰਿ ਜਾਪਸਿ ਸਾਚਾ ॥", transliteration = "varan bhekh asroop na jaapee; kiu kar jaapas saachaa ||", translation = "When color, dress and form could not be seen, how could the True Lord be known?\"", hindi = "वरनु भेखु असरूपु न जापी; किउ करि जापसि साचा ॥", punjabi = "ਜਿਸ ਪ੍ਰਭੂ ਦਾ ਰੰਗ ਭੇਖ ਤੇ ਸਰੂਪ ਨਹੀਂ ਦਿੱਸਦਾ, ਉਹ ਸਦਾ ਕਾਇਮ ਰਹਿਣ ਵਾਲਾ ਪ੍ਰਭੂ ਕਿਵੇਂ ਲਖਿਆ ਜਾਂਦਾ ਹੈ?", wordMeaning = "ਅਸਰੂਪੁ = ਸ੍ਵਰੂਪੁ, ਸਰੂਪ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-364", gurmukhi = "ਨਾਨਕ. ਨਾਮਿ ਰਤੇ ਬੈਰਾਗੀ; ਇਬ ਤਬ ਸਾਚੋ ਸਾਚਾ ॥੬੬॥", transliteration = "naanak. naam rte bairaagee; ib tab saacho saachaa ||66||", translation = "O Nanak, those who are attuned to the Naam, the Name of the Lord, are detached. Then and now, they see the Truest of the True. ||66||", hindi = "नानक. नामि रते बैरागी; इब तब साचो साचा ॥६६॥", punjabi = "(ਉੱਤਰ:) ਹੇ ਨਾਨਕ! ਪ੍ਰਭੂ ਦੇ ਨਾਮ ਵਿਚ ਰੱਤੇ ਹੋਏ ਵੈਰਾਗਵਾਨ ਨੂੰ ਹਰ ਵੇਲੇ ਸੱਚਾ ਪ੍ਰਭੂ ਹੀ (ਮੌਜੂਦ) ਪ੍ਰਤੀਤ ਹੁੰਦਾ ਹੈ ॥੬੬॥", wordMeaning = "ਇਬ = ਹੁਣ ਜਦੋਂ ਸਰੀਰ ਮੌਜੂਦ ਹੈ। ਤਬ = ਤਦੋਂ ਜਦੋਂ ਸਰੀਰ ਨਹੀਂ ਸੀ ॥੬੬॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-365", gurmukhi = "ਹਿਰਦਾ ਦੇਹ. ਨ ਹੋਤੀ, ਅਉਧੂ; ਤਉ ਮਨੁ ਸੁੰਨਿ ਰਹੈ ਬੈਰਾਗੀ ॥", transliteration = "hirdaa deh. na hotee, audhoo; tau man sunn rhai bairaagee ||", translation = "When the heart and the body did not exist, O hermit, then the mind resided in the absolute, detached Lord.", hindi = "हिरदा देह. न होती, अउधू; तउ मनु सुंनि रहै बैरागी ॥", punjabi = "(ਉੱਤਰ:) ਹੇ ਜੋਗੀ! ਜਦੋਂ ਨਾਹ ਹਿਰਦਾ ਸੀ ਨਾਹ ਸਰੀਰ ਸੀ, ਤਦੋਂ ਵੈਰਾਗੀ ਮਨ ਨਿਰਗੁਣ ਪ੍ਰਭੂ ਵਿਚ ਟਿਕਿਆ ਹੋਇਆ ਸੀ।", wordMeaning = "ਅਉਧੂ = ਹੇ ਜੋਗੀ! ਸੁੰਨਿ = ਅਫੁਰ ਪ੍ਰਭੂ ਵਿਚ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-366", gurmukhi = "ਨਾਭਿ ਕਮਲੁ ਅਸਥੰਭੁ. ਨ ਹੋਤੋ; ਤਾ ਨਿਜ ਘਰਿ ਬਸਤਉ ਪਵਨੁ ਅਨਰਾਗੀ ॥", transliteration = "naabh kamal asathambh. na hoto; taa nij ghar basatau pavan anraagee ||", translation = "When there was no support of the lotus of the navel, the breath remained in its own home, attuned to the Lord's Love.", hindi = "नाभि कमलु असथंभु. न होतो; ता निज घरि बसतउ पवनु अनरागी ॥", punjabi = "ਜਦੋਂ ਨਾਭੀ-ਚੱਕਰ-ਰੂਪ ਥੰਮੀ ਨਹੀਂ ਸੀ ਤਦੋਂ ਪ੍ਰਾਣ (ਪ੍ਰਭੂ ਦਾ) ਪ੍ਰੇਮੀ ਹੋ ਕੇ ਆਪਣੇ ਅਸਲ ਘਰ (ਪ੍ਰਭੂ) ਵਿਚ ਵੱਸਦਾ ਸੀ।", wordMeaning = "ਅਨਰਾਗੀ = ਪ੍ਰੇਮੀ ਹੋ ਕੇ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-367", gurmukhi = "ਰੂਪੁ ਨ ਰੇਖਿਆ. ਜਾਤਿ ਨ ਹੋਤੀ; ਤਉ ਅਕੁਲੀਣਿ ਰਹਤਉ. ਸਬਦੁ ਸੁ ਸਾਰੁ ॥", transliteration = "roop na rekhiaa. jaat na hotee; tau akuleen rahatau. sabad su saar ||", translation = "When there was no form or shape or social class, then the Shabad, in its essence, resided in the unmanifest Lord.", hindi = "रूपु न रेखिआ. जाति न होती; तउ अकुलीणि रहतउ. सबदु सु सारु ॥", punjabi = "ਜਦੋਂ (ਜਗਤ ਦਾ) ਕੋਈ ਰੂਪ ਰੇਖ ਨਹੀਂ ਸੀ ਤਦੋਂ ਉਹ ਸ੍ਰੇਸ਼ਟ ਸ਼ਬਦ (ਜੋ \"ਦੁਤਰ ਸਾਗਰ\" ਤੋਂ ਤਾਰਦਾ ਹੈ) ਕੁਲ-ਰਹਿਤ ਪ੍ਰਭੂ ਵਿਚ ਰਹਿੰਦਾ ਸੀ;", wordMeaning = "ਜਾਤਿ = ਹੋਂਦ, ਉਤਪੱਤੀ। ਅਕੁਲੀਣਿ = ਅਕੁਲੀਣ ਵਿਚ, ਕੁਲ-ਰਹਿਤ ਪ੍ਰਭੂ ਵਿਚ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-368", gurmukhi = "ਗਉਨੁ ਗਗਨੁ ਜਬ ਤਬਹਿ. ਨ ਹੋਤਉ; ਤ੍ਰਿਭਵਣ ਜੋਤਿ ਆਪੇ ਨਿਰੰਕਾਰੁ ॥", transliteration = "gaun gagan jab tabah. na hotau; tribhavan jot aape nirankaar ||", translation = "When the world and the sky did not even exist, the Light of the Formless Lord filled the three worlds.", hindi = "गउनु गगनु जब तबहि. न होतउ; त्रिभवण जोति आपे निरंकारु ॥", punjabi = "ਜਦੋਂ ਜਗਤ ਦੀ ਹਸਤੀ ਨਹੀਂ ਸੀ, ਅਕਾਸ਼ ਨਹੀਂ ਸੀ, ਤਦੋਂ ਆਕਾਰ-ਰਹਿਤ ਤ੍ਰਿਭਵਣੀ ਜੋਤਿ (ਭਾਵ, ਹੁਣ ਤ੍ਰਿਲੋਕੀ ਵਿਚ ਵਿਆਪਕ ਹੋਣ ਵਾਲੀ ਜੋਤਿ) ਆਪ ਹੀ ਆਪ ਸੀ।", wordMeaning = "ਗਉਨੁ = ਗਵਨੁ, ਗਮਨ, ਚਾਲ, ਜਗਤ ਦੀ ਚਾਲ, ਜਗਤ ਦੀ ਹੋਂਦ। ਗਗਨੁ = ਅਕਾਸ਼।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-369", gurmukhi = "ਵਰਨੁ ਭੇਖੁ. ਅਸਰੂਪੁ ਸੁ ਏਕੋ; ਏਕੋ ਸਬਦੁ ਵਿਡਾਣੀ ॥", transliteration = "varan bhekh. asroop su eko; eko sabad vidaanee ||", translation = "Color, dress and form were contained in the One Lord; the Shabad was contained in the One, Wondrous Lord.", hindi = "वरनु भेखु. असरूपु सु एको; एको सबदु विडाणी ॥", punjabi = "ਇਕੋ ਅਸਚਰਜ ਸ਼ਬਦ-ਰੂਪ ਪ੍ਰਭੂ ਹੀ ਸੀ, ਉਹੀ (ਜਗਤ ਦਾ) ਰੰਗ ਭੇਖ ਤੇ ਰੂਪ ਸੀ।", wordMeaning = "ਵਿਡਾਣੀ = ਅਸਚਰਜ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-370", gurmukhi = "ਸਾਚ ਬਿਨਾ. ਸੂਚਾ ਕੋ ਨਾਹੀ; ਨਾਨਕ ਅਕਥ ਕਹਾਣੀ ॥੬੭॥", transliteration = "saach binaa. soochaa ko naahee; naanak akath khaanee ||67||", translation = "Without the True Name, no one can become pure; O Nanak, this is the Unspoken Speech. ||67||", hindi = "साच बिना. सूचा को नाही; नानक अकथ कहाणी ॥६७॥", punjabi = "ਹੇ ਨਾਨਕ! (ਐਸੇ ਉਸ) ਸਦਾ ਕਾਇਮ ਰਹਿਣ ਵਾਲੇ ਪ੍ਰਭੂ (ਨੂੰ ਮਿਲਣ) ਤੋਂ ਬਿਨਾ, ਜਿਸ ਦਾ ਕੋਈ ਸਹੀ ਸਰੂਪ ਬਿਆਨ ਨਹੀਂ ਕੀਤਾ ਜਾ ਸਕਦਾ, ਕੋਈ ਮਨੁੱਖ ਸੁੱਚਾ ਨਹੀਂ ਹੈ ॥੬੭॥", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-371", gurmukhi = "ਕਿਤੁ ਕਿਤੁ ਬਿਧਿ ਜਗੁ ਉਪਜੈ ਪੁਰਖਾ; ਕਿਤੁ ਕਿਤੁ ਦੁਖਿ ਬਿਨਸਿ ਜਾਈ ॥", transliteration = "kit kit bidh jag upjai purkhaa; kit kit dukh binas jaaee ||", translation = "\"How, in what way, was the world formed, O man? And what disaster will end it?\"", hindi = "कितु कितु बिधि जगु उपजै पुरखा; कितु कितु दुखि बिनसि जाई ॥", punjabi = "(ਪ੍ਰਸ਼ਨ:) ਹੇ ਪੁਰਖ! ਜਗਤ ਕਿਸ ਕਿਸ ਵਿਧੀ ਨਾਲ ਉਪਜਦਾ ਹੈ, ਕਿਸ ਤਰ੍ਹਾਂ ਦੁੱਖ ਵਿਚ (ਪੈਂਦਾ) ਹੈ ਤੇ ਕਿਵੇਂ ਨਾਸ ਹੋ ਜਾਂਦਾ ਹੈ?", wordMeaning = "ਕਿਤੁ = ਕਿਸ ਨਾਲ? ਕਿਤੁ ਬਿਧਿ = ਕਿਸ ਵਿਧੀ ਨਾਲ? ਪੁਰਖਾ = ਹੇ ਪੁਰਖ! ਦੁਖਿ = ਦੁੱਖ ਨਾਲ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-372", gurmukhi = "ਹਉਮੈ ਵਿਚਿ ਜਗੁ ਉਪਜੈ ਪੁਰਖਾ; ਨਾਮਿ ਵਿਸਰਿਐ ਦੁਖੁ ਪਾਈ ॥", transliteration = "haumai vich jag upjai purkhaa; naam visriai dukh paaee ||", translation = "In egotism, the world was formed, O man; forgetting the Naam, it suffers and dies.", hindi = "हउमै विचि जगु उपजै पुरखा; नामि विसरिऐ दुखु पाई ॥", punjabi = "(ਉੱਤਰ:) ਹੇ ਪੁਰਖ! ਜਗਤ ਹਉਮੈ ਵਿਚ ਪੈਦਾ ਹੁੰਦਾ ਹੈ, ਜੇ (ਇਸ ਨੂੰ) ਪ੍ਰਭੂ ਦਾ ਨਾਮ ਵਿੱਸਰ ਜਾਏ ਤਾਂ ਦੁੱਖ ਪਾਂਦਾ ਹੈ।", wordMeaning = "ਹਉਮੈ = ਵੱਖਰਾ-ਪਨ, ਮੇਰ-ਤੇਰ, ਆਪਣੀ ਵੱਖਰੀ ਹੋਂਦ ਦਾ ਖ਼ਿਆਲ। ਨਾਮਿ ਵਿਸਰਿਐ = ਜੇ ਨਾਮ ਵਿੱਸਰ ਜਾਏ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-373", gurmukhi = "ਗੁਰਮੁਖਿ ਹੋਵੈ. ਸੁ ਗਿਆਨੁ ਤਤੁ ਬੀਚਾਰੈ; ਹਉਮੈ ਸਬਦਿ ਜਲਾਏ ॥", transliteration = "gurmukh hovai. su giaan tat beechaarai; haumai sabad jlaae ||", translation = "One who becomes Gurmukh contemplates the essence of spiritual wisdom; through the Shabad, he burns away his egotism.", hindi = "गुरमुखि होवै. सु गिआनु ततु बीचारै; हउमै सबदि जलाए ॥", punjabi = "ਜੋ ਮਨੁੱਖ ਗੁਰੂ ਦੇ ਹੁਕਮ ਵਿਚ ਤੁਰਦਾ ਹੈ, ਉਹ ਤੱਤ-ਗਿਆਨ ਨੂੰ ਵਿਚਾਰਦਾ ਹੈ ਤੇ (ਆਪਣੀ) ਹਉਮੈ ਗੁਰੂ ਦੇ ਸ਼ਬਦ ਦੀ ਰਾਹੀਂ ਸਾੜਦਾ ਹੈ,", wordMeaning = "ਸਬਦਿ = ਗੁਰ-ਸ਼ਬਦ ਦੀ ਰਾਹੀਂ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-374", gurmukhi = "ਤਨੁ ਮਨੁ ਨਿਰਮਲੁ ਨਿਰਮਲ ਬਾਣੀ; ਸਾਚੈ ਰਹੈ ਸਮਾਏ ॥", transliteration = "tan man niramal niramal baanee; saachai rhai smaae ||", translation = "His body and mind become immaculate, through the Immaculate Bani of the Word. He remains absorbed in Truth.", hindi = "तनु मनु निरमलु निरमल बाणी; साचै रहै समाए ॥", punjabi = "ਉਸ ਦਾ ਤਨ ਉਸ ਦਾ ਮਨ ਤੇ ਉਸ ਦੀ ਬਾਣੀ ਪਵਿਤ੍ਰ ਹੋ ਜਾਂਦੇ ਹਨ; ਉਹ ਸਦਾ ਕਾਇਮ ਰਹਿਣ ਵਾਲੇ ਪ੍ਰਭੂ ਵਿਚ ਟਿਕਿਆ ਰਹਿੰਦਾ ਹੈ।", wordMeaning = "ਸਾਚੈ = ਸੱਚੇ ਪ੍ਰਭੂ ਵਿਚ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-375", gurmukhi = "ਨਾਮੇ ਨਾਮਿ ਰਹੈ ਬੈਰਾਗੀ; ਸਾਚੁ ਰਖਿਆ ਉਰਿ ਧਾਰੇ ॥", transliteration = "naame naam rhai bairaagee; saach rkhiaa ur dhaare ||", translation = "Through the Naam, the Name of the Lord, he remains detached; he enshrines the True Name in his heart.", hindi = "नामे नामि रहै बैरागी; साचु रखिआ उरि धारे ॥", punjabi = "ਉਹ ਮਨੁੱਖ (ਪ੍ਰਭੂ-ਚਰਨਾਂ ਦਾ) ਮਤਵਾਲਾ ਹੋ ਕੇ ਨਿਰੋਲ ਪ੍ਰਭੂ-ਨਾਮ ਵਿਚ ਹੀ ਜੁੜਿਆ ਰਹਿੰਦਾ ਹੈ, ਸਦਾ ਪ੍ਰਭੂ ਨੂੰ ਹਿਰਦੇ ਵਿਚ ਟਿਕਾਈ ਰੱਖਦਾ ਹੈ।", wordMeaning = "ਨਾਮੇ ਨਾਮਿ = ਨਾਮਿ ਹੀ ਨਾਮਿ, ਨਾਮ ਹੀ ਨਾਮ ਵਿਚ, ਨਿਰੋਲ ਪ੍ਰਭੂ-ਨਾਮ ਵਿਚ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-376", gurmukhi = "ਨਾਨਕ ਬਿਨੁ ਨਾਵੈ. ਜੋਗੁ ਕਦੇ, ਨ ਹੋਵੈ; ਦੇਖਹੁ ਰਿਦੈ ਬੀਚਾਰੇ ॥੬੮॥", transliteration = "naanak bin naavai. jog kde, na hovai; dekhah ridai beechaare ||68||", translation = "O Nanak, without the Name, Yoga is never attained; reflect upon this in your heart, and see. ||68||", hindi = "नानक बिनु नावै. जोगु कदे, न होवै; देखहु रिदै बीचारे ॥६८॥", punjabi = "ਹੇ ਨਾਨਕ! ਪ੍ਰਭੂ ਦੇ ਨਾਮ ਤੋਂ ਬਿਨਾ ਪ੍ਰਭੂ ਨਾਲ ਮਿਲਾਪ ਕਦੇ ਨਹੀਂ ਹੋ ਸਕਦਾ, ਆਪਣੇ ਹਿਰਦੇ ਵਿਚ ਵਿਚਾਰ ਕੇ ਵੇਖ ਲਵੋ (ਭਾਵ, ਤੁਹਾਡਾ ਆਪਣਾ ਜ਼ਾਤੀ ਤਜਰਬਾ ਇਹੀ ਗਵਾਹੀ ਦੇਵੇਗਾ) ॥੬੮॥", wordMeaning = "ਜੋਗੁ = ਮਿਲਾਪ ॥੬੮॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-377", gurmukhi = "ਗੁਰਮੁਖਿ; ਸਾਚੁ ਸਬਦੁ ਬੀਚਾਰੈ ਕੋਇ ॥", transliteration = "gurmukh; saach sabad beechaarai koi ||", translation = "The Gurmukh is one who reflects upon the True Word of the Shabad.", hindi = "गुरमुखि; साचु सबदु बीचारै कोइ ॥", punjabi = "ਜੇ ਕੋਈ ਮਨੁੱਖ ਗੁਰੂ ਦੇ ਹੁਕਮ ਵਿਚ ਤੁਰਦਾ ਹੈ ਉਹ ਸੱਚੇ ਸ਼ਬਦ ਨੂੰ ਵਿਚਾਰਦਾ ਹੈ,", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-378", gurmukhi = "ਗੁਰਮੁਖਿ; ਸਚੁ ਬਾਣੀ ਪਰਗਟੁ ਹੋਇ ॥", transliteration = "gurmukh; sach baanee paragat hoi ||", translation = "The True Bani is revealed to the Gurmukh.", hindi = "गुरमुखि; सचु बाणी परगटु होइ ॥", punjabi = "ਸਤਿਗੁਰੂ ਦੀ ਬਾਣੀ ਦੀ ਰਾਹੀਂ ਸੱਚਾ ਪ੍ਰਭੂ (ਉਸ ਦੇ ਹਿਰਦੇ ਵਿਚ) ਪਰਗਟ ਹੋ ਜਾਂਦਾ ਹੈ।", wordMeaning = "ਬਾਣੀ = ਗੁਰੂ ਦੀ ਬਾਣੀ ਦੀ ਰਾਹੀਂ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-379", gurmukhi = "ਗੁਰਮੁਖਿ ਮਨੁ ਭੀਜੈ; ਵਿਰਲਾ ਬੂਝੈ ਕੋਇ ॥", transliteration = "gurmukh man bheejai; virlaa boojhai koi ||", translation = "The mind of the Gurmukh is drenched with the Lord's Love, but how rare are those who understand this.", hindi = "गुरमुखि मनु भीजै; विरला बूझै कोइ ॥", punjabi = "ਗੁਰਮੁਖਿ ਮਨੁੱਖ ਦਾ ਮਨ (ਨਾਮ-ਰਸ ਵਿਚ) ਭਿੱਜਦਾ ਹੈ, (ਪਰ ਇਸ ਗੱਲ ਨੂੰ) ਕੋਈ ਵਿਰਲਾ ਸਮਝਦਾ ਹੈ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-380", gurmukhi = "ਗੁਰਮੁਖਿ; ਨਿਜ ਘਰਿ ਵਾਸਾ ਹੋਇ ॥", transliteration = "gurmukh; nij ghar vaasaa hoi ||", translation = "The Gurmukh dwells in the home of the self, deep within.", hindi = "गुरमुखि; निज घरि वासा होइ ॥", punjabi = "ਗੁਰੂ ਦੇ ਸਨਮੁਖ ਮਨੁੱਖ ਦਾ ਨਿਵਾਸ ਆਪਣੇ ਅਸਲ ਸਰੂਪ ਵਿਚ ਹੋਇਆ ਰਹਿੰਦਾ ਹੈ।", wordMeaning = "ਨਿਜ ਘਰਿ = ਆਪਣੇ ਅਸਲ ਸਰੂਪ ਵਿਚ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-381", gurmukhi = "ਗੁਰਮੁਖਿ ਜੋਗੀ; ਜੁਗਤਿ ਪਛਾਣੈ ॥", transliteration = "gurmukh jogee; jugat pchhaanai ||", translation = "The Gurmukh realizes the Way of Yoga.", hindi = "गुरमुखि जोगी; जुगति पछाणै ॥", punjabi = "ਜੋ ਮਨੁੱਖ ਸਤਿਗੁਰੂ ਦੇ ਹੁਕਮ ਵਿਚ ਤੁਰਦਾ ਹੈ ਉਹੀ (ਅਸਲ) ਜੋਗੀ ਹੈ ਉਹ (ਪ੍ਰਭੂ ਨਾਲ ਮਿਲਾਪ ਦੀ) ਜੁਗਤਿ ਪਛਾਣਦਾ ਹੈ।", wordMeaning = "ਜੁਗਤਿ = ਜੋਗ ਦੀ ਜੁਗਤਿ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-382", gurmukhi = "ਗੁਰਮੁਖਿ ਨਾਨਕ; ਏਕੋ ਜਾਣੈ ॥੬੯॥", transliteration = "gurmukh naanak; eko jaanai ||69||", translation = "O Nanak, the Gurmukh knows the One Lord alone. ||69||", hindi = "गुरमुखि नानक; एको जाणै ॥६९॥", punjabi = "ਹੇ ਨਾਨਕ! ਗੁਰੂ ਦੇ ਹੁਕਮ ਵਿਚ ਤੁਰਨ ਵਾਲਾ ਮਨੁੱਖ ਇੱਕ ਪ੍ਰਭੂ ਨੂੰ (ਹਰ ਥਾਂ ਵਿਆਪਕ) ਜਾਣਦਾ ਹੈ ॥੬੯॥", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-383", gurmukhi = "ਬਿਨੁ ਸਤਿਗੁਰ ਸੇਵੇ; ਜੋਗੁ. ਨ ਹੋਈ ॥", transliteration = "bin stigur seve; jog. na hoee ||", translation = "Without serving the True Guru, Yoga is not attained;", hindi = "बिनु सतिगुर सेवे; जोगु. न होई ॥", punjabi = "ਸਤਿਗੁਰੂ ਦੀ ਦੱਸੀ ਕਾਰ ਕਰਨ ਤੋਂ ਬਿਨਾ (ਪ੍ਰਭੂ ਨਾਲ) ਮੇਲ ਨਹੀਂ ਹੁੰਦਾ,", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
