    BaniLine(id = "sidha-gosht-400", gurmukhi = "ਕਰਿ ਬੀਚਾਰੁ ਮਨਿ ਦੇਖਹੁ ਨਾਨਕ; ਬਿਨੁ ਨਾਵੈ ਮੁਕਤਿ. ਨ ਹੋਈ ॥੭੨॥", transliteration = "kar beechaar man dekhah naanak; bin naavai mukat. na hoee ||72||", translation = "Reflect upon this in your mind, and see; O Nanak, without the Name, there is no liberation. ||72||", hindi = "करि बीचारु मनि देखहु नानक; बिनु नावै मुकति. न होई ॥७२॥", punjabi = "ਹੇ ਨਾਨਕ! ਮਨ ਵਿਚ ਵਿਚਾਰ ਕਰ ਕੇ ਵੇਖ ਲਵੋ, 'ਨਾਮ' ਤੋਂ ਬਿਨਾ ਮੁਕਤੀ ਨਹੀਂ ਮਿਲਦੀ (ਭਾਵ, ਤੁਹਾਡਾ ਆਪਣਾ ਜ਼ਾਤੀ ਤਜਰਬਾ ਦੱਸ ਦੇਵੇਗਾ ਕਿ ਨਾਮ ਸਿਮਰਨ ਤੋਂ ਬਿਨਾ ਹਉਮੈ ਤੋਂ ਖ਼ਲਾਸੀ ਨਹੀਂ ਹੁੰਦੀ)।੭੨)॥੭੨॥", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-401", gurmukhi = "ਤੇਰੀ ਗਤਿ ਮਿਤਿ ਤੂਹੈ ਜਾਣਹਿ; ਕਿਆ ਕੋ ਆਖਿ ਵਖਾਣੈ ॥", transliteration = "teree gat mit toohai jaanah; kiaa ko aakh vkhaanai ||", translation = "You alone know Your state and extent, Lord; What can anyone say about it?", hindi = "तेरी गति मिति तूहै जाणहि; किआ को आखि वखाणै ॥", punjabi = "ਤੂੰ ਕਿਹੋ ਜਿਹਾ ਹੈਂ ਤੇ ਕੇਡਾ ਵੱਡਾ ਹੈਂ, ਹੇ ਪ੍ਰਭੂ! ਇਹ ਗੱਲ ਤੂੰ ਆਪ ਹੀ ਜਾਣਦਾ ਹੈ। ਕੋਈ ਹੋਰ ਕੀਹ ਕਹਿ ਕੇ ਦੱਸ ਸਕਦਾ ਹੈ?", wordMeaning = "ਗਤਿ = ਹਾਲਤ। ਮਿਤਿ = ਮਿਣਤੀ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-402", gurmukhi = "ਤੂ ਆਪੇ ਗੁਪਤਾ. ਆਪੇ ਪਰਗਟੁ; ਆਪੇ ਸਭਿ ਰੰਗ ਮਾਣੈ ॥", transliteration = "too aape guptaa. aape paragat; aape sabh rang maanai ||", translation = "You Yourself are hidden, and You Yourself are revealed. You Yourself enjoy all pleasures.", hindi = "तू आपे गुपता. आपे परगटु; आपे सभि रंग माणै ॥", punjabi = "ਤੂੰ ਆਪ ਹੀ ਲੁਕਿਆ ਹੋਇਆ ਹੈਂ ਤੂੰ ਆਪ ਹੀ ਪਰਗਟ ਹੈਂ (ਭਾਵ, ਸੂਖਮ ਤੇ ਅਸਥੂਲ ਤੂੰ ਆਪ ਹੀ ਹੈਂ), ਤੂੰ ਆਪ ਹੀ ਸਾਰੇ ਰੰਗ ਮਾਣ ਰਿਹਾ ਹੈਂ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-403", gurmukhi = "ਸਾਧਿਕ ਸਿਧ ਗੁਰੂ ਬਹੁ ਚੇਲੇ; ਖੋਜਤ ਫਿਰਹਿ ਫੁਰਮਾਣੈ ॥", transliteration = "saadhik sidh guroo bah chele; khojat phirah phurmaanai ||", translation = "The seekers, the Siddhas, the many gurus and disciples wander around searching for You, according to Your Will.", hindi = "साधिक सिध गुरू बहु चेले; खोजत फिरहि फुरमाणै ॥", punjabi = "ਸਾਧਨ ਕਰਨ ਵਾਲੇ ਤੇ ਸਾਧਨਾਂ ਵਿਚ ਪੁੱਗੇ ਹੋਏ ਜੋਗੀ, ਗੁਰੂ ਤੇ ਉਹਨਾਂ ਦੇ ਕਈ ਚੇਲੇ ਤੇਰੇ ਹੁਕਮ ਵਿਚ ਤੈਨੂੰ ਖੋਜਦੇ ਫਿਰਦੇ ਹਨ,", wordMeaning = "ਸਾਧਿਕ = ਸਾਧਨ ਕਰਨ ਵਾਲੇ। ਸਿਧ = ਜੋਗ-ਸਾਧਨਾਂ ਵਿਚ ਪੁੱਗੇ ਹੋਏ ਜੋਗੀ। ਫੁਰਮਾਣੈ = ਫੁਰਮਾਨ ਵਿਚ ਹੀ, ਤੇਰੇ ਹੁਕਮ ਵਿਚ ਹੀ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-404", gurmukhi = "ਮਾਗਹਿ ਨਾਮੁ, ਪਾਇ ਇਹ ਭਿਖਿਆ; ਤੇਰੇ ਦਰਸਨ ਕਉ ਕੁਰਬਾਣੈ ॥", transliteration = "maagah naam, paai ih bhikhiaa; tere darasan kau kurbaanai ||", translation = "They beg for Your Name, and You bless them with this charity. I am a sacrifice to the Blessed Vision of Your Darshan.", hindi = "मागहि नामु, पाइ इह भिखिआ; तेरे दरसन कउ कुरबाणै ॥", punjabi = "ਤੈਥੋਂ ਤੇਰਾ 'ਨਾਮ' ਮੰਗਦੇ ਹਨ, ਤੈਥੋਂ ਇਹ ਭਿੱਖਿਆ ਲੈ ਕੇ ਤੇਰੇ ਦੀਦਾਰ ਤੋਂ ਸਦਕੇ ਹੁੰਦੇ ਹਨ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-405", gurmukhi = "ਅਬਿਨਾਸੀ ਪ੍ਰਭਿ ਖੇਲੁ ਰਚਾਇਆ; ਗੁਰਮੁਖਿ ਸੋਝੀ ਹੋਈ ॥", transliteration = "abinaasee prabh khel rchaaiaa; gurmukh sojhee hoee ||", translation = "The eternal imperishable Lord God has staged this play; the Gurmukh understands it.", hindi = "अबिनासी प्रभि खेलु रचाइआ; गुरमुखि सोझी होई ॥", punjabi = "ਅਬਿਨਾਸੀ ਪ੍ਰਭੂ ਨੇ (ਇਹ ਜਗਤ ਦੀ) ਖੇਡ ਰਚੀ ਹੈ ਗੁਰਮੁਖ ਮਨੁੱਖ ਨੂੰ ਇਹ ਸਮਝ ਪੈਂਦੀ ਹੈ।", wordMeaning = "ਪ੍ਰਭਿ = ਪ੍ਰਭੂ ਨੇ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "sidha-gosht-406", gurmukhi = "ਨਾਨਕ. ਸਭਿ ਜੁਗ ਆਪੇ ਵਰਤੈ; ਦੂਜਾ ਅਵਰੁ. ਨ ਕੋਈ ॥੭੩॥੧॥", transliteration = "naanak. sabh jug aape vartai; doojaa avar. na koee ||73||1||", translation = "O Nanak, He extends Himself throughout the ages; there is no other than Him. ||73||1||", hindi = "नानक. सभि जुग आपे वरतै; दूजा अवरु. न कोई ॥७३॥१॥", punjabi = "ਹੇ ਨਾਨਕ! ਸਾਰੇ ਹੀ ਜੁਗਾਂ ਵਿਚ ਉਹ ਆਪ ਹੀ ਮੌਜੂਦ ਹੈ, ਕੋਈ ਹੋਰ ਦੂਜਾ (ਉਸ ਵਰਗਾ) ਨਹੀਂ ॥੭੩॥੧॥", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L)
)
